def _reexec_if_old() -> None:
    if sys.version_info >= (3, 11):
        return
    if sys.argv[0] == "-":
        sys.stderr.write("land_gate_test: cannot restart consumed stdin; use Python >= 3.11\n")
        sys.exit(2)
    original = getattr(sys, "orig_argv", None)
    if original:
        arguments = original[1:]
    else:
        main = sys.modules.get("__main__")
        spec = getattr(main, "__spec__", None)
        entry = getattr(main, "__file__", None)
        if spec is not None:
            arguments = ["-m", spec.name, *sys.argv[1:]]
        elif entry and sys.argv[0] not in ("-", "-c"):
            arguments = [entry, *sys.argv[1:]]
        else:
            sys.stderr.write("land_gate_test: cannot restart consumed stdin/-c; use Python >= 3.11\n")
            sys.exit(2)
        if sys.dont_write_bytecode:
            arguments.insert(0, "-B")
    for cand in ("python3.14", "python3.13", "python3.12", "python3.11"):
        path = shutil.which(cand)
        if path:
            os.execv(path, [path, *arguments])
    sys.stderr.write("land_gate_test: needs Python >= 3.11\n")
    sys.exit(2)


_reexec_if_old()

