_REAL_POPEN = subprocess.Popen


def fixture_leg_process(command, **kwargs):
    # Use actual waitable/pipe-owning children at the process boundary. Keep
    # readonly group observers real as well; never start the selected compiler.
    actual = [sys.executable, '-c', 'pass'] if kwargs.get('start_new_session') else command
    return _REAL_POPEN(actual, **kwargs)


def selected_spawn_call(spawn):
    calls = [call for call in spawn.call_args_list if call.kwargs.get('start_new_session')]
    if len(calls) != 1:
        raise AssertionError(f'expected one selected leg spawn, got {calls!r}')
    return calls[0]



def stated(changed=(), head: str = "", tip: str = "base") -> "land_gate.LandingRange":
    """A landing push that can be stated (round 3): `head` (the fixture's)
    contains origin's main `tip`, and the push changes `changed`. Tests of
    plan, run and key use it in place of read_landing."""
    return land_gate.LandingRange(tip, head or Fixture.rev, "", True, tuple(changed), "")


# No test reads the real origin (the network, and a tip that moves under the
# suite): a test of plan or run on this checkout mocks read_landing, and one
# that forgets gets a landing that cannot be stated, so it fails visibly.
_REMOTE_MAIN_TIP = land_gate.remote_main_tip


def _hermetic_remote_main_tip(root, env):
    if Path(root).resolve() == REPO.resolve():
        raise land_gate.LandingUnjudged("land_gate_test reads no real origin (mock read_landing)")
    return _REMOTE_MAIN_TIP(root, env)


land_gate.remote_main_tip = _hermetic_remote_main_tip


def setUpModule():
    # These synthetic repositories exercise the original Python checkout
    # workers. Never acquire a real installed SDK just to start their pool.
    # Native admission/protocol and actual reader execution have their own
    # native_checkout_test.py and native_checkout_inputs.rs controls.
    managed = mock.patch.object(
        land_gate.native_checkout, "managed_program",
        side_effect=land_gate.native_checkout.Unavailable(
            "synthetic gate fixture has no installed native reader"),
    )
    managed.start()
    unittest.addModuleCleanup(managed.stop)


def load_crates_lane():
    """scripts/check_crates_tests_scoped.py, the lane the crates leg runs (it is
    a script, not a module on the path)."""
    import importlib.util
    spec = importlib.util.spec_from_file_location("check_crates_tests_scoped",
                                                  REPO / "scripts" / "check_crates_tests_scoped.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

