        for path in ("scripts/luminal_domination.py", "scripts/tests/luminal_domination_test.py", ledger):
            with self.subTest(path=path):
                g = Fixture.graph()
                self.assertEqual(ls.classify(g, path)[0], "validation")
                selection = ls.select(g, "base", [path])
                self.assertFalse(selection.everything)
                for leg_id in ("compiler-check", "ui-trust", "run-make-trust"):
                    self.assertFalse(selection.decisions[leg_id].selected, leg_id)
                self.assertEqual(ls.validation_test_modules([path]), [module])
                if path == ledger:
                    # build_legs asks the crates lane's instrument hosts of a non-script
                    # path, and the fixture graph has no crates/ member to answer with.
                    continue
                for hook in (HOOK_ON, HOOK_OFF):
                    leg = next(leg for leg in land_gate.build_legs(g, selection, "base", plans, hook)
                               if leg.id == "validation-tests")
                    self.assertTrue(leg.selected)
                    self.assertTrue(leg.force_run)
                    self.assertEqual(leg.command[4:], [module])
        for path in ("tests/luminal-domination/other.json", "tests/luminal-domination/capabilities.json.bak",
                     "tests/luminal-domination/sub/capabilities.json", "scripts/luminal_domination.py.orig"):
            with self.subTest(path=path):
                g = Fixture.graph()
                self.assertIn(ls.classify(g, path)[0], ("unmapped", "everything"))
                self.assertTrue(ls.select(g, "base", [path]).everything)
        # The tests also hold the ledger to the plan's PKG-U rows and to the manifest
        # row's pins, so an edit to either file re-runs them (additively: the
        # manifest keeps its every-leg rule).
        for path in ("docs/PLAN.md", "tests/run_trust_comprehensive_harness.sh"):
            with self.subTest(path=path):
                self.assertIn(module, ls.validation_test_modules([path]))
        g = Fixture.graph()
        g.packages["compiler/rustc_a"].reads.append(ls.Read("compile", ledger, False, "fixture include"))
        selection = ls.select(g, "base", [ledger])
        self.assertTrue(selection.decisions["compiler-check"].selected)
        self.assertTrue(selection.per_crate["compiler-unit-tests"]["compiler/rustc_a"].selected)

