    def test_declared_validation_tests_are_real_files(self):
        # Declarations may select a whole module or an actual test class
        # within it. Resolve the same dotted selector the runner consumes
        # rather than treating a class as a file. Load them in a separate
        # interpreter, as the runner does: importing every declared module into
        # this one left repository modules no gate import bound (the soundness
        # corpus test execs its script into sys.modules), so each later
        # in-process discovery refused as an unbound loaded reader.
        declared = sorted({module for modules in ls.VALIDATION_PROGRAM_TESTS.values() for module in modules})
        for modules in ls.VALIDATION_PROGRAM_TESTS.values():
            self.assertTrue(modules)
        code = ("import json, sys, unittest\n"
                "sys.path[:] = json.loads(sys.argv[1])\n"
                "rows = {}\n"
                "for module in sys.argv[2:]:\n"
                "    loader = unittest.TestLoader()\n"
                "    suite = loader.loadTestsFromName(module)\n"
                "    rows[module] = [[str(error) for error in loader.errors], suite.countTestCases()]\n"
                "sys.stdout.write('\\nDECLARED-VALIDATION-TESTS ' + json.dumps(rows) + '\\n')\n")
        # Match the runner's sibling-import path too: several real test
        # modules import another scripts/tests module bare.
        path = [str(REPO / "scripts/tests"), *sys.path]
        proc = subprocess.run([sys.executable, "-B", "-c", code, json.dumps(path), *declared],
                              cwd=REPO, capture_output=True, text=True, timeout=600)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        rows = json.loads(proc.stdout.rsplit("\nDECLARED-VALIDATION-TESTS ", 1)[1])
        self.assertEqual(sorted(rows), declared)
        for module in declared:
            errors, count = rows[module]
            self.assertEqual(errors, [], module)
            self.assertGreater(count, 0, module)

    # LAND-SELECT-VALIDATION-REACH-1: no scripts/tests module is out of the
    # validation-tests leg's reach. Until 2026-11-10 no changed path selected
    # 156 of the 175 modules (scripts.tests.resource_fds_test among them).
    @staticmethod
    def script_test_modules():
        listed = subprocess.run(["git", "-C", str(REPO), "ls-files", "-z", "--", "scripts/tests/*_test.py"],
                                capture_output=True, text=True, check=True, timeout=60).stdout
        return sorted("scripts.tests." + path[len("scripts/tests/"):-len(".py")]
                      for path in listed.split("\0") if path and path.count("/") == 2)

    @staticmethod
    def tracked_paths():
        listed = subprocess.run(["git", "-C", str(REPO), "ls-files", "-z"],
                                capture_output=True, text=True, check=True, timeout=60).stdout
        return [path for path in listed.split("\0") if path]

    @staticmethod
    def unselected(modules, paths):
        """The modules no path in `paths` makes the selector run, less the
        declared exceptions (asked of the selector itself, one changed set)."""
        selected = set(ls.validation_test_modules(paths))
        return [module for module in modules
                if module not in selected and module not in ls.VALIDATION_UNJUDGED_MODULES
                and module not in ls.VALIDATION_UNMAPPED_RED]

    def test_every_script_test_module_is_selected_by_some_changed_path(self):
        modules, paths = self.script_test_modules(), self.tracked_paths()
        # The instrument: the listing found the suite, and the declared rows exist.
        self.assertIn("scripts.tests.land_gate_test", modules)
        self.assertIn("scripts.tests.check_frozen_source_reader_test", modules)
        self.assertEqual(self.unselected(modules, paths), [])
        # Positive control: a module nothing maps is reported, and a mapping
        # (here an injected one) is what makes it selected.
        control, subject = "scripts.tests.zz_reach_control_test", "scripts/zz_reach_control.py"
        self.assertEqual(self.unselected([*modules, control], paths), [control])
        with mock.patch.dict(ls.VALIDATION_TEST_SUBJECTS, {subject: (control,)}):
            self.assertEqual(self.unselected([*modules, control], [*paths, subject]), [])
        self.assertNotIn(subject, ls.VALIDATION_TEST_SUBJECTS)
        # The finding that opened this: its imported transport selects it.
        self.assertIn("scripts.tests.resource_fds_test", ls.validation_test_modules(["scripts/lib/landing_targo.py"]))
        # 136c65d7e3 added the lattice reader's Git-isolation counterexamples
        # with no subject: the reader they load by path must select them.
        self.assertIn("scripts.tests.pin_lattice_git_isolation_test",
                      ls.validation_test_modules(["scripts/check_first_party_pin_lattice.py"]))
        for subject in ("scripts/check_frozen_files.sh", "scripts/tests/check_frozen_source_reader_test.py"):
            self.assertIn("scripts.tests.check_frozen_source_reader_test", ls.validation_test_modules([subject]))

