    # The row table (gates/land.toml, PKG-LIVE-4): the one source of the four
    # tables above, the rules its reader refuses to load without, and how a
    # change to the table itself is selected.
    ROWS = {"alpha_test": ["scripts/alpha.py", "scripts/tests/alpha_test.py"],
            "beta_test": ["scripts/alpha.py", "scripts/tests/beta_test.py", "x.py"]}
    PROGRAMS = {"scripts/alpha.py": ["beta_test", "alpha_test"], "scripts/tests/alpha_test.py": ["alpha_test"]}
    NOT_RUN = [("delta_test", "unjudgeable", "argparse driver: fixture"), ("gamma_test", "red", "1 FAIL: fixture")]

    def test_row_table_builds_the_four_selector_tables(self):
        table = ls.parse_land_rows(land_rows_text(self.ROWS, self.PROGRAMS, self.NOT_RUN))
        # A validation program reports its rows in the order it lists them; every
        # other selecting path is a subject, its modules sorted.
        self.assertEqual(table.program_tests, {
            "scripts/alpha.py": ("scripts.tests.beta_test", "scripts.tests.alpha_test"),
            "scripts/tests/alpha_test.py": ("scripts.tests.alpha_test",)})
        self.assertEqual(list(table.program_tests), ["scripts/alpha.py", "scripts/tests/alpha_test.py"])
        self.assertEqual(table.test_subjects, {"scripts/tests/beta_test.py": ("scripts.tests.beta_test",),
                                               "x.py": ("scripts.tests.beta_test",)})
        self.assertEqual(table.unjudged_modules, {"scripts.tests.delta_test": "argparse driver: fixture"})
        self.assertEqual(table.unmapped_red, {"scripts.tests.gamma_test": "1 FAIL: fixture"})
        self.assertEqual(table.row_files, {"validation.alpha_test": "scripts/tests/alpha_test.py",
                                           "validation.beta_test": "scripts/tests/beta_test.py"})
        self.assertEqual(table.not_run_files, {"validation.delta_test": "scripts/tests/delta_test.py",
                                               "validation.gamma_test": "scripts/tests/gamma_test.py"})
        self.assertEqual(table.covered, ("scripts/tests/*_test.py",))
        # The checked-in table is tracked, loads, and is what this process selects with.
        self.assertTrue(ls.LAND_ROWS_FILE in self.tracked_paths(), "the row table is not a tracked file")
        # ... as a plain file: a link there would name a file the gate does not watch.
        staged = subprocess.run(["git", "-C", str(REPO), "ls-files", "-s", "--", ls.LAND_ROWS_FILE],
                                capture_output=True, text=True, check=True, timeout=60).stdout.split()
        self.assertEqual(staged[:1] + staged[2:], ["100644", "0", ls.LAND_ROWS_FILE])
        actual = ls.load_land_rows(str(REPO))
        self.assertEqual(actual, ls.parse_land_rows((REPO / ls.LAND_ROWS_FILE).read_text()))
        self.assertEqual((ls.VALIDATION_PROGRAM_TESTS, ls.VALIDATION_TEST_SUBJECTS,
                          ls.VALIDATION_UNJUDGED_MODULES, ls.VALIDATION_UNMAPPED_RED),
                         (actual.program_tests, actual.test_subjects, actual.unjudged_modules, actual.unmapped_red))
        self.assertGreater(len(actual.row_files), 150)
        self.assertTrue(actual.unjudged_modules and actual.unmapped_red)

    def test_row_table_reader_refuses_a_table_that_breaks_a_rule(self):
        valid = land_rows_text(self.ROWS, self.PROGRAMS, self.NOT_RUN)
        ls.parse_land_rows(valid)
        alpha = '"scripts/alpha.py", "scripts/tests/alpha_test.py"'
        runner = json.dumps([*ls.VALIDATION_ROW_COMMAND, "scripts.tests.alpha_test"])
        beta_row = valid[valid.index('[[row]]\nid = "validation.beta_test"'):valid.index("[[not_run]]")]
        gamma = valid[valid.index('[[not_run]]\nid = "validation.gamma_test"'):]
        for snippet in (alpha, runner, beta_row, gamma, 'catches = "a fixture defect"', 'kind = "red"'):
            self.assertIn(snippet, valid)
        cases = (
            # The six rules the port's review named.
            ("unknown key, top level", valid.replace("covered =", 'owner = "x"\ncovered ='), "unknown key 'owner'"),
            ("unknown key, row (the design's first name for selects_on)",
             valid.replace(f"selects_on = [{alpha}]", f"selects_on = [{alpha}]\ninputs = [{alpha}]"),
             r"\[\[row\]\] validation\.alpha_test: unknown key 'inputs'"),
            ("unknown key, not_run", valid.replace('kind = "red"', 'kind = "red"\nseconds = 900'),
             r"\[\[not_run\]\] validation\.gamma_test: unknown key 'seconds'"),
            ("duplicate row id", valid.replace("[[not_run]]", beta_row + "[[not_run]]", 1),
             r"\[\[row\]\] validation\.beta_test: duplicate id"),
            ("unsorted row ids", valid.replace('id = "validation.alpha_test"', 'id = "validation.calpha_test"')
             .replace("scripts.tests.alpha_test", "scripts.tests.calpha_test"),
             r"\[\[row\]\] validation\.beta_test: ids are not sorted \(it follows validation\.calpha_test\)"),
            ("empty selects_on", valid.replace(f"selects_on = [{alpha}]", "selects_on = []"),
             r"\[\[row\]\] validation\.alpha_test: empty selects_on"),
            ("empty catches", valid.replace('catches = "a fixture defect"', 'catches = " "', 1),
             r"\[\[row\]\] validation\.alpha_test: empty catches"),
            ("a module that is both", valid.replace('id = "validation.gamma_test"', 'id = "validation.beta_test"')
             .replace("scripts/tests/gamma_test.py", "scripts/tests/beta_test.py")
             .replace('id = "validation.delta_test"', 'id = "validation.aaa_test"')
             .replace("scripts/tests/delta_test.py", "scripts/tests/aaa_test.py"),
             r"\[\[not_run\]\] validation\.beta_test: also a \[\[row\]\]"),
            # The rest of what the reader holds a table to.
            ("not TOML", valid + "[[row\n", "not TOML"),
            ("another schema", valid.replace(ls.LAND_ROWS_SCHEMA, "trust.land-rows.v2"), "schema is 'trust.land-rows.v2'"),
            ("missing key", valid.replace('catches = "a fixture defect"\n', "", 1), "missing key 'catches'"),
            ("mistyped key", valid.replace('catches = "a fixture defect"', "catches = 7", 1), "catches is not a string"),
            ("row without an id", valid.replace('id = "validation.alpha_test"\n', ""), r"\[\[row\]\] #1: no string id"),
            ("an id of another kind", valid.replace('id = "validation.alpha_test"', 'id = "push.alpha_test"'),
             r"\[\[row\]\] push\.alpha_test: the id is not validation\.<module>"),
            ("unsorted selects_on", valid.replace(alpha, '"scripts/tests/alpha_test.py", "scripts/alpha.py"'),
             "selects_on: not sorted"),
            ("repeated selects_on path", valid.replace(alpha, '"scripts/alpha.py", ' + alpha), "listed twice"),
            ("empty selects_on path", valid.replace(alpha, '"", ' + alpha), "is not a non-empty string"),
            ("another command", valid.replace(runner, '["python3", "-m", "unittest", "scripts.tests.alpha_test"]'),
             r"\[\[row\]\] validation\.alpha_test: command is not this row's validation runner"),
            ("another module's command", valid.replace(runner, runner.replace("alpha_test", "beta_test")),
             r"\[\[row\]\] validation\.alpha_test: command is not this row's validation runner"),
            ("empty not_yet_targo", valid.replace('not_yet_targo = "a fixture runner"', 'not_yet_targo = ""', 1),
             r"\[\[row\]\] validation\.alpha_test: empty not_yet_targo"),
            ("not_run kind", valid.replace('kind = "red"', 'kind = "slow"'), "kind is 'slow'"),
            ("not_run empty why", valid.replace('"1 FAIL: fixture"', '""'),
             r"\[\[not_run\]\] validation\.gamma_test: empty why"),
            ("not_run path of another file", valid.replace("scripts/tests/gamma_test.py", "scripts/tests/other_test.py"),
             r"\[\[not_run\]\] validation\.gamma_test: path is 'scripts/tests/other_test\.py'"),
            ("duplicate not_run id", valid + gamma, r"\[\[not_run\]\] validation\.gamma_test: duplicate id"),
            ("unsorted not_run ids", valid.replace('id = "validation.delta_test"', 'id = "validation.zeta_test"')
             .replace("scripts/tests/delta_test.py", "scripts/tests/zeta_test.py"),
             r"\[\[not_run\]\] validation\.gamma_test: ids are not sorted"),
            ("program row that is no row", valid.replace('["validation.alpha_test"]', '["validation.omega_test"]'),
             "validation.omega_test is not a \\[\\[row\\]\\]"),
            ("program rows short of its selectors",
             valid.replace('["validation.beta_test", "validation.alpha_test"]', '["validation.alpha_test"]'),
             "validation_programs 'scripts/alpha.py': its rows are not exactly the rows whose selects_on names"),
            ("program rows beyond its selectors",
             valid.replace('"scripts/tests/alpha_test.py" = ["validation.alpha_test"]',
                           '"scripts/tests/alpha_test.py" = ["validation.alpha_test", "validation.beta_test"]'),
             "validation_programs 'scripts/tests/alpha_test.py': its rows are not exactly"),
            ("program row listed twice",
             valid.replace('["validation.beta_test", "validation.alpha_test"]',
                           '["validation.beta_test", "validation.alpha_test", "validation.beta_test"]'),
             "listed twice"),
            ("program without rows", valid.replace('["validation.beta_test", "validation.alpha_test"]', "[]"),
             "validation_programs 'scripts/alpha.py': empty"),
            ("program that is not an array",
             valid.replace('["validation.beta_test", "validation.alpha_test"]', '"validation.alpha_test"'),
             "not an array of row ids"),
            ("nothing covered", valid.replace('covered = ["scripts/tests/*_test.py"]', "covered = []"), "covered: empty"),
        )
        self.assertEqual(len({name for name, _text, _why in cases}), len(cases))
        for name, text, why in cases:
            with self.subTest(case=name):
                self.assertNotEqual(text, valid, "the case does not change the table")
                with self.assertRaisesRegex(ls.LandRowsError, why):
                    ls.parse_land_rows(text)
        # A missing, unreadable or broken table names the file; nothing is selected from a default.
        with tempfile.TemporaryDirectory(prefix="land-rows-") as tmp:
            with self.assertRaisesRegex(ls.LandRowsError, r"gates/land\.toml: the landing gate's row table cannot "
                                                           r"be read under .*FileNotFoundError"):
                ls.load_land_rows(tmp)
            (Path(tmp) / "gates").mkdir()
            (Path(tmp) / ls.LAND_ROWS_FILE).write_bytes(b"\xff\xfe")
            with self.assertRaisesRegex(ls.LandRowsError, r"gates/land\.toml: .*UnicodeDecodeError"):
                ls.load_land_rows(tmp)
            (Path(tmp) / ls.LAND_ROWS_FILE).write_text(cases[5][1])
            with self.assertRaisesRegex(ls.LandRowsError, r"^gates/land\.toml: \[\[row\]\] validation\.alpha_test: "
                                                           r"empty selects_on"):
                ls.load_land_rows(tmp)
            (Path(tmp) / ls.LAND_ROWS_FILE).write_text(valid)
            self.assertEqual(ls.load_land_rows(tmp), ls.parse_land_rows(valid))
        with mock.patch.object(ls, "tomllib", None):
            with self.assertRaisesRegex(ls.LandRowsError, r"Python >= 3\.11"):
                ls.parse_land_rows(valid)

    def test_row_table_is_read_only_from_a_regular_file_in_a_real_directory(self):
        # Git can track a symbolic link at gates/land.toml or at gates. The gate
        # hashes and watches the table by that one path, so a table read through
        # a link could change (its target edited, on main or on disk) with no
        # cache key and no loaded-reader check noticing. The reader refuses it.
        valid = land_rows_text(self.ROWS, self.PROGRAMS, self.NOT_RUN)
        expected = ls.parse_land_rows(valid)

        def root_with(build):
            tmp = tempfile.TemporaryDirectory(prefix="land-rows-link-")
            self.addCleanup(tmp.cleanup)
            root = Path(tmp.name)
            (root / "elsewhere").mkdir()
            (root / "elsewhere/rows.toml").write_text(valid)
            (root / "elsewhere/land.toml").write_text(valid)
            build(root)
            return root

        def plain(root):
            (root / "gates").mkdir()
            (root / ls.LAND_ROWS_FILE).write_text(valid)

        def linked_file(root):
            (root / "gates").mkdir()
            (root / ls.LAND_ROWS_FILE).symlink_to("../elsewhere/rows.toml")

        def linked_directory(root):
            (root / "gates").symlink_to("elsewhere")

        def directory_at_the_table(root):
            (root / ls.LAND_ROWS_FILE).mkdir(parents=True)

        def file_at_the_directory(root):
            (root / "gates").write_text(valid)

        # Control: the same bytes in a regular file load, and each link's target is readable.
        root = root_with(plain)
        self.assertEqual(ls.read_land_rows_text(str(root)), valid)
        self.assertEqual(ls.load_land_rows(str(root)), expected)
        for build, why in ((linked_file, r"gates/land\.toml: gates/land\.toml is a symbolic link under "),
                           (linked_directory, r"gates/land\.toml: gates is a symbolic link under "),
                           (directory_at_the_table, r"gates/land\.toml: gates/land\.toml is not a regular file under "),
                           (file_at_the_directory, r"gates/land\.toml: gates is not a directory under ")):
            with self.subTest(case=build.__name__):
                root = root_with(build)
                if "linked" in build.__name__:
                    self.assertEqual((root / ls.LAND_ROWS_FILE).read_text(), valid, "the link does not resolve")
                with self.assertRaisesRegex(ls.LandRowsError, why + ".*the selector selects nothing without it"):
                    ls.load_land_rows(str(root))
                # The gate's reload of an incoming table reads it the same way.
                with mock.patch.object(land_gate, "REPO_ROOT", root):
                    with self.assertRaises(ValueError):
                        land_gate._data_reader_text(ls.LAND_ROWS_FILE)
        # The gate's other data reader is unaffected: plain text of the path.
        root = root_with(plain)
        (root / "scripts/lib").mkdir(parents=True)
        (root / "scripts/lib/land_development.py").write_text("PROGRAM_TESTS = {}\n")
        with mock.patch.object(land_gate, "REPO_ROOT", root):
            self.assertEqual(land_gate._data_reader_text(ls.LAND_ROWS_FILE), valid)
            self.assertEqual(land_gate._data_reader_text("scripts/lib/land_development.py"), "PROGRAM_TESTS = {}\n")

    @staticmethod
    def exported(manifest: str, path: str) -> bool:
        """Whether publish/manifest.txt's allowlist ships `path`: some entry
        names it or a directory above it, and no `!` exclusion does."""
        shipped = False
        for line in manifest.splitlines():
            entry = line.strip()
            if not entry or entry.startswith("#"):
                continue
            excluded, entry = entry.startswith("!"), entry.lstrip("!")
            if path == entry or (entry.endswith("/") and path.startswith(entry)):
                if excluded:
                    return False
                shipped = True
        return shipped

    def test_a_public_snapshot_that_ships_the_selector_ships_its_row_table(self):
        # The export is an allowlist (publish/manifest.txt: only listed paths
        # ship). The selector does not import without its table, so a snapshot
        # with scripts/ and no gates/ would carry a land_gate.py and a
        # check_ledger_pins.py that die at import, where they ran before the
        # table left land_select.py.
        manifest = (REPO / "publish/manifest.txt").read_text()
        self.assertTrue(self.exported(manifest, ls.LAND_ROWS_READER), "the instrument: the selector ships")
        self.assertFalse(self.exported(manifest, "src/llvm-project/README.md"), "the instrument: exclusions count")
        self.assertFalse(self.exported(manifest, "docs/PLAN.md"), "the instrument: an unlisted path does not ship")
        self.assertTrue(self.exported(manifest, ls.LAND_ROWS_FILE),
                        f"publish/manifest.txt ships {ls.LAND_ROWS_READER} without {ls.LAND_ROWS_FILE}")
        # Control: the allowlist as it was before the table was listed.
        without = "\n".join(line for line in manifest.splitlines() if line.strip() != "gates/")
        self.assertNotEqual(without, manifest.rstrip("\n"))
        self.assertFalse(self.exported(without, ls.LAND_ROWS_FILE))
        self.assertTrue(self.exported(without, ls.LAND_ROWS_READER))

    def test_importing_the_selector_without_its_row_table_fails_closed(self):
        # The four tables have no default: a checkout without the table, or with
        # one that breaks a rule, imports no selector at all.
        selector = REPO / "scripts/lib/land_select.py"
        probe = ("import sys\nsys.path.insert(0, sys.argv[1])\nimport land_select\n"
                 "print(len(land_select.VALIDATION_PROGRAM_TESTS))\n")
        broken = land_rows_text(self.ROWS, self.PROGRAMS, self.NOT_RUN).replace(
            'catches = "a fixture defect"', 'catches = ""', 1)
        for name, text, why in (("missing", None, "row table cannot be read"),
                                ("broken", broken, r"gates/land\.toml: \[\[row\]\] validation\.alpha_test: empty catches"),
                                ("valid", land_rows_text(self.ROWS, self.PROGRAMS, self.NOT_RUN), None)):
            with self.subTest(table=name), tempfile.TemporaryDirectory(prefix="land-rows-import-") as tmp:
                lib = Path(tmp) / "scripts/lib"
                lib.mkdir(parents=True)
                for module in ("land_select.py", "rust_lex.py", "crates_lane_members.py", "host_budget.py"):
                    shutil.copy2(selector.parent / module, lib / module)
                if text is not None:
                    (Path(tmp) / "gates").mkdir()
                    (Path(tmp) / ls.LAND_ROWS_FILE).write_text(text)
                proc = subprocess.run([sys.executable, "-B", "-c", probe, str(lib)], cwd=tmp,
                                      capture_output=True, text=True, timeout=60)
                if why is None:
                    self.assertEqual((proc.returncode, proc.stdout.strip()), (0, "2"), proc.stderr[-2000:])
                else:
                    self.assertNotEqual(proc.returncode, 0)
                    self.assertEqual(proc.stdout, "")
                    self.assertRegex(proc.stderr.strip().splitlines()[-1], "LandRowsError: .*" + why)

    def test_every_tracked_script_test_is_exactly_one_row_or_one_not_run(self):
        text = (REPO / ls.LAND_ROWS_FILE).read_text()
        table, tracked = ls.parse_land_rows(text), self.tracked_paths()
        # The instrument: the listing found the suite, and the rule covers it.
        self.assertIn("scripts/tests/land_gate_test.py", tracked)
        self.assertEqual(table.covered, ("scripts/tests/*_test.py",))
        self.assertEqual(sorted([*table.row_files.values(), *table.not_run_files.values()]),
                         sorted(module.replace(".", "/") + ".py" for module in self.script_test_modules()))
        self.assertEqual(ls.land_rows_coverage(table, tracked), [])
        # Positive control: a tracked test file that is neither is reported, and
        # declaring it either way, once, is what satisfies the rule.
        control = "scripts/tests/zz_cover_control_test.py"
        self.assertEqual(ls.land_rows_coverage(table, [*tracked, control]),
                         [f"{control}: neither a [[row]] nor a [[not_run]]"])
        declared = land_rows_text({"zz_cover_control_test": [control]}, None,
                                  [("zz_cover_control_test", "red", "1 FAIL: control")])
        row = declared[declared.index("[[row]]"):declared.index("[[not_run]]")]
        not_run = declared[declared.index("[[not_run]]"):]
        as_row, as_not_run = ls.parse_land_rows(text + row), ls.parse_land_rows(text + not_run)
        self.assertEqual(ls.land_rows_coverage(as_row, [*tracked, control]), [])
        self.assertEqual(ls.land_rows_coverage(as_not_run, [*tracked, control]), [])
        # Both: the reader refuses the table, and the rule itself reports it.
        with self.assertRaisesRegex(ls.LandRowsError, r"validation\.zz_cover_control_test: also a \[\[row\]\]"):
            ls.parse_land_rows(text + row + not_run)
        both = as_row._replace(not_run_files=as_not_run.not_run_files)
        self.assertEqual(ls.land_rows_coverage(both, [*tracked, control]),
                         [f"{control}: [[row]] validation.zz_cover_control_test and [[not_run]] "
                          "validation.zz_cover_control_test (exactly one, never both)"])
        # An entry for a file the tree does not track is reported too.
        self.assertEqual(ls.land_rows_coverage(as_row, tracked),
                         [f"[[row]] validation.zz_cover_control_test: {control} is not a tracked file"])
        self.assertEqual(ls.land_rows_coverage(as_not_run, tracked),
                         [f"[[not_run]] validation.zz_cover_control_test: {control} is not a tracked file"])
        # `*` stays inside one path component, and only the covered names count.
        self.assertEqual(ls.land_rows_coverage(table, [*tracked, "scripts/tests/sub/zz_test.py",
                                                       "scripts/tests/zz_helper.py", "tests/zz_test.py",
                                                       "x/scripts/tests/zz_test.py"]), [])

    # What a `catches` may not be. A floor the tree is held to, not the field's
    # meaning (the defect the row exists to catch), which no pattern can judge.
    BARE_TITLE = re.compile(r"(?:[^\s:;.]+ ){0,6}(?:self-?tests?|tests?|controls|regressions?|proofs) (?:for|of) ",
                            re.IGNORECASE)

    @classmethod
    def names_no_defect(cls, catches: str) -> Optional[str]:
        """Why `catches` cannot be a defect statement, or None when the floor has nothing against it."""
        if catches.lstrip().startswith(':"') or 'exec "$' in catches or "raise SystemExit" in catches:
            return "a shell or Python block, not prose"
        if cls.BARE_TITLE.match(catches):
            return "a title that names the row's subject, not what would be wrong without the row"
        return None

    def test_no_row_catches_is_a_bare_title_or_a_shell_block(self):
        # The table was made from each module's docstring (2026-11-14). 67 rows
        # then said only "Tests for scripts/x.py." or the like, and five held the
        # `sh` re-exec block that opens a polyglot test file. Each now names its
        # defect; this holds new rows to at least that.
        doc = tomllib.loads((REPO / ls.LAND_ROWS_FILE).read_text())
        self.assertGreater(len(doc["row"]), 150)
        self.assertEqual({row["id"]: why for row in doc["row"]
                          if (why := self.names_no_defect(row["catches"])) is not None}, {})
        # Positive controls: texts the table held, each refused for its own reason.
        for text in ("Tests for scripts/check_reports_script_copies.py.",
                     "Self-test for `scripts/regen_raw_enum_tag_fixtures.py`.",
                     "Offline self-test for scripts/trust_f1_ladder.py.",
                     "Controls for the G2 schema-owned gate checker.",
                     "Focused fail-closed and mutation controls for the G4 completion checker.",
                     "Regressions for scripts/linux_refresh_toolchain.py: one staircase rung as one command.",
                     "Mutation proofs for the fleet pin-drift sweep."):
            with self.subTest(title=text):
                self.assertIn("a title", self.names_no_defect(text) or "")
        for text in (':" for candidate in python3.14 python3.13; do if command -v "$candidate" >/dev/null; then '
                     'exec "$candidate" "$0" "$@" fi done exit 2 ":',
                     "for c in python3.12; do exec \"$c\" \"$0\"; done",
                     "import sys; raise SystemExit(sys.version_info < (3, 11))"):
            with self.subTest(block=text):
                self.assertIn("block", self.names_no_defect(text) or "")
        # Negative controls: a defect statement may mention tests, and a text
        # that describes its controls is beyond this floor (the table's header
        # and docs/OPEN_ISSUES.md LAND-ROWS-CATCHES-1 say so).
        for text in ("scripts/x.py passing a tree whose pin moved.",
                     "A change to any file a seal ships changes its content identity (plan T13a).",
                     "No shell script may hand `trustc` an environment variable `trustc` refuses.",
                     "Inert provenance fixtures; these never qualify or execute a real SDK tool.",
                     "scripts/check_script_tests.sh reporting a pass when it ran no tests for a changed script."):
            with self.subTest(kept=text):
                self.assertIsNone(self.names_no_defect(text))

    def test_row_table_change_selects_what_a_selector_change_selects(self):
        # The table holds what land_select.py's dict literals held, so a change
        # to it is classified as a change to that file is: its tests run, no leg
        # is selected by the table alone, and a package that reads it is reached.
        table, reader = ls.LAND_ROWS_FILE, ls.LAND_ROWS_READER
        self.assertEqual((table, reader), ("gates/land.toml", "scripts/lib/land_select.py"))
        # By the selector's own rule, not by a row: the four tables stay the table's.
        self.assertNotIn(table, ls.VALIDATION_PROGRAM_TESTS)
        self.assertNotIn(table, ls.VALIDATION_TEST_SUBJECTS)
        self.assertIn(reader, ls.VALIDATION_PROGRAM_TESTS)
        self.assertTrue(ls.is_validation_program(table))
        self.assertIsNone(ls.everything_reason(table))
        self.assertIsNotNone(ls.everything_reason(reader + ".orig"))
        modules = ["scripts.tests.check_ledger_pins_test", "scripts.tests.land_development_test",
                   "scripts.tests.land_gate_test"]
        self.assertEqual(ls.validation_test_modules([reader]), modules)
        self.assertEqual(ls.validation_test_modules([table]), modules)
        self.assertEqual(ls.validation_program_tests(table), ls.VALIDATION_PROGRAM_TESTS[reader])
        g = Fixture.graph()
        self.assertEqual(ls.classify(g, table), ls.classify(g, reader))
        self.assertEqual(ls.classify(g, table)[0], "validation")
        selection, of_reader = ls.select(g, "base", [table]), ls.select(Fixture.graph(), "base", [reader])
        self.assertFalse(selection.everything)
        self.assertEqual(selected(selection), selected(of_reader))
        for leg_id in ("compiler-check", "ui-trust", "run-make-trust"):
            self.assertFalse(selection.decisions[leg_id].selected, leg_id)
        # One thing a .py never was: the table is a TOML document, so the crates
        # lane also runs trust-toml's corpus instrument on it, as for the audit
        # ledger. The fixture graph has no crates/ member to host that instrument.
        instruments = land_gate.crates_lane().moved_instruments([table])
        self.assertEqual([host for host, _tail in instruments], ["trust-toml"])
        self.assertEqual(instruments, land_gate.crates_lane().moved_instruments([ls.AUDITS_FILE]))
        self.assertEqual(land_gate.crates_lane().moved_instruments([reader]), [])
        plans = {k: host_budget.plan(host(14, 24, 20), k) for k in host_budget.KINDS}
        for hook in (HOOK_ON, HOOK_OFF):
            with mock.patch.object(land_gate, "moved_instrument_hosts", return_value={}):
                leg = next(leg for leg in land_gate.build_legs(g, selection, "base", plans, hook)
                           if leg.id == "validation-tests")
            self.assertTrue(leg.selected)
            self.assertTrue(leg.force_run)
            self.assertEqual(leg.command[4:], modules)
            self.assertIn(table, leg.scripts)
            self.assertIn(table, leg.inputs)
        # A neighbour, another spelling or a path under it is not the table: unmapped, every leg.
        for path in ("gates/land.toml.orig", "gates/other.toml", "gates/land.toml/x", "Gates/land.toml",
                     "land.toml", "scripts/gates/land.toml"):
            with self.subTest(path=path):
                self.assertFalse(ls.is_validation_program(path))
                self.assertIn(ls.classify(Fixture.graph(), path)[0], ("unmapped", "everything"))
                self.assertTrue(ls.select(Fixture.graph(), "base", [path]).everything)
                self.assertEqual(ls.validation_test_modules([path]), [])
        # A package that reads the table still selects its own legs.
        g = Fixture.graph()
        g.packages["compiler/rustc_a"].reads.append(ls.Read("compile", table, False, "fixture include"))
        selection = ls.select(g, "base", [table])
        self.assertTrue(selection.decisions["compiler-check"].selected)
        self.assertTrue(selection.per_crate["compiler-unit-tests"]["compiler/rustc_a"].selected)
        # Never narrowed on its own: the table is a validation program only while
        # its reader is one. Without that declaration it is unmapped: every leg.
        without = {path: tests for path, tests in ls.VALIDATION_PROGRAM_TESTS.items() if path != reader}
        with mock.patch.object(ls, "VALIDATION_PROGRAM_TESTS", without):
            self.assertFalse(ls.is_validation_program(table))
            self.assertEqual(ls.classify(Fixture.graph(), table)[0], "unmapped")
            self.assertTrue(ls.select(Fixture.graph(), "base", [table]).everything)
            self.assertEqual(ls.validation_test_modules([table]), [])
            self.assertNotIn(table, ls.validation_program_paths())
        # In a tree that holds it, it is not one of the paths every key carries.
        with tempfile.TemporaryDirectory(prefix="land-rows-inputs-") as tmp:
            root = Path(tmp)
            rev = make_repo(root, dict(FILES, **{table: "# fixture row table\n", "gates/other.toml": "# unmapped\n"}))
            g = ls.build_graph(ls.TreeIndex.load(str(root), rev))
            self.assertIn(table, g.index.entries)
            self.assertNotIn(table, ls.global_inputs(g))
            self.assertIn("gates/other.toml", ls.global_inputs(g))

    def test_test_subjects_add_tests_and_narrow_no_leg(self):
        # Additive: unlike a validation program, a test subject keeps every
        # other rule, so a script or a build input still selects everything.
        closure = "scripts.tests.bootstrap_dependency_closure_test"
        for path, module in (("scripts/bootstrap_dependency_closure.py", closure),
                             ("scripts/recreate_bootstrap.py", closure),
                             ("scripts/tests/bootstrap_dependency_closure_test.py", closure),
                             ("src/bootstrap/src/core/build_steps/tool.rs", closure),
                             ("scripts/recreate_bootstrap.py", "scripts.tests.bootstrap_resource_admission_test"),
                             ("scripts/tests/resource_fds_test.py", "scripts.tests.resource_fds_test"),
                             ("tools/preflight.py", "scripts.tests.targo_tool_preflight_test"),
                             ("x.py", "scripts.tests.trust_build_provenance_test")):
            with self.subTest(path=path):
                self.assertIn(path, ls.VALIDATION_TEST_SUBJECTS)
                self.assertIsNotNone(ls.everything_reason(path))
