        with tempfile.TemporaryDirectory(prefix="land-gate-prep.") as tmp, \
                contextlib.redirect_stdout(io.StringIO()):
            rc, _secs, _log, prepare_failed = land_gate.run_leg(l, Path(tmp), {}, (1, 2))
        self.assertNotEqual(rc, 0)
