    def test_targo_trust_test_workers_respect_admission_and_rescaling(self):
        for share in (1, 2, 6):
            with self.subTest(share=share), mock.patch.dict(os.environ, {
                "BUILD_SLOT_HELD": "1", "CARGO_BUILD_JOBS": str(share), "RUST_TEST_THREADS": "128",
            }):
                leg = self.legs("targo-trust/src/main.rs")["targo-trust"]
                self.assertEqual(land_gate.leg_environment(leg)["RUST_TEST_THREADS"], str(share))
                self.assertIn("--locked", leg.command)
                self.assertIn("--no-fail-fast", leg.command)
                self.assertNotIn("--test-threads", leg.command)
                with contextlib.redirect_stdout(io.StringIO()):
                    land_gate.rescale(leg, host(32, 512, 500))
                self.assertEqual(land_gate.leg_environment(leg)["RUST_TEST_THREADS"], str(share))
                before = (dict(leg.env), dict(leg.default_env))
                with self.assertRaises(land_gate.RescaleRefused):
                    land_gate.rescale(leg, host(14, 24, 2))
                self.assertEqual((leg.env, leg.default_env), before)

    def test_targo_trust_rescales_and_transports_its_own_test_thread_budget(self):
        g = ls.build_graph(ls.TreeIndex.load(str(self.root), self.rev))
        sel = ls.select(g, "base", ["targo-trust/src/main.rs"])
        with patch.dict(os.environ, {}, clear=True):
            plans = {k: host_budget.plan(host(5, 32, 11), k) for k in host_budget.KINDS}
            leg = {l.id: l for l in land_gate.build_legs(g, sel, "base", plans, HOOK_ON)}["targo-trust"]
        self.assertEqual(leg.env["CARGO_BUILD_JOBS"], "2")
        self.assertEqual(leg.env.get("RUST_TEST_THREADS"), "5")
        command = list(leg.command)
        self.assertEqual(command, land_gate.landing_targo.COMMAND)
        vm = ("Mach Virtual Memory Statistics: (page size of 16384 bytes)\n"
              "Pages free: 5242880.\nPages inactive: 0.\n"
              "Pages speculative: 0.\nPages purgeable: 0.\n")
        with patch.dict(os.environ, {"BUILD_SLOT_HELD": "1", "CARGO_BUILD_JOBS": "6",
                                     "RUST_TEST_THREADS": "99"}, clear=True), \
                patch.object(host_budget.platform, "system", return_value="Darwin"), \
                patch.object(host_budget, "_run", side_effect=["32", str(96 * GIB), vm]), \
                contextlib.redirect_stdout(io.StringIO()):
            measured = host_budget.measure()
            self.assertEqual(measured.cpus, 6)
            land_gate.rescale(leg, measured)
            self.assertEqual(leg.command, command)
            self.assertEqual(leg.env["CARGO_BUILD_JOBS"], "6")
            self.assertEqual(leg.env["RUST_TEST_THREADS"], "6")
            with patch.object(land_gate, "REPO_ROOT", self.root), \
                    patch.object(land_gate.subprocess, "Popen", side_effect=fixture_leg_process) as spawn:
                code = land_gate._run_one(leg, leg.command, io.StringIO(), {}, (1, 2), self.root)
            self.assertEqual(code, 0)
            selected_spawn_call(spawn)
            self.assertEqual(selected_spawn_call(spawn).args[0], command)
            actual_env = selected_spawn_call(spawn).kwargs["env"]
            self.assertEqual(actual_env["CARGO_BUILD_JOBS"], "6")
            self.assertEqual(actual_env["RUST_TEST_THREADS"], "6")

