# Bootstrap's source-readiness rule (PreparationScope::for_config), modelled for
# XpyReadinessScopeTests, which binds the model to that source.
XPY_PRODUCING = {"build", "b", "check", "c", "clippy", "fix", "doc", "d", "test", "t", "miri", "bench",
                 "run", "r"}
XPY_ALWAYS_FULL = {"dist", "install"}
XPY_NOT_PRODUCING = {"clean", "fmt", "format", "setup", "vendor"}
XPY_VALUE_OPTIONS = {"-j", "--jobs", "--stage", "--test-args", "--target", "--host", "--skip", "--exclude",
                     "--set", "--config", "--build-dir", "--rustc-args", "--compare-mode", "--pass", "--run",
                     "--extra-checks", "--keep-stage", "--keep-stage-std", "--on-fail", "--warnings"}
XPY_FLAGS = {"--all-targets", "--force-rerun", "--no-fail-fast", "--include-default-paths", "--verbose", "-v",
             "--dry-run", "--bless", "--no-doc", "--doc", "--tests"}


def xpy_readiness_scope(argv) -> str:
    """'request', 'full' or 'none' (no producer) for one x.py argv. An option or
    subcommand the model does not know fails: classify it, never guess."""
    at = next(i for i, a in enumerate(argv) if a == "x.py" or a.endswith("/x.py"))
    sub, rest = argv[at + 1], iter(argv[at + 2:])
    stage, paths, defaults = None, [], False
    for a in rest:
        if a == "--":
            break
        name, eq, value = a.partition("=")
        if a.startswith("-") and name in XPY_VALUE_OPTIONS:
            value = value if eq else next(rest)
            if name == "--stage":
                stage = value
        elif a.startswith("-"):
            if a not in XPY_FLAGS:
                raise AssertionError(f"x.py option {a!r} is unclassified here: {argv}")
            defaults = defaults or a == "--include-default-paths"
        else:
            paths.append(a)
    if sub in XPY_NOT_PRODUCING:
        return "none"
    if sub in XPY_ALWAYS_FULL:
        return "full"
    if sub not in XPY_PRODUCING:
        raise AssertionError(f"x.py subcommand {sub!r} is unclassified here: {argv}")
    return "request" if stage in ("0", "1") and paths and not defaults else "full"


class UnusedPatchOrderTests(unittest.TestCase):
    """LAND-GATE-UNUSED-PATCH-ORDER-1: a PATH targo older than the tree's
    unused-patch sort refuses every lock under --locked. Its unlocked rewrite
    is judged on a private copy beside the workspace: only a permutation of
    complete [[patch.unused]] rows, of the judged lock in the tree resolver's
    order, passes. MUTANTS reopens each hole."""

    HEAD = ('# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n'
            'version = 4\n\n[[package]]\nname = "credential"\nversion = "0.0.0"\n\n'
            '[[package]]\nname = "targo"\nversion = "0.0.0"\n')
    ROWS = ('[[patch.unused]]\nname = "Zed"\nversion = "0.1.0"\n',
            '[[patch.unused]]\nname = "a-unused"\nversion = "0.1.0"\n',
            '[[patch.unused]]\nname = "b-unused"\nversion = "0.2.0"\n',
            '[[patch.unused]]\nname = "b-unused"\nversion = "0.2.0"\n')
    LOCKED = ("error: the lock file /w/src/tools/targo/Cargo.lock needs to be updated but --locked was passed to "
              "prevent this\n")
    GAP = "error: failed to download `itoa v1.0.15`\n\nCaused by:\n  attempting to make an HTTP request, but --offline was specified\n"

    def lock(self, rows, head=None):
        return ((self.HEAD if head is None else head) + "".join("\n" + row for row in rows)).encode()

    def head_of(self, raw):
        return raw.split(b"\n[[patch.unused]]\n", 1)[0].decode()

    def tree(self, committed, files=None):
        tmp = tempfile.TemporaryDirectory(prefix="land-gate-unused-order.")
        self.addCleanup(tmp.cleanup)
        root = Path(tmp.name)
        files = dict(CoverageLegTests.FILES, **{"src/tools/targo/Cargo.lock": committed.decode(),
                                                 "src/tools/targo/.gitignore": "/target\n"}, **(files or {}))
        rev = make_repo(root, files)
        return root, ls.build_graph(ls.TreeIndex.load(str(root), rev))

    def fake(self, root, rewrite, edge="leaf", rc=0, odd=False, locked_ok=False, gap=0, refuse="src/tools/targo/Cargo.toml"):
        """`targo metadata`: --locked refuses `refuse` (or nothing, with
        `locked_ok`); the unlocked call (only ever on the copy, offline unless
        it fills) writes `rewrite(committed)` there. The first `gap` offline
        copy calls fail for what the registry lacks until an online one fills."""
        seen = {"copies": [], "online": [], "offline": 0}
        real_run = subprocess.run

        def run(argv, cwd=None, **kwargs):
            if argv[:1] != ["targo"]:  # the tree index's own git reads
                return real_run(argv, cwd=cwd, **kwargs)
            manifest = argv[argv.index("--manifest-path") + 1]
            if "--locked" in argv:
                if manifest == refuse and not locked_ok:
                    return subprocess.CompletedProcess(argv, 101, "", self.LOCKED)
                return subprocess.CompletedProcess(argv, 0, '{"packages": [], "resolve": {"nodes": []}}', "")
            env = kwargs.get("env")
            self.assertIsNotNone(env, "the copy's call names its environment")
            self.assertEqual([var for var in env if var in land_gate.METADATA_ENV_DROP
                              or var.startswith(land_gate.METADATA_ENV_DROP_PREFIXES)], [],
                             "the copy's own lock is the one judged")
            copy = (Path(cwd) / manifest).parent
            self.assertEqual(copy.parent, (root / refuse).parent.parent, "the copy stands beside the workspace")
            self.assertTrue(copy.name.startswith(f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{os.getpid()}."), copy)
            self.assertTrue((copy / "Cargo.toml").is_symlink())
            self.assertFalse(os.path.lexists(copy / ".gitignore"))
            self.assertFalse((copy / "Cargo.lock").is_symlink())
            if "--offline" not in argv:
                seen["online"].append(kwargs.get("timeout"))
                gap_left[0] = 0
                return subprocess.CompletedProcess(argv, 0, "{}", "")
            seen["offline"] += 1
            if gap_left[0]:
                # Targo writes its resolve before it downloads, so a download
                # gap leaves the rewrite in the copy.
                (copy / "Cargo.lock").write_bytes(rewrite((copy / "Cargo.lock").read_bytes()))
                return subprocess.CompletedProcess(argv, 101, "", self.GAP)
            seen["copies"].append(copy)
            (copy / "Cargo.lock").write_bytes(rewrite((copy / "Cargo.lock").read_bytes()))
            base = f"{root}/src/tools/./{copy.name}" if odd else str(copy)
            target = (("leaf", str(root / "crates/leaf/Cargo.toml")) if edge == "leaf"
                      else ("credential", base + "/crates/credential/Cargo.toml"))
            data = {"packages": [{"id": "native", "source": None, "manifest_path": base + "/Cargo.toml"},
                                 {"id": target[0], "source": None, "manifest_path": target[1]}],
                    "resolve": {"nodes": [{"id": "native", "deps": [{"pkg": target[0]}]}]},
                    "workspace_root": base}
            return subprocess.CompletedProcess(argv, rc, json.dumps(data), "")
        gap_left = [gap]
        return seen, run

    # A caller's environment that would judge another lock, or none: every
    # copy call must leave these out (metadata_env).
    REDIRECTING_ENV = {"CARGO_RESOLVER_LOCKFILE_PATH": "/elsewhere/Cargo.lock",
                       "TARGO_RESOLVER_LOCKFILE_PATH": "/elsewhere/Cargo.lock",
                       "CARGO_UNSTABLE_AVOID_DEV_DEPS": "true", "TARGO_UNSTABLE_AVOID_DEV_DEPS": "true"}

    def verify(self, root, graph, run, drift=([], [])):
        err = io.StringIO()
        with mock.patch.object(land_gate, "REPO_ROOT", root), \
                mock.patch.dict(os.environ, self.REDIRECTING_ENV), \
                mock.patch.object(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None), \
                mock.patch.object(land_gate, "first_party_drift", lambda: drift), \
                mock.patch.object(land_gate.subprocess, "run", run), contextlib.redirect_stderr(err):
            return land_gate.verify_graph(graph), err.getvalue()

    def prefetch(self, root, run, check=True, drift=([], [])):
        out = io.StringIO()
        with mock.patch.object(land_gate, "REPO_ROOT", root), \
                mock.patch.dict(os.environ, self.REDIRECTING_ENV), \
                mock.patch.object(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None), \
                mock.patch.object(land_gate, "first_party_drift", lambda: drift), \
                mock.patch.object(land_gate.subprocess, "run", run), contextlib.redirect_stdout(out):
            return land_gate.cmd_prefetch(land_gate.argparse.Namespace(check=check)), out.getvalue()

    def permuted(self, raw):
        return self.lock(tuple(reversed(self.ROWS)), self.head_of(raw))

    def leftovers(self, root, parent="src/tools"):
        return [name for name in os.listdir(root / parent) if name.startswith(land_gate.UNUSED_ORDER_COPY_PREFIX)]

    def refused(self, root, graph, run, drift=([], [])):
        with self.assertRaises(land_gate.LockedWorkspaceInputs) as caught:
            self.verify(root, graph, run, drift)
        self.assertEqual(self.leftovers(root), [])
        return caught.exception

    def test_an_older_targos_row_order_is_judged_on_a_private_copy(self):
        committed = self.lock(self.ROWS)
        root, graph = self.tree(committed)
        seen, run = self.fake(root, self.permuted)
        problems, err = self.verify(root, graph, run)
        self.assertEqual(problems, [])
        self.assertEqual((len(seen["copies"]), seen["online"]), (1, []))
        self.assertIn("LAND-GATE-UNUSED-PATCH-ORDER-1", err)
        self.assertEqual((root / "src/tools/targo/Cargo.lock").read_bytes(), committed, "the lock never moves")
        self.assertEqual(self.leftovers(root), [], "the copy is removed")
        self.assertTrue((root / "src/tools/targo/src/lib.rs").is_file(), "removing links removes no source")

    def test_the_copys_graph_names_the_workspaces_own_paths(self):
        root, graph = self.tree(self.lock(self.ROWS))
        _seen, run = self.fake(root, self.permuted, edge="credential")
        problems, _err = self.verify(root, graph, run)
        self.assertEqual(len(problems), 1, problems)
        self.assertIn("resolves src/tools/targo -> src/tools/targo/crates/credential", problems[0])
        self.assertNotIn(land_gate.UNUSED_ORDER_COPY_PREFIX, problems[0])

    def test_a_copy_path_the_mapping_misses_is_still_refused(self):
        root, graph = self.tree(self.lock(self.ROWS))
        _seen, run = self.fake(root, self.permuted, edge="credential", odd=True)
        error = self.refused(root, graph, run)
        self.assertEqual([row["workspace"] for row in error.failures if row["stale_lock"]],
                         ["src/tools/targo/Cargo.toml"])

    def test_a_content_change_beside_the_permutation_is_still_refused(self):
        root, graph = self.tree(self.lock(self.ROWS))
        changes = {
            "a package row": lambda raw: self.permuted(raw).replace(b'version = "0.0.0"\n\n[[package]]\nname = "targo"',
                                                                    b'version = "0.0.1"\n\n[[package]]\nname = "targo"'),
            "an unused row": lambda raw: self.permuted(raw).replace(b'"a-unused"', b'"c-unused"'),
            "a duplicate unused row dropped": lambda raw: self.lock(
                (self.ROWS[3], self.ROWS[1], self.ROWS[0]), self.head_of(raw)),
            "a duplicate unused row added": lambda raw: self.lock(
                tuple(reversed(self.ROWS)) + (self.ROWS[2],), self.head_of(raw)),
            "no change": lambda raw: raw,
        }
        for what, rewrite in changes.items():
            with self.subTest(what=what):
                _seen, run = self.fake(root, rewrite)
                error = self.refused(root, graph, run)
                self.assertEqual([row["workspace"] for row in error.failures if row["stale_lock"]],
                                 ["src/tools/targo/Cargo.toml"])

    def test_a_committed_lock_out_of_the_resolvers_order_is_still_refused(self):
        rows = (self.ROWS[1], self.ROWS[0], self.ROWS[2], self.ROWS[3])
        root, graph = self.tree(self.lock(rows))
        seen, run = self.fake(root, self.permuted)
        self.refused(root, graph, run)
        self.assertEqual(seen["offline"], 0, "no copy is made for a lock the tree's targo would rewrite")

    def test_a_worktree_lock_that_is_not_the_judged_one_is_still_refused(self):
        committed = self.lock(self.ROWS)
        root, graph = self.tree(committed)
        for what, worktree in (
                ("out of order", self.permuted(committed)),
                ("in order, another package row", committed.replace(
                    b'version = "0.0.0"\n\n[[package]]\nname = "targo"',
                    b'version = "9.9.9"\n\n[[package]]\nname = "targo"'))):
            with self.subTest(what=what):
                (root / "src/tools/targo/Cargo.lock").write_bytes(worktree)
                seen, run = self.fake(root, self.permuted)
                self.refused(root, graph, run)
                self.assertEqual(seen["offline"], 0)
                self.assertEqual((root / "src/tools/targo/Cargo.lock").read_bytes(), worktree)

    def test_a_drifted_or_unreadable_first_party_tree_is_still_refused(self):
        root, graph = self.tree(self.lock(self.ROWS))
        for drift, kind in (((["first-party/x"], []), "drifted"), (([], ["first-party/ (git status exit 128)"]),
                                                                    "stale_lock")):
            with self.subTest(drift=drift):
                seen, run = self.fake(root, self.permuted)
                error = self.refused(root, graph, run, drift)
                row = next(r for r in error.failures if r["workspace"] == "src/tools/targo/Cargo.toml")
                self.assertTrue(row["drifted"] if kind == "drifted" else row["stale_lock"], row)
                self.assertEqual(seen["offline"], 0, "no copy is made over drifted or unknown inputs")
                rc, out = self.prefetch(root, run, drift=drift)
                self.assertEqual(rc, 2, out)
                self.assertEqual(seen["offline"], 0)

    def test_a_failed_call_or_a_redirect_leaves_the_refusal(self):
        root, graph = self.tree(self.lock(self.ROWS))
        _seen, run = self.fake(root, self.permuted, rc=101)
        self.refused(root, graph, run)
        seen, run = self.fake(root, self.permuted)
        with mock.patch.object(land_gate, "REPO_ROOT", root), \
                mock.patch.object(land_gate, "lock_redirect", lambda cwd, env=None, home=None: "a config redirects"), \
                mock.patch.object(land_gate.subprocess, "run", run), contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(land_gate.unused_order_answer("src/tools/targo/Cargo.toml", self.lock(self.ROWS), None,
                                                           True), (None, None))
        self.assertEqual(seen["offline"], 0)

    def test_the_root_workspaces_lock_is_never_copied(self):
        committed = self.lock(self.ROWS)
        root, graph = self.tree(committed, {"Cargo.lock": committed.decode()})
        seen, run = self.fake(root, self.permuted, refuse="Cargo.toml")
        error = self.refused(root, graph, run)
        self.assertEqual([row["workspace"] for row in error.failures if row["stale_lock"]], ["Cargo.toml"])
        self.assertEqual(seen["offline"], 0)
        self.assertEqual(self.leftovers(root, "."), [])
        err = io.StringIO()
        with mock.patch.object(land_gate, "REPO_ROOT", root), contextlib.redirect_stderr(err):
            self.assertEqual(land_gate.unused_order_answer("Cargo.toml", committed, None, True), (None, None))
        self.assertIn("the root workspace's lock is not judged on a private copy", err.getvalue(),
                      "the gate says why the root's refusal stands")

    def test_a_registry_gap_behind_a_moved_resolve_asks_no_network(self):
        committed = self.lock(self.ROWS)
        root, graph = self.tree(committed)
        moved = lambda raw: self.permuted(raw).replace(  # noqa: E731
            b'version = "0.0.0"\n\n[[package]]\nname = "targo"', b'version = "0.0.1"\n\n[[package]]\nname = "targo"')
        for what, rewrite in (("a package row moved", moved), ("no resolve written", lambda raw: raw)):
            with self.subTest(what=what):
                seen, run = self.fake(root, rewrite, gap=1)
                err = io.StringIO()
                with mock.patch.object(land_gate, "REPO_ROOT", root), \
                        mock.patch.object(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None), \
                        mock.patch.object(land_gate.subprocess, "run", run), contextlib.redirect_stderr(err):
                    self.assertEqual(land_gate.unused_order_answer("src/tools/targo/Cargo.toml", committed, None,
                                                                   True), (None, None))
                self.assertEqual(seen["online"], [], "no download for a resolve the committed lock does not hold")
                self.assertIn("the network is not asked", err.getvalue())
                self.assertEqual(self.leftovers(root), [])
                seen, run = self.fake(root, rewrite, gap=1)
                error = self.refused(root, graph, run)
                self.assertEqual(seen["online"], [])
                self.assertEqual([row["workspace"] for row in error.failures if row["stale_lock"]],
                                 ["src/tools/targo/Cargo.toml"])

    def test_a_registry_gap_on_the_copy_is_filled_once_then_judged(self):
        root, graph = self.tree(self.lock(self.ROWS))
        seen, run = self.fake(root, self.permuted, gap=1)
        problems, err = self.verify(root, graph, run)
        self.assertEqual(problems, [])
        self.assertEqual(seen["online"], [land_gate.METADATA_FILL_TIMEOUT_S], "one bounded fill, on the copy")
        self.assertIn("the private lock copy cannot answer offline", err)
        # A dead network asked once already, or --check, asks it no more.
        seen, run = self.fake(root, self.permuted, gap=1)
        with mock.patch.object(land_gate, "REPO_ROOT", root), \
                mock.patch.object(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None), \
                mock.patch.object(land_gate.subprocess, "run", run), contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(land_gate.unused_order_answer("src/tools/targo/Cargo.toml", self.lock(self.ROWS),
                                                           "no network", True), (None, "no network"))
        rc, out = self.prefetch(root, run, check=True)
        self.assertEqual(rc, 2, out)
        self.assertIn("failed too", out)
        self.assertEqual(seen["online"], [])

    def test_a_sweep_reaches_the_parents_it_is_given(self):
        # The lock hygiene check sweeps beside the workspaces it judges
        # (crates/*), which METADATA_WORKSPACES does not name.
        committed = self.lock(self.ROWS)
        root, _graph = self.tree(committed)
        dead = subprocess.Popen([sys.executable, "-c", "pass"])
        dead.wait()
        (root / "crates").mkdir(exist_ok=True)
        copy = root / "crates" / f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{dead.pid}.gone.w"
        copy.mkdir()
        (copy / "Cargo.lock").write_bytes(committed)
        with mock.patch.object(land_gate, "REPO_ROOT", root):
            land_gate.sweep_dead_unused_order_copies(say=lambda line: None)
            self.assertTrue(copy.is_dir(), "the default sweep reaches only METADATA_WORKSPACES' parents")
            land_gate.sweep_dead_unused_order_copies(say=lambda line: None, parents=[root / "crates"])
        self.assertFalse(copy.exists())

    def test_a_dead_gates_copy_is_removed_whatever_the_lock_says(self):
        committed = self.lock(self.ROWS)
        root, graph = self.tree(committed)
        dead = subprocess.Popen([sys.executable, "-c", "pass"])
        dead.wait()
        tools = root / "src/tools"
        live = f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{os.getppid()}.keep.targo"
        for name in (f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{dead.pid}.gone.targo", live):
            copy = tools / name
            copy.mkdir()
            os.symlink(tools / "targo/src", copy / "src")
            (copy / "Cargo.lock").write_bytes(committed)
        # A prefix-named link is never followed: the workspace behind it keeps its lock.
        os.symlink(tools / "targo", tools / f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{dead.pid}.link")
        _seen, run = self.fake(root, self.permuted, locked_ok=True)
        problems, _err = self.verify(root, graph, run)
        self.assertEqual(problems, [])
        self.assertEqual(sorted(self.leftovers(root)),
                         sorted([live, f"{land_gate.UNUSED_ORDER_COPY_PREFIX}{dead.pid}.link"]))
        self.assertEqual((tools / "targo/Cargo.lock").read_bytes(), committed)
        self.assertTrue((tools / "targo/src/lib.rs").is_file())

    def test_prefetch_judges_the_worktree_lock_the_same_way(self):
        committed = self.lock(self.ROWS)
        root, _graph = self.tree(committed)
        _seen, run = self.fake(root, self.permuted)
        rc, out = self.prefetch(root, run)
        self.assertEqual(rc, 0, out)
        self.assertIn("registry: src/tools/targo/Cargo.toml: answers offline", out)
        self.assertEqual(self.leftovers(root), [])

    def test_the_tree_resolvers_order(self):
        def rows(*pairs, **extra):
            return [dict({"name": n, "version": v}, **extra) for n, v in pairs]
        self.assertTrue(land_gate.tree_unused_order(rows(("Zed", "0.1.0"), ("a", "0.1.0"), ("a", "0.10.0"))))
        self.assertTrue(land_gate.tree_unused_order(rows(("a", "0.1.0"), ("a", "0.1.0"))))
        self.assertFalse(land_gate.tree_unused_order(rows(("a", "0.1.0"), ("Zed", "0.1.0"))))
        self.assertFalse(land_gate.tree_unused_order(rows(("a", "0.2.0"), ("a", "0.10.0"))))
        self.assertFalse(land_gate.tree_unused_order(
            [{"name": "a", "version": "1", "source": "git+x"}, {"name": "a", "version": "1"}]),
            "equal keys with different rows are not judged")
        self.assertFalse(land_gate.tree_unused_order([{"name": "a"}]))


class XpyReadinessScopeTests(unittest.TestCase):
    """LAND-GATE-DARWIN-READINESS-1 (2026-11-10). Bootstrap readies an x.py
    request from the sources it selects only with an explicit `--stage` 0/1 and
    explicit paths; every other producing request first checks the whole locked
    offline recipe envelope, which on Darwin refused before any work until the
    dependency fetch gained its retirement custodian
    (DARWIN-DEPENDENCY-FETCH-CUSTODIAN-1). The tidy and bootstrap-tests legs
    named paths but no stage, so every Mac refused them. Each gate x.py
    command is request-scoped, or a full request land_gate.XPY_FULL_REQUESTS
    lists with its reason; a leg added without a stage fails here."""

    FILES = CoverageLegTests.FILES
    # The x.py lines of the scripts the legs and push rows run, as
    # (subcommand, --stage, scope read off the line's paths), in file order. A
    # new or restaged line must be classified here; a "full" one belongs to a
    # leg XPY_FULL_REQUESTS lists.
    SCRIPT_XPY = {
        "scripts/check_compiler_unit_tests.sh": [("test", "1", "request"), ("test", "2", "full"),
                                                 ("build", "1", "request"), ("test", "1", "request")],
        "scripts/check_trust_verify_suite_ratchet.sh": [("test", "1", "request")],
    }
    SCRIPT_LEG = {"scripts/check_compiler_unit_tests.sh": "compiler-unit-tests",
                  "scripts/check_trust_verify_suite_ratchet.sh": "compiler-unit-tests"}
    XPY_LINE = re.compile(r"(?:\S*python[\w.]*\"?\s+|\./)x\.py\s+(\S+)(.*)$", re.IGNORECASE)

    @classmethod
    def setUpClass(cls) -> None:
        cls.tmp = tempfile.TemporaryDirectory(prefix="land-gate-test-readiness.")
        cls.root = Path(cls.tmp.name)
        cls.rev = make_repo(cls.root, cls.FILES)

    @classmethod
    def tearDownClass(cls) -> None:
        cls.tmp.cleanup()

    def legs(self, *paths: str) -> list:
        g = ls.build_graph(ls.TreeIndex.load(str(self.root), self.rev))
        sel = ls.select(g, "base", list(paths))
        with patch.dict(os.environ, {}, clear=True):
            plans = {k: host_budget.plan(host(14, 24, 20), k) for k in host_budget.KINDS}
        return land_gate.build_legs(g, sel, "base", plans, HOOK_ON)

    def test_the_model_is_bootstraps_rule(self):
        src = (REPO / "src/bootstrap/src/utils/trust_preparation.rs").read_text(encoding="utf-8")
        body = " ".join(src.split("impl PreparationScope {", 1)[1].split("\n}", 1)[0].split())
        self.assertIn("if stage.is_some_and(|stage| stage <= 1) && paths && !defaults "
                      "{ Self::RequestSources } else { Self::FullEnvelope }", body)
        self.assertIn("fn for_flags(flags: &Flags) -> Self { Self::selection( flags.cmd.kind(), "
                      "flags.stage, !flags.paths.is_empty(), flags.include_default_paths, ) }", body)
        self.assertIn("fn for_config(config: &Config) -> Self { Self::selection( config.cmd.kind(), "
                      "config.explicit_stage_from_cli.then_some(config.stage), "
                      "!config.paths.is_empty(), config.include_default_paths, ) }", body)
        self.assertIn("Kind::Build | Kind::Check | Kind::Clippy | Kind::Fix | Kind::Doc | Kind::Test | Kind::Miri "
                      "| Kind::Bench | Kind::Run =>", body)
        self.assertIn("Kind::Dist | Kind::Install | Kind::MiriSetup | Kind::MiriTest => Self::FullEnvelope", body)
        self.assertIn("Kind::Clean | Kind::Format | Kind::Setup | Kind::Vendor => Self::NotProducer", body)
        for argv, want in ((["x.py", "test", "tidy"], "full"), (["x.py", "test", "tidy", "--stage", "1"], "request"),
                           (["x.py", "test", "--stage=1", "tidy"], "request"),
                           (["x.py", "test", "--stage", "2", "tidy"], "full"),
                           (["x.py", "check", "--stage", "1", "--all-targets"], "full"),
                           (["x.py", "test", "--stage", "1", "--include-default-paths", "tidy"], "full"),
                           (["x.py", "test", "--stage", "1", "--test-args", "tidy"], "full"),
                           (["x.py", "dist", "--stage", "1", "library"], "full"),
                           (["x.py", "fmt"], "none")):
            with self.subTest(argv=argv):
                self.assertEqual(xpy_readiness_scope(argv), want)
        for argv in (["x.py", "test", "--stage", "1", "--frobnicate", "tidy"], ["x.py", "perf", "tidy"]):
            with self.subTest(argv=argv), self.assertRaises(AssertionError):
                xpy_readiness_scope(argv)

    def test_every_leg_xpy_command_is_request_scoped_or_a_listed_full_request(self):
        full, seen = set(), set()
        for path in ("Cargo.toml", "src/bootstrap/src/lib.rs", "docs/README.md"):
            for leg in self.legs(path):
                for what, argv in (("command", leg.command), ("prepare", leg.prepare)):
                    # An unselected leg is SKIPPED, never run (run-make-trust
                    # then holds no path).
                    if not leg.selected or not argv or "x.py" not in argv:
                        continue
                    seen.add(leg.id)
                    with self.subTest(leg=leg.id, what=what, path=path):
                        if xpy_readiness_scope(argv) == "full":
                            full.add(leg.id)
                            self.assertIn(leg.id, land_gate.XPY_FULL_REQUESTS,
                                          f"{leg.id} {what} {argv[1:]} gets bootstrap's full-envelope readiness "
                                          "(the whole recipe envelope): name an explicit --stage 0/1 with its paths, or "
                                          "list it in XPY_FULL_REQUESTS with the reason its verdict needs that")
        for leg_id in ("tidy", "bootstrap-tests", "ui-trust", "run-make-trust", "native-targo-tests"):
            self.assertIn(leg_id, seen)
            self.assertNotIn(leg_id, full)
        self.assertIn("compiler-check", seen)
        for name, argv in (("development-recipes", land_gate._xpy_test_cmd(["tests/ui/trust/x.rs"], 2)),
                           ("stage1_prepare", land_gate.stage1_prepare(2))):
            with self.subTest(name=name):
                self.assertEqual(xpy_readiness_scope(argv), "request")
        self.assertEqual(full, {"compiler-check"})

    def test_every_xpy_argv_in_the_gate_source_is_classified(self):
        # Legs built conditionally (development_legs) or added later: read
        # every x.py argv display in land_gate.py, owned by its Leg(...) id.
        import ast
        tree = ast.parse((REPO / "scripts/land_gate.py").read_text(encoding="utf-8"))
        owner = {}
        for call in ast.walk(tree):
            if isinstance(call, ast.Call) and getattr(call.func, "id", None) == "Leg" and call.args \
                    and isinstance(call.args[0], ast.Constant):
                for arg in [*call.args[1:2], *(k.value for k in call.keywords if k.arg in ("command", "prepare"))]:
                    owner[id(arg)] = call.args[0].value
        found = []
        for node in ast.walk(tree):
            if not isinstance(node, ast.List) or not any(
                    isinstance(e, ast.Constant) and e.value == "x.py" for e in node.elts):
                continue
            argv = [e.value if isinstance(e, ast.Constant) and isinstance(e.value, str)
                    else "<paths>" if isinstance(e, ast.Starred) else "<value>" for e in node.elts]
            leg_id = owner.get(id(node), f"<line {node.lineno}>")
            found.append(leg_id)
            with self.subTest(owner=leg_id):
                if xpy_readiness_scope(argv) == "full":
                    self.assertIn(leg_id, land_gate.XPY_FULL_REQUESTS,
                                  f"{leg_id}: {argv} needs an explicit --stage 0/1 and paths, or a listed reason")
        self.assertGreaterEqual(len(found), 5)
        self.assertTrue({"tidy", "bootstrap-tests", "compiler-check"} <= set(found), found)

    def test_the_scripts_legs_and_push_rows_run_have_classified_xpy_lines(self):
        rows = subprocess.run(["bash", "tests/run_trust_comprehensive_harness.sh", "--list", "push"], cwd=REPO,
                              check=True, capture_output=True, text=True).stdout.splitlines()
        self.assertTrue(rows)
        commands = [row.split("\t")[4] for row in rows] + [
            " ".join(l.command) for l in self.legs("Cargo.toml")]
        queue = [rel for c in commands for rel in re.findall(r"\b(scripts/[\w./-]+\.sh)\b", c)]
        for c in commands:
            m = self.XPY_LINE.search(c)
            with self.subTest(command=c):
                if m and not c.startswith(sys.executable):
                    self.assertNotEqual(xpy_readiness_scope(shlex.split(c)), "full", c)
        scripts = {}
        while queue:
            rel = queue.pop()
            if rel in scripts or not (REPO / rel).is_file():
                continue
            lines, cont = [], ""
            for raw in (REPO / rel).read_text(encoding="utf-8", errors="replace").splitlines():
                line = cont + raw.strip()
                cont = line[:-1] + " " if line.endswith("\\") else ""
                if cont or line.startswith("#") or re.match(r"(echo|printf)\b", line):
                    continue
                queue += re.findall(r"\bbash (scripts/[\w./-]+\.sh)\b", line)
                m = self.XPY_LINE.search(line)
                if m:
                    stage = re.search(r"--stage[ =](\S+)", m.group(2))
                    lines.append((m.group(1), stage.group(1) if stage else None))
            scripts[rel] = lines
        self.assertIn("scripts/check_compiler_unit_tests.sh", scripts)
        got = {rel: lines for rel, lines in scripts.items() if lines}
        want = {rel: [(sub, stage) for sub, stage, _ in rows] for rel, rows in self.SCRIPT_XPY.items()}
        self.assertEqual(got, want, "a gate script's x.py lines changed: classify each in SCRIPT_XPY")
        for rel, rows in self.SCRIPT_XPY.items():
            for sub, stage, scope in rows:
                if scope == "full" or stage not in ("0", "1"):
                    self.assertIn(self.SCRIPT_LEG[rel], land_gate.XPY_FULL_REQUESTS, (rel, sub, stage))

    def test_the_listed_full_requests_are_the_reviewed_ones_with_reasons(self):
        # Each entry readies the whole recipe envelope for its leg, a cost every
        # run pays: adding one is a reviewed decision (docs/DECISION_QUEUE.md).
        self.assertEqual(set(land_gate.XPY_FULL_REQUESTS), {"compiler-check", "compiler-unit-tests"})
        for leg_id, why in land_gate.XPY_FULL_REQUESTS.items():
            with self.subTest(leg=leg_id):
                self.assertGreater(len(why.split()), 8)


def git_in(root: Path, *args: str) -> str:
    env = dict(os.environ, **FIXTURE_GIT_ENV)
    return subprocess.run(["git", "-C", str(root), *args], check=True, env=env, capture_output=True,
                          text=True).stdout.strip()


class HooklessTests(unittest.TestCase):
    """LAND-GATE-HOOKLESS-1 (2026-11-02): the crates leg left the touched
    members to the pre-push hook, and in a clone where no hook is installed
    nothing tested them (a4c4157ffe's trust-vcgen). Whether the hook runs is
    decided per run; with none, the touched members and the hook's other rows
    run here."""

    # -- whether the hook is installed ------------------------------------
    def repo(self, hook: Optional[str] = "#!/bin/sh\nexit 0\n", mode: int = 0o755) -> Path:
        tmp = tempfile.TemporaryDirectory(prefix="land-gate-hook.")
        self.addCleanup(tmp.cleanup)
        root = Path(tmp.name) / "r"
        files = {"README.md": "x\n"}
        if hook is not None:
            files["scripts/hooks/pre-push"] = hook
        make_repo(root, files, symlinks={})
        if hook is not None and mode != 0o644:
            # Committed with its mode: a linked worktree checks out what git holds.
            os.chmod(root / "scripts/hooks/pre-push", mode)
            git_in(root, "commit", "-qam", "mode")
        return root

    def test_an_unset_hooks_path_is_not_installed(self):
        state = land_gate.hook_installed(self.repo())
        self.assertFalse(state.active)
        self.assertIn("core.hooksPath unset", state.why)
        self.assertEqual(state.mode, "absent")

    def test_the_trees_own_hooks_directory_with_an_executable_hook_is_installed(self):
        for value in ("scripts/hooks", "./scripts/hooks/"):
            with self.subTest(value=value):
                root = self.repo()
                git_in(root, "config", "core.hooksPath", value)
                state = land_gate.hook_installed(root)
                self.assertTrue(state.active, state.why)
                self.assertEqual(state.mode, "active")
                root2 = self.repo()
                git_in(root2, "config", "core.hooksPath", str(root2 / "scripts" / "hooks"))
                self.assertTrue(land_gate.hook_installed(root2).active)

    def test_a_linked_worktree_runs_its_own_trees_hook(self):
        root = self.repo()
        git_in(root, "config", "core.hooksPath", "scripts/hooks")
        wt = root.parent / "wt"
        git_in(root, "worktree", "add", "-q", str(wt))
        self.assertTrue(land_gate.hook_installed(wt).active)
        # The main clone's absolute path is ANOTHER tree's hook for the worktree.
        git_in(root, "config", "core.hooksPath", str(root / "scripts" / "hooks"))
        state = land_gate.hook_installed(wt)
        self.assertFalse(state.active)
        self.assertIn("not this tree's scripts/hooks", state.why)

    def test_another_or_a_stale_directory_is_not_installed(self):
        other = self.repo()
        root = self.repo()
        for value, said in ((str(other / "scripts" / "hooks"), "not this tree's scripts/hooks"),
                            (str(root / "no-such-dir"), "does not exist"),
                            (".git/hooks", "not this tree's scripts/hooks")):
            with self.subTest(value=value):
                git_in(root, "config", "core.hooksPath", value)
                state = land_gate.hook_installed(root)
                self.assertFalse(state.active)
                self.assertIn(said, state.why)

    def test_a_missing_or_non_executable_hook_is_not_installed(self):
        for root, said in ((self.repo(mode=0o644), "not executable"), (self.repo(hook=None), "")):
            with self.subTest(said=said):
                (root / "scripts" / "hooks").mkdir(parents=True, exist_ok=True)
                git_in(root, "config", "core.hooksPath", "scripts/hooks")
                state = land_gate.hook_installed(root)
                self.assertFalse(state.active)
                self.assertIn(said or "missing", state.why)

    def test_a_question_git_cannot_answer_is_not_installed(self):
        with tempfile.TemporaryDirectory(prefix="land-gate-nogit.") as tmp, \
                mock.patch.dict(os.environ, {"GIT_CEILING_DIRECTORIES": str(Path(tmp).resolve().parent)}):
            state = land_gate.hook_installed(Path(tmp))
            self.assertFalse(state.active)
            self.assertIn("cannot tell", state.why)

    # -- what the gate selects in each mode ---------------------------------
    def legs(self, hook, *paths: str) -> dict:
        g = Fixture.graph()
        sel = ls.select(g, "base", list(paths))
        h = host(14, 24, 20)
        plans = {k: host_budget.plan(h, k) for k in host_budget.KINDS}
        return {l.id: l for l in land_gate.build_legs(g, sel, "base", plans, hook)}

    # TRUST_RUSTC-1: a crates member whose tests compile through the one
    # Trust rustc resolver runs against this tree's stage 1, handed to it.
    def test_crates_members_that_reach_the_resolver_get_this_trees_stage1(self):
        with mock.patch.object(land_gate, "TRUST_RUSTC_RESOLVER", "crates/leaf"):
            crates = self.legs(HOOK_OFF, "crates/leaf/src/lib.rs")["crates-tests"]
        # crates/tester dev-depends on crates/leaf: a dependent runs it too.
        self.assertEqual(crates.stage1_members, ["crates/leaf", "crates/tester"])
        self.assertEqual(crates.prepare, land_gate.stage1_prepare(int(crates.env["CARGO_BUILD_JOBS"])))
        self.assertEqual(crates.env["TRUST_RUSTC"], str(land_gate.stage1_dir() / "bin" / "rustc"))
        self.assertFalse(crates.needs_stage1, "the lane is not an x.py suite: no --keep-stage on its command")

    def test_crates_members_that_do_not_reach_the_resolver_build_no_stage1(self):
        with mock.patch.object(land_gate, "TRUST_RUSTC_RESOLVER", "crates/leaf"):
            crates = self.legs(HOOK_OFF, "crates/walker/src/lib.rs")["crates-tests"]
        self.assertIn("--also-members", crates.command)
        self.assertIn("crates/walker", crates.command[crates.command.index("--also-members") + 1].split(","))
        self.assertEqual(crates.stage1_members, [])
        self.assertIsNone(crates.prepare)
        self.assertNotIn("TRUST_RUSTC", crates.env)

    def test_the_touched_member_runs_here_only_when_no_hook_runs(self):
        on = self.legs(HOOK_ON, "crates/leaf/src/lib.rs")["crates-tests"]
        off = self.legs(HOOK_OFF, "crates/leaf/src/lib.rs")["crates-tests"]
        also = lambda l: l.command[l.command.index("--also-members") + 1].split(",")  # noqa: E731
        self.assertIn("crates/tester", on.cache_members, "the fixture's reverse dependency is not reached")
        self.assertNotIn("crates/leaf", on.cache_members, "beside a hook the leg must not re-run its member")
        self.assertNotIn("crates/leaf", also(on))
        self.assertEqual(on.command[on.command.index("--range") + 1], "HEAD...HEAD")
        self.assertEqual((on.hookless_members, on.force_run), ([], False))
        # Hookless: the touched member is tested (in the command), never from a
        # cached PASS (not a cache member), and the lane reads the landing range.
        self.assertIn("crates/leaf", also(off))
        self.assertNotIn("crates/leaf", off.cache_members)
        self.assertEqual(off.cache_members, on.cache_members)
        self.assertEqual(off.hookless_members, ["crates/leaf"])
        self.assertTrue(off.force_run)
        self.assertEqual(off.command[off.command.index("--range") + 1], f"base...{Fixture.rev}")
        self.assertTrue(any(r.startswith("crates/leaf: touched") for r in off.reasons))

    def test_the_moved_instruments_run_from_the_landing_range_with_no_hook(self):
        # Round 2, D3: the host is NOT handed to the lane as a member (a member
        # run is judged by the zero-test rule only); the lane gets the landing
        # range and runs the instrument itself, under its instrument rules.
        lane = land_gate.crates_lane()
        fake = lambda paths: [("leaf", ["--test", "corpus"])] if "docs/data.md" in paths else []  # noqa: E731
        with mock.patch.object(lane, "moved_instruments", fake):
            off = self.legs(HOOK_OFF, "docs/data.md")["crates-tests"]
            on = self.legs(HOOK_ON, "docs/data.md")["crates-tests"]
            self.assertTrue(off.selected)
            self.assertTrue(off.force_run, "a cached PASS of the reached members must not skip the instrument")
            self.assertEqual(off.hookless_instruments, ["crates/leaf"])
            self.assertNotIn("crates/leaf", off.command[off.command.index("--also-members") + 1].split(","))
            self.assertEqual(off.command[off.command.index("--range") + 1], f"base...{Fixture.rev}")
            self.assertNotIn("crates/leaf", on.cache_members)
            self.assertEqual((on.force_run, on.hookless_instruments), (False, []))
            self.assertEqual(on.command[on.command.index("--range") + 1], "HEAD...HEAD")
        with mock.patch.object(lane, "moved_instruments", lambda paths: [("no-such-member", [])]):
            with self.assertRaisesRegex(RuntimeError, "no crates/ member"):
                self.legs(HOOK_OFF, "docs/data.md")

    def test_the_real_lanes_instrument_tails_enable_no_feature(self):
        # The superset argument: a host tested as a member runs its whole default
        # `--tests`, which holds every instrument tail that enables no feature.
        lane = land_gate.crates_lane()
        for _prefixes, host_name, tail in lane.CROSS_CRATE_INSTRUMENTS:
            self.assertFalse(any(a.startswith("--features") or a == "--all-features" for a in tail), host_name)
        for _suffix, _outside, host_name, tail in lane.CORPUS_INSTRUMENTS:
            self.assertFalse(any(a.startswith("--features") or a == "--all-features" for a in tail), host_name)

