    def test_the_plan_says_which_mode_applies_and_why(self):
        for hook, needle in ((HOOK_OFF, "LAND-GATE: the pre-push hook is not installed in this clone "
                                        "(test: core.hooksPath unset); crates-tests also runs the hook lane over "
                                        "the landing range: the 1 touched"),
                             (land_gate.PushHook(False, "test: edits the hook", "hook-path"),
                              "LAND-GATE: the pre-push hook does not answer for this landing (rule hook-path: "
                              "test: edits the hook); crates-tests also runs"),
                             (HOOK_ON, "LAND-GATE: the pre-push hook is installed in this clone and answers for "
                                       "this landing (test: the hook is installed)")):
            with self.subTest(active=hook.active):
                g = Fixture.graph()
