    def test_the_mode_is_in_the_crates_legs_key(self):
        on = self.legs(HOOK_ON, "crates/leaf/src/lib.rs")["crates-tests"]
        off = self.legs(HOOK_OFF, "crates/leaf/src/lib.rs")["crates-tests"]
        g = Fixture.graph()
        sel = ls.select(g, "base", ["crates/leaf/src/lib.rs"])
        member = "crates/tester"  # tested in both modes
        inputs = sel.per_crate["crates-tests"][member].inputs

        def parts(l):
            return land_gate.key_parts(l, g.index, member, inputs, env={"A": "1"}, toolchain={"t": 1},
                                       global_fp="g")
        self.assertEqual((parts(on).hook_mode, parts(off).hook_mode), ("active", "absent"))
        # The same hookless leg with only the mode flipped: the mode alone moves the key.
        flipped = dataclasses.replace(off, hook_mode="active")
        self.assertEqual({**parts(off).__dict__, "hook_mode": None}, {**parts(flipped).__dict__, "hook_mode": None},
                         "the member's key differs in more than the mode: the test compares nothing")
        self.assertNotEqual(parts(off).key(), parts(flipped).key(), "a hook-mode PASS would answer a hookless run")
        self.assertNotEqual(parts(on).key(), parts(off).key())
        # The landing range is not keyed: a re-merge of main that moves the base
        # keeps a reached member's PASS (what the range adds is never cached).
        h = host(14, 24, 20)
        plans = {k: host_budget.plan(h, k) for k in host_budget.KINDS}
        other = next(l for l in land_gate.build_legs(g, ls.select(g, "other", ["crates/leaf/src/lib.rs"]), "other",
                                                     plans, HOOK_OFF) if l.id == "crates-tests")
        self.assertNotEqual(other.command, off.command)
        self.assertEqual(parts(other).key(), parts(off).key())

    def test_the_covered_rows_are_the_manifests(self):
        # Manifest-driven (the push profile holds only live verifier/proof-input
        # rows today; the scoped checks the gate used to cover are not per-push
        # rows yet, a defect recorded in docs/STATUS.md). HOOK_ROWS_COVERED
        # names each row by id and exact command; a covered row that IS in
        # the push profile must still match its argued command, and every
        # push row no leg covers runs in push-rows: no verifier row is
        # silently dropped, and no scoped row is restored by expectation.
        rows = {r.id: r for r in land_gate.push_profile_rows(REPO)}
        self.assertTrue(rows, "the push profile must not be empty")
        for row_id, (command, leg_id) in land_gate.HOOK_ROWS_COVERED.items():
            if row_id not in rows:
                continue
            with self.subTest(row=row_id):
                self.assertEqual(rows[row_id].command, command)
                self.assertIn(leg_id, {l.id for l in self.legs(HOOK_OFF, "docs/README.md").values()})
        # Round 3, D3: the script behind a fixed-command leg's row is pinned. An
        # edit to it must re-argue that the leg covers what it now runs and
        # move the pin; until then push-rows runs the row. Enforced only while
        # the row is actually a push row whose coverage is being claimed.
        for row_id, pins in land_gate.COVERED_ROW_PINS.items():
            if row_id not in rows:
                continue
            for path, blob in pins:
                with self.subTest(row=row_id, script=path):
                    self.assertEqual(land_gate.git_blob_id((REPO / path).read_bytes()), blob,
                                     f"{path} is not the script {row_id}'s coverage was argued for: re-argue that "
                                     f"its leg covers what the script now runs, then move COVERED_ROW_PINS")
        head = git_in(REPO, "rev-parse", "HEAD")
        run, covered, notes = land_gate.uncovered_rows(list(rows.values()), REPO,
                                                       land_gate.LandingPush(head, head, ""))
        self.assertEqual(sorted(covered),
                         sorted(r for r in land_gate.HOOK_ROWS_COVERED if r in rows), notes)
        self.assertEqual(sorted(r.id for r in run),
                         sorted(r for r in rows if r not in covered),
                         "every uncovered push row (today: all verifier rows) must run in push-rows")
        self.assertEqual(len(run) + len(covered), len(rows))
        self.assertEqual(notes, [])
        self.assertIsNotNone(land_gate._hook_solo_re(REPO), "the hook's FAST_SOLO_RE cannot be read")

    def test_a_covered_row_whose_command_changed_runs(self):
        rows = [land_gate.PushRow("scoped.crates-tests", "true", "python3 scripts/check_crates_tests_scoped.py"),
                land_gate.PushRow("scoped.compiler-check", "true", "bash scripts/check_compiler_targets_build.sh")]
