    def test_the_legs_process_environment_is_exactly_the_constructed_one(self):
        probe = leg(id="sealed-fixture", command=["/usr/bin/env"], scripts=[], inputs=[],
                    sealed_programs=("awk", "git"))
        with mock.patch.dict(os.environ, self.hostile()):
            rc, log, run_dir = self.run_sealed(probe)
        self.assertEqual(rc, 0, log)
        env = dict(line.split("=", 1) for line in log.splitlines()[1:])
        sealed = Path(env["HOME"]).parent
        self.assertEqual(sealed.parent, self.base_root, "a gate-owned directory under the sealed base root")
        self.assertTrue(sealed.name.startswith("sealed-fixture.sealed."), sealed)
        # Spelled out, not read from the constants a mutant changes: PATH is
        # the pinned programs' directory alone.
        self.assertEqual(env, {
            "PATH": f"{sealed}/bin", "LC_ALL": "C", "LANG": "C",
            "HOME": f"{sealed}/home", "TMPDIR": f"{sealed}/tmp", "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": "/dev/null", "GIT_NO_REPLACE_OBJECTS": "1", "GIT_OPTIONAL_LOCKS": "0",
            "GIT_NO_LAZY_FETCH": "1", "GIT_CONFIG_COUNT": "3",
            "GIT_CONFIG_KEY_0": "core.fsmonitor", "GIT_CONFIG_VALUE_0": "false",
            "GIT_CONFIG_KEY_1": "core.hooksPath", "GIT_CONFIG_VALUE_1": "/dev/null",
            "GIT_CONFIG_KEY_2": "protocol.allow", "GIT_CONFIG_VALUE_2": "never"})
        self.assertFalse(sealed.exists(), "every per-run directory is removed after the run")
        with self.assertRaisesRegex(RuntimeError, "takes no environment from the gate"):
            self.run_sealed(probe, {"RAYON_NUM_THREADS": "2"})
        own = land_gate.tcb_panic_ratchet_leg([])
        own.env["TRUST_FIXTURE_SETTING"] = "1"
        with self.assertRaisesRegex(RuntimeError, "takes no environment settings of its own"):
            land_gate.leg_environment(own)

    def test_each_program_runs_as_the_binary_its_key_pins(self):
        self.write("scripts/probe.sh", 'for p in "$@"; do printf "%s %s %s\\n" "$p" "$(command -v "$p")" '
                   '"$(/usr/bin/readlink "$(command -v "$p")")"; done\nprintf "script %s\\n" "$0"\n'
                   'printf "unpinned [%s%s]\\n" "$(command -v tr)" "$(command -v env)"\n'
                   'printf "home [%s] tmp [%s]\\n" "$(/bin/ls -A "$HOME")" "$(/bin/ls -A "$TMPDIR")"\n')
        names = list(land_gate.TCB_RATCHET_PROGRAMS)
        probe = leg(id="sealed-fixture", command=["/bin/bash", "--noprofile", "--norc", "scripts/probe.sh", *names],
                    scripts=["scripts/probe.sh"], inputs=[], sealed_programs=land_gate.TCB_RATCHET_PROGRAMS)
        self.assertEqual(land_gate.pin_programs(probe), [])
        # The run starts what the key pinned, even where a resolution now
        # would name another binary.
        planted = probe.pinned = {**probe.pinned, "sed": probe.pinned["awk"]}
        with mock.patch.dict(os.environ, self.hostile()):
            rc, log, _run = self.run_sealed(probe)
        self.assertEqual(rc, 0, log)
        rows = {line.split(" ", 1)[0]: line.split(" ")[1:] for line in log.splitlines()[1:]}
        bindir = os.path.dirname(rows["awk"][0])
        for name in names:
            with self.subTest(program=name):
                self.assertEqual(rows[name], [f"{bindir}/{name}", planted[name]])
        self.assertEqual(rows["script"], [str(self.root / "scripts/probe.sh")], "by absolute path")
        self.assertIn("home [] tmp []", log, "an empty HOME and TMPDIR")
        self.assertIn("unpinned []", log, "a name the gate did not pin resolves to nothing")
        self.assertFalse(self.marker.exists())

