    def test_a_sealed_base_root_that_is_not_literal_runs_nothing_and_has_no_key(self):
        self.assertEqual(self.default_base_root, "/tmp", "the gate chooses the base root, not the clone")
        land_gate.sealed_literal(os.path.realpath(self.default_base_root), "this host's base root")
        self.failing_fixture()
        self.planted_grep(self.tmp / "a")
        for name in ("a:b", "a\\b", "a b", "a\nb", "a\tb", "a$b"):
            with self.subTest(root=name):
                root = self.tmp / name
                root.mkdir()
                with mock.patch.object(land_gate, "SEALED_BASE_ROOT", str(root)):
                    self.runs_fresh("the sealed base root")
