    def test_discovery_progress_timing_throttling_and_flush_are_stderr_only(self):
        class Stream(io.StringIO):
            flushes = 0
            def flush(self):
                self.flushes += 1
                super().flush()
        stream, stdout = Stream(), io.StringIO()
        times = iter((10.0, 12.0, 15.0, 16.0))
        reporter = land_gate._DiscoveryProgress(started=10.0, clock=lambda:next(times), stream=stream)
        with contextlib.redirect_stdout(stdout):
            reporter("own sources", "start", {"candidate_total":3})
            reporter("own sources", "progress", {"candidates_examined":1})
            reporter("own sources", "progress", {"candidates_examined":2})
            reporter("own sources", "complete", {"candidates_examined":3})
        lines = stream.getvalue().splitlines()
        self.assertEqual(len(lines), 3)
        self.assertIn("start candidate_total=3; elapsed=0.00s", lines[0])
        self.assertIn("progress candidates_examined=2; elapsed=5.00s", lines[1])
        self.assertIn("complete candidates_examined=3; elapsed=6.00s", lines[2])
        self.assertEqual(stream.flushes, 3)
        self.assertEqual(stdout.getvalue(), "")

    def test_discovery_phases_add_up_and_reach_the_run_record(self):
        # LAND-GATE-DISCOVERY-COST-1: each phase's seconds from its start to
        # its end, a phase run twice (the module closure's rounds) added up,
        # progress lines closing nothing, and silent when it does not echo.
        stream = io.StringIO()
        times = iter((0.0, 1.0, 3.0, 4.0, 4.5, 10.0, 10.0, 11.0, 12.0))
        timed = land_gate._DiscoveryProgress(started=0.0, clock=lambda: next(times), stream=stream, echo=False)
        timed("module closure", "start", {"round": 1})
        timed("module closure", "progress", {})
        timed("module closure", "complete", {"round": 1})
        timed("module closure", "start", {"round": 2})
        timed("module closure", "complete", {"round": 2})
        timed("escape candidates", "start", {})
        timed("escape candidates", "complete", {})
        timed("graph store", "written", {})  # no start: no time
        self.assertEqual(timed.timing(), {"module closure": 3.5, "escape candidates": 0.0})
        self.assertEqual(stream.getvalue(), "")
        graph = Fixture.graph()
        record = land_gate.discovery_record(timed, graph)
        self.assertEqual(record["seconds"], 12.0)
        self.assertEqual(record["phases"], {"module closure": 3.5, "escape candidates": 0.0})
        self.assertEqual(record["packages"], len(graph.packages))
        self.assertIn("reused_grep_answers", record)
        # A discovery run with no progress observer is timed whole, not itemised.
        whole = land_gate.discovery_record(None, graph, seconds=3.214)
        self.assertEqual((whole["seconds"], whole["phases"]), (3.21, None))
        self.assertEqual(whole["packages"], len(graph.packages))
        # A run's record itemises the discovery its selection came from.
        sel = ls.select(graph, "base", ["crates/leaf/src/lib.rs"])
        args = land_gate.argparse.Namespace(base="base", only=None, no_cache=True, dry_run=True)

        def compute(*_args, progress=None, **_kwargs):
            progress("escape candidates", "start", {})
            progress("escape candidates", "complete", {})
            return graph, sel, "base"
        with tempfile.TemporaryDirectory(prefix="land-gate-discovery-record.") as tmp, \
                contextlib.ExitStack() as stack:
            for name, value in (
                ("git", lambda *a, **kw: ""), ("checkout_problem", lambda *a, **kw: None),
                ("compute", compute), ("read_landing", lambda *a, **kw: stated(sel.changed)),
                ("build_legs", lambda *a, **kw: []), ("toolchain_identity", lambda: {}),
                ("config_identity", lambda: {}), ("common_dir", lambda: Path(tmp)),
                ("rustc_identity", lambda: None),
            ):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()) as err:
                land_gate.cmd_run(args)
            self.assertIn("land-gate: discovery phases escape-candidates=", err.getvalue())
            written = json.loads(next(Path(tmp).glob("trust-land/runs/*/record.json")).read_text())
        self.assertEqual(set(written["discovery"]["phases"]), {"escape candidates"})
