    def test_discovery_progress_opt_in_preserves_quiet_library_calls_and_forwarding(self):
        graph = Fixture.graph()
        selection = ls.Selection("base", graph.index.rev, [], [])
        with mock.patch.object(land_gate, "resolve_base", return_value="base"), \
                mock.patch.object(ls.TreeIndex, "load", return_value=graph.index), \
                mock.patch.object(ls, "build_graph", return_value=graph) as build, \
                mock.patch.object(ls, "changed_paths", return_value=[]), \
                mock.patch.object(land_gate, "in_place_changes", return_value=set()), \
                mock.patch.object(ls, "select", return_value=selection), \
                contextlib.redirect_stdout(io.StringIO()) as stdout, \
                contextlib.redirect_stderr(io.StringIO()) as stderr:
            self.assertEqual(land_gate.compute("base"), (graph, selection, "base"))
            self.assertEqual((stdout.getvalue(), stderr.getvalue()), ("", ""))
            self.assertNotIn("progress", build.call_args.kwargs)
            events = []
            callback = lambda *event:events.append(event)
            self.assertEqual(land_gate.compute("base", progress=callback), (graph, selection, "base"))
            self.assertIs(build.call_args.kwargs["progress"], callback)
            self.assertEqual(events[0], ("index", "start", {}))
            self.assertEqual(events[-1], ("selection", "complete", {"changed_paths":0}))

    def test_discovery_progress_full_landing_survives_failed_diagnostic_flush(self):
        graph = Fixture.graph()
        selection = ls.Selection("a" * 40, graph.index.rev, [], [])
        landing = land_gate.LandingRange("a" * 40, graph.index.rev, "local", True, (), "")
        class FailedFlush(io.StringIO):
            def flush(self):
                raise OSError("diagnostic stream unavailable")
        for stream in (io.StringIO(), FailedFlush()):
            def discover(*_args, progress=None, checkout=None):
                self.assertIs(checkout, True, "a landing's implicit HEAD is the checkout")
                self.assertIsNotNone(progress)
                self.assertIn("planning start", stream.getvalue())
                progress("manifest graph", "complete", {"packages":len(graph.packages)})
                return graph, selection, "base"
            with mock.patch.object(land_gate, "read_landing", return_value=landing), \
                    mock.patch.object(land_gate, "compute_discovery", side_effect=discover), \
                    contextlib.redirect_stderr(stream), contextlib.redirect_stdout(io.StringIO()) as stdout:
                self.assertEqual(land_gate.discover_landing("base"), (graph, selection, "base", landing))
                self.assertEqual(stdout.getvalue(), "")
        class Interrupted(io.StringIO):
            def write(self, _message):
                raise KeyboardInterrupt()
        with self.assertRaises(KeyboardInterrupt):
            land_gate._DiscoveryProgress(stream=Interrupted())("index", "start", {})

