    def test_git_diagnostic_real_conflict_survives_advice_in_other_stream(self):
        with tempfile.TemporaryDirectory(prefix="land-conflict-diagnostic-") as temporary:
            root = Path(temporary)
            path = root / "docs/DECISION_QUEUE.md"
            base = make_repo(root, {"docs/DECISION_QUEUE.md":"original\n"}, {})
            git_in(root, "branch", "incoming")
            path.write_text("local decision\n")
            git_in(root, "commit", "-qam", "local change")
            git_in(root, "checkout", "-q", "incoming")
            path.write_text("incoming decision\n")
            git_in(root, "commit", "-qam", "incoming change")
            git_in(root, "checkout", "-q", "main")
            # The root already has no parents: this fixture preserves that
            # history while requesting real Git's deprecation advice.
            (root / ".git/info/grafts").write_text(base + "\n")
            environment = {**os.environ, **FIXTURE_GIT_ENV, "GIT_CONFIG_COUNT":"2",
                "GIT_CONFIG_KEY_1":"advice.graftFileDeprecated", "GIT_CONFIG_VALUE_1":"true"}
            result = subprocess.run(["git", "-C", str(root), "merge", "--no-edit", "incoming"],
                                    capture_output=True, text=True, env=environment)
            self.assertNotEqual(result.returncode, 0)
            self.assertIn("CONFLICT (content): Merge conflict in docs/DECISION_QUEUE.md", result.stdout)
            self.assertIn("hint:", result.stderr)
            original = (result.returncode, result.stdout, result.stderr)
            self.assertEqual(land_gate._git_said(result),
                             "CONFLICT (content): Merge conflict in docs/DECISION_QUEUE.md")
            self.assertEqual((result.returncode, result.stdout, result.stderr), original)
            self.assertIn("UU docs/DECISION_QUEUE.md", git_in(root, "status", "--porcelain"))

    def test_git_diagnostic_priority_reads_both_streams(self):
        cases = (
            ("CONFLICT (content): stdout path\n", "hint: advice\nfatal: original stderr refusal\n",
             "fatal: original stderr refusal"),
            ("error: original stdout refusal\n", "hint: advice\n", "error: original stdout refusal"),
            ("fatal: original stdout refusal\n", "CONFLICT (content): stderr path\n",
             "fatal: original stdout refusal"),
            ("CONFLICT (content): stdout path\n", "Automatic merge failed; fix conflicts.\n",
             "CONFLICT (content): stdout path"),
            ("hint: stdout advice\n", "CONFLICT (content): stderr path\n",
             "CONFLICT (content): stderr path"),
            ("Automatic merge failed; fix conflicts.\n", "hint: stderr advice\n",
             "Automatic merge failed; fix conflicts."),
        )
        for stdout, stderr, expected in cases:
            with self.subTest(stdout=stdout, stderr=stderr):
                result = subprocess.CompletedProcess(["git", "fixture"], 1, stdout, stderr)
                self.assertEqual(land_gate._git_said(result), expected)

    def test_git_diagnostic_empty_and_last_line_fallbacks_preserve_raw_result(self):
        for stdout, stderr, expected in (
                (None, None, "exit 7"), ("\n", " \n", "exit 7"),
                ("stdout context\nstdout last\n", "", "stdout last"),
                ("stdout last\n", "stderr context\nstderr last\n", "stderr last"),
                ("stdout last\n", " \n", "stdout last")):
            with self.subTest(stdout=stdout, stderr=stderr):
                result = subprocess.CompletedProcess(["git", "fixture"], 7, stdout, stderr)
                self.assertEqual(land_gate._git_said(result), expected)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (7, stdout, stderr))

