    TARGO_TRUST_FILES = {
        "Cargo.toml": ('[workspace]\nmembers = ["targo-trust", "crates/trust-build-cpu", "crates/dep"]\n'
                       'default-members = ["crates/trust-build-cpu", "crates/dep"]\n'),
        "targo-trust/Cargo.toml": (
            '[features]\ndefault = []\nmc = []\nay = []\n'
            '[package]\nname = "targo-trust"\nversion = "0.1.0"\n'
            '[[bin]]\nname = "targo-trust"\npath = "src/main.rs"\n'
            '[dependencies]\ndep = { path = "../crates/dep" }\n'
            'trust-build-cpu = { path = "../crates/trust-build-cpu" }\n'
            'clean-kernel = { path = "../first-party/clean/crates/clean-kernel" }\n'),
        "targo-trust/src/main.rs": "mod doctor;\nfn main() { doctor::run(); }\n",
        "targo-trust/src/doctor.rs": "pub fn run() {}\n",
        "crates/dep/Cargo.toml": '[package]\nname = "dep"\nversion = "0.1.0"\n',
        "crates/dep/src/lib.rs": "pub fn dep() {}\n",
        "crates/trust-build-cpu/Cargo.toml": '[package]\nname = "trust-build-cpu"\nversion = "0.1.0"\n',
        "crates/trust-build-cpu/src/lib.rs": "pub fn cpu() {}\n",
        # Bootstrap's one source of the shipped feature surface.
        "src/bootstrap/src/core/build_steps/tool.rs": (
            "pub(super) fn targo_trust_in_process_features() -> Vec<String> {\n"
            "    // shipped\n"
            '    ["mc", "ay"]\n'
            "    .into_iter()\n"
            "    .map(str::to_owned)\n"
            "    .collect()\n"
            "}\n"),
    }

    def targo_trust_repo(self, root: Path, extra=None) -> str:
        """targo-trust with a crates/ path dependency, a declared development
        component it depends on, and an unpopulated first-party gitlink (a
        fresh worktree's empty directory)."""
        first = make_repo(root, dict(self.TARGO_TRUST_FILES, **(extra or {})), {})
        (root / "first-party/clean").mkdir(parents=True)
        git_in(root, "update-index", "--add", "--cacheinfo", f"160000,{first},first-party/clean")
        git_in(root, "commit", "-qm", "first-party pin")
        return git_in(root, "rev-parse", "HEAD")

    def change(self, root: Path, edits: dict, message: str = "change") -> None:
        for rel, text in edits.items():
            path = root / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        git_in(root, "add", "--", *edits)
        git_in(root, "commit", "-qm", message)

    def development_legs_of(self, root: Path, base: str):
        with mock.patch.object(land_gate, "REPO_ROOT", root):
            graph, selection, selected_base = land_gate.compute_discovery(
                base, "HEAD", False, None, land_gate.DiscoveryProfile.DEVELOPMENT)
            plans = land_gate.budget_plans(host(28, 128, 100))
            landing = land_gate.LandingRange(selected_base, selection.head, "local", True,
                                             tuple(selection.changed), "")
            with mock.patch.object(host_budget, "admitted_jobs", return_value=8):
                legs = (land_gate.declared_development_legs(graph, selection, 8, HOOK_ON, landing)
                        if isinstance(selection, land_gate.DeclaredDevelopmentSelection) else
                        land_gate.development_legs(graph, selection, land_gate.build_legs(
                            graph, selection, selected_base, plans, HOOK_ON, landing), 8, landing))
        return graph, selection, {leg.id: leg for leg in legs}

    def test_development_targo_trust_source_runs_exactly_its_own_full_leg(self):
        for path in ("targo-trust/src/doctor.rs", "targo-trust/tests/cli.rs"):
            with self.subTest(path=path), tempfile.TemporaryDirectory(prefix="land-development-targo-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root)
                self.change(root, {path: "// a one-line comment\npub fn run() {}\n"})
                _graph, selection, legs = self.development_legs_of(root, base)
                self.assertNotIsInstance(selection, land_gate.DeclaredDevelopmentSelection)
                run = {name for name, leg in legs.items() if not leg.diagnostic_only}
                # The mandatory fresh rows, and of the package/suite legs only targo-trust's.
                self.assertEqual(run, {"push-rows", "tcb-panic-ratchet", "ir-cohort", "targo-trust",
                                       "targo-trust-shipped-features"})
                leg = legs["targo-trust"]
                self.assertTrue(leg.selected and leg.force_run)
                self.assertEqual(leg.command, land_gate.landing_targo.COMMAND)
                self.assertFalse(leg.needs_stage1 or leg.prepare or leg.stage1_members or leg.cache_members)
                self.assertEqual(leg.required_gitlinks, ["first-party/clean"])
                for stage1 in ("compiler-check", "ui-trust", "run-make-trust", "native-targo-tests",
                               "bootstrap-tests", "crates-tests"):
                    self.assertTrue(legs[stage1].diagnostic_only, stage1)

    def test_development_targo_trust_leg_refuses_unpopulated_first_party_sources(self):
        with tempfile.TemporaryDirectory(prefix="land-development-targo-pins-") as tmp:
            root = Path(tmp)
            base = self.targo_trust_repo(root)
            self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
            _graph, _selection, legs = self.development_legs_of(root, base)
            leg = legs["targo-trust"]
            probe = mock.patch.object(land_gate.landing_targo, "capability_gap", return_value=None)
            with mock.patch.object(land_gate, "REPO_ROOT", root), probe as capability:
                why = land_gate.targo_unready(leg)
                self.assertIn("first-party/clean", why)
                self.assertIn("has not populated", why)
                self.assertIn("no test ran", why)
                capability.assert_not_called()
                # A populated gitlink (bound to its pin by the checkout
                # binding) leaves the leg to the normal Targo probe.
                (root / "first-party/clean/.git").write_text("gitdir: elsewhere\n")
                self.assertIsNone(land_gate.targo_unready(leg))
                capability.assert_called_once()

    def test_development_targo_trust_audited_foreign_test_reader_runs_that_test(self):
        scan = "#[test]\nfn scan() {}\n"
        blob = hashlib.sha1(b"blob %d\0" % len(scan.encode()) + scan.encode()).hexdigest()
        audit = ('[[audit]]\nfile = "crates/dep/tests/scan.rs"\n'
                 f'blob = "{blob}"\nclass = "runtime"\ntest_only = true\n'
                 'reads = ["targo-trust/*.rs", "first-party/clean"]\nlists = ["targo-trust"]\nhistory = false\n'
                 "reason = 'fixture: a test of crates/dep that scans targo-trust sources'\n")
        extra = {"crates/dep/tests/scan.rs": scan, ls.AUDITS_FILE: audit}
        for path in ("targo-trust/src/doctor.rs", "targo-trust/tests/cli.rs"):
            with self.subTest(path=path), tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root, extra)
                self.change(root, {path: "// comment\npub fn run() {}\n"})
                _graph, _selection, legs = self.development_legs_of(root, base)
                run = {name for name, leg in legs.items() if not leg.diagnostic_only}
                reader = "development-package-reader-dep-scan"
                self.assertEqual(run, {"push-rows", "tcb-panic-ratchet", "ir-cohort", "targo-trust",
                                       "targo-trust-shipped-features", reader})
                self.assertEqual(legs[reader].command[-4:], ["--manifest-path", "crates/dep/Cargo.toml",
                                                             "--test", "scan"])
                self.assertTrue(legs[reader].force_run)
                # The gitlink the audit says the test reads must be populated.
                self.assertEqual(legs[reader].required_gitlinks, ["first-party/clean"])
        # A reader whose exact default test target cannot be named refuses.
        with tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
            root = Path(tmp)
            manifest = self.TARGO_TRUST_FILES["crates/dep/Cargo.toml"] + "autotests = false\n"
            base = self.targo_trust_repo(root, dict(extra, **{"crates/dep/Cargo.toml": manifest}))
            self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
            with self.assertRaises(RuntimeError) as caught:
                self.development_legs_of(root, base)
            self.assertIn("targo-trust/src/doctor.rs: direct reader crates/dep has no development check",
                          str(caught.exception))

    def test_development_targo_trust_with_an_unowned_input_still_refuses(self):
        import land_development
        cases = (
            # Unowned path: refused before any graph, naming only that path.
            ({"unknown.py": "x = 1\n"}, "unknown.py", "discovery"),
            # Global build inputs inside targo-trust keep their refusal.
            ({"targo-trust/build.rs": "fn main() {}\n"}, "targo-trust/build.rs", "scope"),
            ({"targo-trust/Cargo.toml": self.TARGO_TRUST_FILES["targo-trust/Cargo.toml"].replace(
                "mc = []", 'mc = ["ay"]')}, "targo-trust/Cargo.toml", "scope"),
        )
        for extra, refused, where in cases:
            with self.subTest(refused=refused), tempfile.TemporaryDirectory(prefix="land-development-mixed-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root)
                self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n", **extra})
                if where == "discovery":
                    with mock.patch.object(land_gate, "REPO_ROOT", root), \
                            self.assertRaises(land_gate.LandingUnjudged) as caught:
                        land_gate.compute_discovery(base, "HEAD", False, None,
                                                    land_gate.DiscoveryProfile.DEVELOPMENT)
                else:
                    with self.assertRaises(RuntimeError) as caught:
                        self.development_legs_of(root, base)
                    self.assertNotIsInstance(caught.exception, land_gate.LandingUnjudged)
                self.assertIn(refused, str(caught.exception))
                self.assertNotIn("targo-trust/src/doctor.rs", str(caught.exception))
        # Another package compiling a targo-trust file in is a consumer the
        # targo-trust suite does not test: no development owner.
        with tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
            root = Path(tmp)
            base = self.targo_trust_repo(root)
            self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
            graph, selection, _legs = self.development_legs_of(root, base)
            graph.packages["crates/dep"].reads.append(
                ls.Read("compile", "targo-trust/src/doctor.rs", False, "fixture include"))
            scope = land_development.scope(graph, selection)
            self.assertEqual(scope.errors,
                             ["targo-trust/src/doctor.rs: direct reader crates/dep has no development check"])

    def test_development_targo_trust_runs_the_shipped_feature_surface(self):
        # The default-feature suite cfg-removes the in-process code Bootstrap
        # ships; a second fresh suite runs exactly Bootstrap's feature list.
        with tempfile.TemporaryDirectory(prefix="land-development-shipped-") as tmp:
            root = Path(tmp)
            base = self.targo_trust_repo(root)
            self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
            _graph, _selection, legs = self.development_legs_of(root, base)
            default, shipped = legs["targo-trust"], legs["targo-trust-shipped-features"]
            self.assertEqual(shipped.command, [*land_gate.landing_targo.COMMAND, "--features", "mc,ay"])
            self.assertIn("--require-test-bin", shipped.command)
            self.assertTrue(shipped.selected and shipped.force_run and not shipped.diagnostic_only)
            self.assertFalse(shipped.needs_stage1 or shipped.prepare or shipped.cache_members)
            self.assertEqual(shipped.required_gitlinks, default.required_gitlinks)
            self.assertEqual(shipped.default_env, default.default_env)
            self.assertIn("src/bootstrap/src/core/build_steps/tool.rs", shipped.inputs)
            # An unpopulated gitlink makes it NOT JUDGED before targo runs, too.
            with mock.patch.object(land_gate, "REPO_ROOT", root), \
                    mock.patch.object(land_gate.landing_targo, "capability_gap", return_value=None):
                self.assertIn("has not populated", land_gate.targo_unready(shipped))
        tool = "src/bootstrap/src/core/build_steps/tool.rs"
        broken = {
            "not a literal list": self.TARGO_TRUST_FILES[tool].replace('["mc", "ay"]', "extra()"),
            "an undeclared feature": self.TARGO_TRUST_FILES[tool].replace('"ay"', '"absent"'),
            "two definitions": self.TARGO_TRUST_FILES[tool] * 2,
            "no definition": "fn other() {}\n",
        }
        for why, text in broken.items():
            with self.subTest(why=why), tempfile.TemporaryDirectory(prefix="land-development-shipped-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root, {tool: text})
                self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
                with self.assertRaises(RuntimeError) as caught:
                    self.development_legs_of(root, base)
                self.assertIn("shipped feature surface", str(caught.exception))
        # The parser reads this repository's own Bootstrap source and manifest.
        with tempfile.TemporaryDirectory(prefix="land-development-shipped-") as tmp:
            root = Path(tmp)
            real = {tool: (REPO / tool).read_text(),
                    "targo-trust/Cargo.toml": (REPO / "targo-trust/Cargo.toml").read_text()}
            base = make_repo(root, real, {})
            graph = ls.build_graph(ls.TreeIndex.load(str(root), base))
            import land_development
            self.assertEqual(land_development.targo_trust_shipped_features(graph),
                             ["trust-mc-in-process", "trust-wp-in-process", "trust-vc-in-process",
                              "ay-backend", "ay-certify"])

    def test_development_targo_trust_non_cargo_readers_run_or_refuse(self):
        coherence = 'SURFACE = root / "targo-trust/src/pipeline/surface.rs"\n'
        spans = 'ROOTS = ("targo-trust/src/fixtures",)\n'
        cases = (
            # A declared checker that reads the file runs its own check.
            ({"scripts/check_toolchain_coherence.py": coherence}, "targo-trust/src/pipeline/surface.rs",
             "pub const X: u8 = 1;\n", "development-reader-toolchain-coherence",
             ["scripts/check_toolchain_coherence.py"]),
            ({"scripts/check_fixture_span_paths.py": spans}, "targo-trust/src/fixtures/span.jsonl",
             '{"span": "<home>/x.rs"}\n', "development-reader-fixture-span-paths",
             ["scripts/check_fixture_span_paths.py"]),
        )
        for extra, path, text, check, command in cases:
            with self.subTest(path=path), tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root, dict(extra, **{path: "// before\n"}))
                self.change(root, {path: text})
                _graph, _selection, legs = self.development_legs_of(root, base)
                run = {name for name, leg in legs.items() if not leg.diagnostic_only}
                self.assertEqual(run, {"push-rows", "tcb-panic-ratchet", "ir-cohort", "targo-trust",
                                       "targo-trust-shipped-features", check})
                self.assertEqual(legs[check].command, [sys.executable, "-B", *command])
                self.assertTrue(legs[check].force_run and legs[check].selected)
        # A scripts/tests module that names the file runs as a validation test.
        with tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
            root = Path(tmp)
            module = {"scripts/tests/doctor_reader_test.py":
                      'SOURCE = ROOT / "targo-trust" / "src" / "doctor.rs"\n'}
            base = self.targo_trust_repo(root, module)
            self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
            _graph, _selection, legs = self.development_legs_of(root, base)
            self.assertIn("scripts.tests.doctor_reader_test", legs["development-validation-tests"].command)
            self.assertFalse(legs["development-validation-tests"].diagnostic_only)
        # Any other non-Cargo file that names the file refuses; comments,
        # Markdown and Rust sources (the Cargo graph's) do not.
        quiet = {"scripts/notes.py": "# reads targo-trust/src/doctor.rs\n",
                 "notes/ABOUT.md": "see targo-trust/src/doctor.rs\n"}
        for reader, refusal in ((None, None),
                                ("tests/e2e_doctor.sh", 'grep run "$ROOT/targo-trust/src/doctor.rs"\n'),
                                ("data/doctor.json", '{"scan_roots": ["targo-trust/src"]}\n'),
                                ("scripts/doctor_glob.py", 'glob("targo-trust/*/doctor.rs")\n')):
            with self.subTest(reader=reader), tempfile.TemporaryDirectory(prefix="land-development-reader-") as tmp:
                root = Path(tmp)
                base = self.targo_trust_repo(root, dict(quiet, **({reader: refusal} if reader else {})))
                self.change(root, {"targo-trust/src/doctor.rs": "// comment\npub fn run() {}\n"})
                if reader is None:
                    _graph, _selection, legs = self.development_legs_of(root, base)
                    self.assertFalse(legs["targo-trust"].diagnostic_only)
                    continue
                with self.assertRaises(RuntimeError) as caught:
                    self.development_legs_of(root, base)
                self.assertIn(f"targo-trust/src/doctor.rs: non-Cargo reader {reader} has no development check",
                              str(caught.exception))

