    def test_program_owner_refuses_class_body_table_capture(self):
        source = ('PROGRAM_TESTS = {"old.py": ("old_test",)}\n'
                  'class C:\n'
                  ' def read():\n  return tuple(PROGRAM_TESTS)\n'
                  ' snapshot = read()\n')
