    def fixture(self, tmp):
        root = Path(tmp) / "source"
        root.mkdir()
        first = make_repo(root, {
            "Cargo.toml": '[workspace]\nmembers = ["crates/leaf"]\ndefault-members = ["crates/leaf"]\n',
            "crates/leaf/Cargo.toml": '[package]\nname = "leaf"\n',
            "crates/leaf/src/lib.rs": "pub fn original() {}\n",
            "docs/peer.md": "first\n",
            "scripts/land_gate.py": "# fixture gate reader\n",
            "extension/reader.py": "VALUE = 1\n",
        }, {})
        remote = Path(tmp) / "remote.git"
        subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(remote)], check=True)
        git_in(root, "config", "user.name", "t")
        git_in(root, "config", "user.email", "t@t")
        git_in(root, "remote", "add", "origin", str(remote))
        git_in(root, "push", "-q", "origin", "main")
        peer = Path(tmp) / "peer"
        subprocess.run(["git", "clone", "-q", str(remote), str(peer)], check=True)
        (root / "crates/leaf/src/lib.rs").write_text("pub fn local_candidate() {}\n")
        git_in(root, "add", ".")
        git_in(root, "commit", "-qm", "local candidate")
        return root, peer, first

    def publish(self, peer, path="docs/peer.md", content="incoming actual bytes\n"):
        (peer / path).write_text(content)
        git_in(peer, "add", ".")
        git_in(peer, "commit", "-qm", "peer change")
        git_in(peer, "push", "-q", "origin", "main")
        return git_in(peer, "rev-parse", "HEAD")

    def test_land_qualifies_its_snapshot_before_composing_a_remote_move(self):
        with tempfile.TemporaryDirectory(prefix="land-discovery-") as tmp, \
                mock.patch.dict(os.environ, FIXTURE_GIT_ENV):
            root, peer, first = self.fixture(tmp)
            candidate = git_in(root, "rev-parse", "HEAD")
            actual_compute = land_gate.compute
            graphs = []
            session = land_gate.DiscoverySession()
            def compute(*args, **kwargs):
                result = actual_compute(*args, **kwargs)
                graphs.append(result[0])
                if len(graphs) == 1:
                    self.publish(peer)
                return result
            with mock.patch.object(land_gate, "REPO_ROOT", root), \
                    mock.patch.object(land_gate, "compute", side_effect=compute):
                graph, selection, base, landing = land_gate.discover_landing(
                    None, compose=True, session=session)
                self.assertEqual(len(graphs), 1)
                self.assertEqual(selection.head, candidate)
                self.assertEqual(landing.tip, first)
                self.assertEqual((root / "docs/peer.md").read_text(), "first\n")
                # Evidence follows actual read sets, not the old candidate's
                # success: composition must invalidate a changed input while
                # retaining the identical independently checked leaf.
                captured_docs = graph.index.fingerprint(["docs/peer.md"])
                captured_leaf = graph.index.fingerprint(["crates/leaf"])
                # The source can now be checked. Its destination remains only
                # a captured range: the actual publication boundary refuses it.
                with self.assertRaises(land_gate.LandingRefreshRequired) as moved:
                    land_gate.landing_preflight(landing, candidate, lambda: None)
                session.compose(moved.exception.landing)
                graph, selection, base, landing = land_gate.discover_landing(
                    None, compose=True, session=session)
                self.assertNotEqual(captured_docs, graph.index.fingerprint(["docs/peer.md"]))
                self.assertEqual(captured_leaf, graph.index.fingerprint(["crates/leaf"]))
            self.assertEqual(len(graphs), 2)
            self.assertIn("crates/leaf", graph.reused_packages)
            self.assertEqual(graph.packages, ls.build_graph(graph.index).packages)
            self.assertEqual(landing.tip, git_in(peer, "rev-parse", "HEAD"))
            self.assertEqual(selection.head, git_in(root, "rev-parse", "HEAD"))
            self.assertEqual((root / "crates/leaf/src/lib.rs").read_text(), "pub fn local_candidate() {}\n")
            self.assertEqual((root / "docs/peer.md").read_text(), "incoming actual bytes\n")
            self.assertEqual(graphs[0].index.rev, git_in(root, "rev-parse", "HEAD^1"))

    def test_composed_gitlink_refuses_before_discovery_until_owned_checkout_matches(self):
        with tempfile.TemporaryDirectory(prefix="land-composed-pin-") as temporary, \
                mock.patch.dict(os.environ, FIXTURE_GIT_ENV):
            directory = Path(temporary)
            child = directory / "child"
            child.mkdir()
            old = make_repo(child, {"source.rs": "pub fn old() {}\n"}, {})
            (child / "source.rs").write_text("pub fn current() {}\n")
            git_in(child, "add", ".")
            git_in(child, "commit", "-qm", "published child source")
            new = git_in(child, "rev-parse", "HEAD")
            root = directory / "source"
            root.mkdir()
            make_repo(root, {
                "Cargo.toml": '[workspace]\nmembers=["crates/leaf"]\ndefault-members=["crates/leaf"]\n',
                "crates/leaf/Cargo.toml": '[package]\nname="leaf"\n',
                "crates/leaf/src/lib.rs": "pub fn original() {}\n",
            }, {})
            git_in(root, "-c", "protocol.file.allow=always", "submodule", "add", "-q", str(child), "first-party/component")
            owned = root / "first-party/component"
            git_in(owned, "checkout", "-q", "--detach", old)
            git_in(root, "add", ".")
            git_in(root, "commit", "-qm", "original pinned child")
            remote = directory / "remote.git"
            subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(remote)], check=True)
            git_in(root, "remote", "add", "origin", str(remote))
            git_in(root, "push", "-q", "origin", "main")
            peer = directory / "peer"
            subprocess.run(["git", "clone", "-q", str(remote), str(peer)], check=True)
            git_in(peer, "update-index", "--cacheinfo", "160000", new, "first-party/component")
            git_in(peer, "commit", "-qm", "move canonical child pin")
            git_in(peer, "push", "-q", "origin", "main")
            (root / "crates/leaf/src/lib.rs").write_text("pub fn local_candidate() {}\n")
            git_in(root, "add", ".")
            git_in(root, "commit", "-qm", "retain local source")
            with mock.patch.object(land_gate, "REPO_ROOT", root), \
                    mock.patch.object(land_gate, "compute") as compute:
                with self.assertRaisesRegex(land_gate.LandingUnjudged, "materialize the exact committed pins"):
                    land_gate.discover_landing(None, compose=True)
                compute.assert_not_called()
            self.assertEqual(git_in(owned, "rev-parse", "HEAD"), old)
            self.assertEqual(git_in(root, "rev-parse", "HEAD:first-party/component"), new)
            git_in(owned, "checkout", "-q", "--detach", new)
            with mock.patch.object(land_gate, "REPO_ROOT", root), \
                    mock.patch.object(land_gate, "compute", wraps=land_gate.compute) as compute:
                graph, selection, _base, _landing = land_gate.discover_landing(None, compose=True)
                self.assertEqual(compute.call_count, 1)
            self.assertEqual(selection.head, graph.index.rev)
            self.assertFalse(git_in(root, "status", "--porcelain"))
            self.assertIn("local_candidate", (root / "crates/leaf/src/lib.rs").read_text())

    def test_reader_ast_preserves_code_data_docstrings_types_and_encoding(self):
        source = b'# coding: utf-8\nVALUE = "caf\xc3\xa9"\ndef read():\n return VALUE\n'
        shape = land_gate._reader_ast(source)
        self.assertEqual(shape, land_gate._reader_ast(source + b'\n# updated explanation\n'))
        for changed in (
                source.replace(b'VALUE =', b'CHANGED ='),
                source.replace(b'caf\xc3\xa9', b'other'),
                b'"new module documentation"\n' + source,
                b'import os\n' + source,
                source.replace(b'def read():', b'@decorate\ndef read():'),
                source.replace(b'VALUE = "caf\xc3\xa9"', b'VALUE = "caf\xc3\xa9" # type: str'),
                source.replace(b'utf-8', b'latin-1')):
            with self.subTest(source=changed):
                self.assertNotEqual(shape, land_gate._reader_ast(changed))
        with self.assertRaises(SyntaxError):
            land_gate._reader_ast(b'not valid Python !')

