    def test_reader_trivia_never_excuses_unknown_reader_or_moved_loaded_snapshot(self):
        for cause in ("moved snapshot", "unknown reader", "changed code", "changed mode"):
            path = "extension/reader.py" if cause == "unknown reader" else "scripts/land_gate.py"
            with self.subTest(cause=cause), tempfile.TemporaryDirectory(prefix="land-reader-refuse-") as tmp, \
                    mock.patch.dict(os.environ, FIXTURE_GIT_ENV):
                root, peer, _first = self.fixture(tmp)
                original = (root / path).read_text()
                incoming = original + ("\nVALUE = 2\n" if cause == "changed code"
                                       else "\n# harmless text alone is not authority\n")
                if cause == "changed mode":
                    (peer / path).chmod(0o755)
                self.publish(peer, path, incoming)
                before = git_in(root, "rev-parse", "HEAD")
                module = types.ModuleType("land_unknown_comment_reader")
                module.__file__ = str(root / "extension/reader.py")
                with mock.patch.object(land_gate, "REPO_ROOT", root), \
                        mock.patch.dict(sys.modules, {module.__name__: module}), \
                        mock.patch.dict(land_gate._GATE_SNAPSHOT,
                                        {path: "0" * 64} if cause == "moved snapshot" else {}, clear=True):
                    with self.assertRaisesRegex(land_gate.LandingUnjudged, "loaded gate reader"):
                        land_gate.discover_landing(None, compose=True)
                self.assertEqual(git_in(root, "rev-parse", "HEAD"), before)
                self.assertEqual((root / path).read_text(), original)

