    def test_composition_status_has_the_merge_bound_and_takes_no_index_lock(self):
        # A whole-checkout status under a ref lookup's 30 s bound timed out on a
        # busy host and left `index.lock` behind (gate NOT JUDGED, then the next
        # merge failed). The lookups keep their bound; the status does not.
        with tempfile.TemporaryDirectory(prefix="land-discovery-status-") as tmp, \
                mock.patch.dict(os.environ, FIXTURE_GIT_ENV):
            root, _peer, first = self.fixture(tmp)
            head = git_in(root, "rev-parse", "HEAD")
            no_progress = land_gate.LandingRange(first, head, str(Path(tmp) / "remote.git"),
                                                  False, None, "original diff could not be read")
            asked = []
            actual = land_gate._git_ask
            def ask(repo, env, *args, **kwargs):
                asked.append((args, kwargs.get("timeout")))
                return actual(repo, env, *args, **kwargs)
            with mock.patch.object(land_gate, "REPO_ROOT", root), \
                    mock.patch.object(land_gate, "_git_ask", side_effect=ask):
                with self.assertRaisesRegex(land_gate.LandingUnjudged, "made no progress"):
                    land_gate._compose_discovery(no_progress)
            statuses = [(args, timeout) for args, timeout in asked if "status" in args]
            self.assertEqual(len(statuses), 1, asked)
            args, timeout = statuses[0]
            self.assertEqual(args[:2], ("--no-optional-locks", "status"), args)
            self.assertEqual(timeout, land_gate.remote_tips.FETCH_TIMEOUT_S)
            lookups = [timeout for args, timeout in asked
                       if "status" not in args and timeout is not None]
            self.assertTrue(lookups and all(bound == 30 for bound in lookups), asked)

