    def test_plan_run_reuses_classification_and_keeps_fresh_validation_boundaries(self):
        for development in (False, True):
            with self.subTest(development=development), tempfile.TemporaryDirectory(prefix="land-plan-run-") as tmp, \
                    mock.patch.dict(os.environ, FIXTURE_GIT_ENV), contextlib.ExitStack() as stack:
                root, _peer, _first = self.fixture(tmp)
                git_in(root, "push", "-q", "origin", "main")
                base = git_in(root, "rev-parse", "HEAD")
                (root / "docs/peer.md").write_text("new prose input\n")
                git_in(root, "commit", "-qam", "actual plan/run subject")
                stack.enter_context(mock.patch.object(land_gate, "REPO_ROOT", root))
                stack.enter_context(mock.patch.object(land_gate, "_checkout_workers_scope", contextlib.nullcontext))
                physical = stack.enter_context(mock.patch.object(land_gate, "checkout_problem", return_value=None))
                stack.enter_context(mock.patch.object(land_gate.host_budget, "measure", return_value=host(12, 64, 48)))
                stack.enter_context(mock.patch.object(land_gate, "push_hook_state", return_value=HOOK_OFF))
                stack.enter_context(mock.patch.object(land_gate, "build_legs", side_effect=lambda *_: [leg(id="push-rows", force_run=True)]))
                for name, value in (("toolchain_identity", {}), ("rustc_identity", None),
                                    ("global_fingerprint", "DATA-global"), ("stage1_key", "DATA-stage1")):
                    stack.enter_context(mock.patch.object(land_gate, name, return_value=value))
                stack.enter_context(mock.patch.object(land_gate, "common_dir", return_value=Path(tmp) / "gate-DATA"))
                stack.enter_context(mock.patch.object(land_gate, "targo_unready", return_value=None))
                cached = stack.enter_context(mock.patch.object(land_gate, "cache_lookup", return_value={"run":"old"}))
                def run_row(_leg, directory, *_args):
                    log = directory / "row-DATA.log"
                    log.write_text("synthetic fresh row terminal\n")
                    return 0, 0.0, str(log), False
                rows = stack.enter_context(mock.patch.object(land_gate, "run_leg", side_effect=run_row))
                scan = stack.enter_context(mock.patch.object(ls, "scan_escapes", wraps=ls.scan_escapes))
                select = stack.enter_context(mock.patch.object(ls, "select", wraps=ls.select))
                verify = stack.enter_context(mock.patch.object(land_gate, "verify_graph", return_value=[]))
                stack.enter_context(contextlib.redirect_stdout(io.StringIO()))
                stack.enter_context(contextlib.redirect_stderr(io.StringIO()))
                session = land_gate.DiscoverySession()
                args = land_gate.argparse.Namespace(head="HEAD", base=base, verify_graph=False,
                                                    json=False, development=development, run=True, no_cache=False)
                self.assertEqual(land_gate.cmd_plan(args, session), 0)
                # Classification is retained, while another run still judges
                # its actual live row and physical source boundaries afresh.
                run_args = land_gate.argparse.Namespace(base=base, only=None, no_cache=False,
                                                        dry_run=False, development=development)
                self.assertEqual(land_gate.cmd_run(run_args, session), 0)
                self.assertEqual(scan.call_count, 1)
                self.assertEqual(select.call_count, 3)
                self.assertEqual(verify.call_count, 0 if development else 2)
                self.assertEqual(rows.call_count, 2)
                self.assertGreaterEqual(physical.call_count, 6)
                cached.assert_not_called()
                self.assertIsNotNone(session.graph)

