                    path = root / ({"source":"crates/leaf/src/lib.rs", "namespace":"docs/added.md",
                                    "reader":"scripts/land_gate.py", "uncommitted-reader":"scripts/land_gate.py"}[mutation])
                    path.write_text("pub fn new_source() {}\n" if mutation == "source" else "# changed input\n")
                    if mutation != "uncommitted-reader":
                        git_in(root, "add", ".")
                        git_in(root, "commit", "-qm", "change actual discovery input")
                    with mock.patch.object(ls, "scan_escapes", wraps=ls.scan_escapes) as scan:
                        if "reader" in mutation:
                            with self.assertRaisesRegex(land_gate.LandingUnjudged, "reader changed"):
                                land_gate._compute_in_session(
                                    session, first, "HEAD", False, land_gate.DiscoveryProfile.FULL)
                            scan.assert_not_called()
                            self.assertIsNone(session.graph)
                        else:
                            graph, _selection, _base = land_gate._compute_in_session(
                                session, first, "HEAD", False, land_gate.DiscoveryProfile.FULL)
                            self.assertEqual(scan.call_count, 1)
                            self.assertNotIn("_classification_reused_from", graph.__dict__)

