    def test_the_wp_observer_refuses_under_cfg_test_before_any_git(self):
        # The bootstrap half of the same premise, in the pinned blobs
        # themselves: run() and require_clean() refuse under cfg(test) before
        # they act, and (second pass) so does every git of trust_repo_cache
        # whose root is this checkout, whoever calls.
        text = (REPO / self.WP).read_text()
        for start, first_act in (("pub(super) fn run(builder", "Publication::claim("),
                                 ("fn require_clean(builder", "require_clean_source(")):
            with self.subTest(start=start):
                body = text[text.index(start):]
                guard, act = body.index("if cfg!(test) {"), body.index(first_act)
                self.assertLess(guard, act)
                self.assertIn("return Err(", body[guard:act])
        cache = (REPO / "src/bootstrap/src/utils/trust_repo_cache.rs").read_text()
        command = cache[cache.index("pub(crate) fn git_command(root: &Path) -> Command {"):]
        self.assertLess(command.index("refuse_this_checkout_under_test(root);"), command.index('Command::new("git")'))
        self.assertIn("fn a_unit_test_never_runs_git_in_this_checkout()",
                      (REPO / "src/bootstrap/src/utils/trust_repo_cache/tests.rs").read_text())

