            # Leave Bootstrap's harness default absent: its Cargo builder uses
            # the rescaled x.py jobs, rather than an inherited host-wide value.
            for name in ("compiler-check", "compiler-unit-tests", "bootstrap-tests", "tidy"):
                self.assertNotIn("RUST_TEST_THREADS", land_gate.leg_environment(legs[name]))
            self.assertEqual(legs["compiler-unit-tests"].env["CARGO_BUILD_JOBS"], "1")
            self.assertEqual(legs["ui-trust"].env["RUST_TEST_THREADS"], "4")

