    def test_run_starts_its_one_worker_pool_before_it_asks_git_or_targo_anything(self):
        # LAND-GATE-PUSHROWS-SPEED-1, the third review: `compute` runs `targo
        # metadata`, which runs the commit's `build.rustc-wrapper`; workers
        # started at the first complete check loaded an interpreter and library
        # that wrapper could have changed. Every Git question, `compute` and
        # every check (before and after the legs) sees the same pool, ready.
        g = Fixture.graph()
        sel = ls.select(g, "base", ["compiler/rustc_a/src/lib.rs"])
        l = leg(id="targo-trust")
        args = land_gate.argparse.Namespace(base="base", only=None, no_cache=False, dry_run=False)
        seen = []

        def observe(what, answer):
            def call(*a, **kw):
                workers = land_gate._ACTIVE_CHECKOUT_WORKERS
                seen.append((what, None if workers is None else
                             (id(workers), workers.jobs, workers._ready, len(workers._procs), workers.fallback)))
                return answer
            return call

        with tempfile.TemporaryDirectory(prefix="land-gate-checkout-pool.") as tmp, \
                mock.patch.dict(os.environ, {"BUILD_SLOT_HELD": "1", "CARGO_BUILD_JOBS": "7",
                                             "TRUST_CHECKOUT_JOBS": "2"}), \
                contextlib.ExitStack() as stack:
            for name in ADVERTISED_DESCRIPTORS:
                os.environ.pop(name, None)
            for name, value in (
                ("git", observe("git", "")), ("checkout_problem", observe("check", None)),
                ("compute", observe("compute", (g, sel, "base"))),
                ("read_landing", lambda *a, **kw: stated(sel.changed)),
                ("build_legs", lambda *a, **kw: [l]),
                ("toolchain_identity", lambda: {}),
                ("common_dir", lambda: Path(tmp)),
                ("rustc_identity", lambda: None),
                ("config_identity", lambda: {}),
            ):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            stack.enter_context(mock.patch.object(land_gate, "cache_lookup", return_value={"run": "old"}))
            stack.enter_context(mock.patch.object(land_gate, "run_leg"))
            with contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(land_gate.cmd_run(args), 0)
        self.assertEqual(seen[0][0], "git", "the run's first question is Git's")
        self.assertIn("compute", [what for what, _pool in seen])
        # The history check, then one complete pass before the legs: the leg
        # is a cached PASS, which starts no program, so that pass answers the
        # later boundaries (SourceBinding, under its HEAD guard).
        self.assertEqual([what for what, _pool in seen].count("check"), 2, seen)
        pools = {pool for _what, pool in seen}
        self.assertEqual(len(pools), 1, f"one pool, unchanged, ready before the first question: {seen}")
        self.assertEqual(next(iter(pools))[1:], (2, 2, 2, ""))
        self.assertIsNone(land_gate._ACTIVE_CHECKOUT_WORKERS)

    def run_one_leg(self, l, *, reusable=True, unready=None, dry_run=True):
        g = Fixture.graph()
        sel = ls.select(g, "base", ["crates/leaf/src/lib.rs"])
        args = land_gate.argparse.Namespace(base="base", only=None, no_cache=True, dry_run=dry_run)
        with tempfile.TemporaryDirectory(prefix="land-gate-crates-stage1.") as tmp, \
                contextlib.ExitStack() as stack:
            for name, value in (
                ("git", lambda *a, **kw: ""), ("checkout_problem", lambda *a, **kw: None),
                ("compute", lambda *a, **kw: (g, sel, "base")),
                ("read_landing", lambda *a, **kw: stated(sel.changed)),
                ("build_legs", lambda *a, **kw: [l]),
                ("toolchain_identity", lambda: {"seed": "same-toolchain"}),
                ("config_identity", lambda: {"bootstrap.toml": "same-config"}),
                ("common_dir", lambda: Path(tmp)),
                ("rustc_identity", lambda: None),
                ("xpy_unready", lambda: unready),
            ):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            asked = stack.enter_context(mock.patch.object(land_gate, "stage1_reusable", return_value=reusable))
            with contextlib.redirect_stdout(io.StringIO()):
                land_gate.cmd_run(args)
            record = next(Path(tmp).glob("trust-land/runs/*/record.json"))
            return land_gate.json.loads(record.read_text())["legs"][l.id], asked, l

    def crates_leg(self, **kw):
        base = dict(id="crates-tests", command=[sys.executable, "scripts/check_crates_tests_scoped.py", "--range",
                                                "HEAD...HEAD", "--also-members", "crates/leaf"],
                    inputs=["crates/leaf"], targets=["crates/leaf"], cache_members=["crates/leaf"],
                    prepare=land_gate.stage1_prepare(4), stage1_members=["crates/leaf"],
                    env={"TRUST_RUSTC": str(land_gate.stage1_dir() / "bin" / "rustc")})
        base.update(kw)
        return leg(**base)

    def test_a_crates_leg_that_prepares_stage1_reuses_it_on_its_prepare_only(self):
        entry, asked, l = self.run_one_leg(self.crates_leg())
        asked.assert_called_once()
        self.assertEqual(entry["stage1"], "reused (stamp matches the stage-1 inputs)")
        self.assertNotIn("--keep-stage", entry["command"], "the crates lane takes no x.py flags")
        self.assertEqual(l.prepare[-4:], ["--keep-stage", "0", "--keep-stage-std", "1"])

    def test_a_crates_leg_that_prepares_stage1_rebuilds_a_stale_one(self):
        entry, asked, l = self.run_one_leg(self.crates_leg(), reusable=False)
        asked.assert_called_once()
        self.assertEqual(entry["stage1"], "built")
        self.assertNotIn("--keep-stage", l.prepare)

    def test_a_crates_leg_that_prepares_stage1_is_held_to_seed_admission(self):
        # Not a dry run: readiness is judged only where the leg would execute,
        # and an unready leg stops before anything runs.
        entry, asked, _l = self.run_one_leg(self.crates_leg(), unready="a configured seed", dry_run=False)
        self.assertEqual(entry["outcome"], "NOT JUDGED (a configured seed)")
        asked.assert_not_called()

    def test_a_crates_leg_without_stage1_members_neither_builds_nor_asks(self):
        entry, asked, _l = self.run_one_leg(self.crates_leg(prepare=None, stage1_members=[], env={}))
        asked.assert_not_called()
        self.assertNotIn("stage1", entry)
        self.assertEqual(entry["outcome"], "DRY RUN")

    # TRUST_RUSTC-1: a crates member that compiles through a Trust rustc is
    # answered from the cache only by a PASS measured on the stage 1 this tree
    # would prepare (its stage-1 inputs) that is still the one on disk, and a
    # narrowed leg keeps the prepare while such a member is still to run. Two
    # gate runs over ONE cache (the real cache_lookup and cache_store); the
    # stage-1 inputs key and the on-disk stage 1 are each run's.
    def run_twice_on_one_cache(self, runs):
        """`runs`: [(stage-1 inputs key, on-disk stage 1, member inputs)] in
        order; returns each run's (crates-tests record entry, prepare steps run)."""
        g = Fixture.graph()
        sel = ls.select(g, "base", ["crates/leaf/src/lib.rs"])
        args = land_gate.argparse.Namespace(base="base", only=None, no_cache=False, dry_run=False)
        out = []
        with tempfile.TemporaryDirectory(prefix="land-gate-crates-stage1-cache.") as tmp:
            for n, (s1_key, identity, member_inputs) in enumerate(runs):
                l = self.crates_leg(cache_members=["crates/leaf", "crates/tester"],
                                    targets=["crates/leaf", "crates/tester"],
                                    command=[sys.executable, "scripts/check_crates_tests_scoped.py", "--range",
                                             "HEAD...HEAD", "--also-members", "crates/leaf,crates/tester"],
                                    member_inputs=dict(member_inputs))
                ran = []

                def run_leg(leg, *a, **kw):
                    ran.append(list(leg.prepare or []))
                    log = Path(tmp) / f"{leg.id}.{n}.{len(ran)}.log"
                    log.write_text("ok\n", encoding="utf-8")
                    return 0, 1.0, str(log), False

                with contextlib.ExitStack() as stack:
                    for name, value in (
                        ("git", lambda *a, **kw: ""), ("checkout_problem", lambda *a, **kw: None),
                        ("compute", lambda *a, **kw: (g, sel, "base")),
                        ("read_landing", lambda *a, **kw: stated(sel.changed)),
                        ("build_legs", lambda *a, **kw: [l]),
                        ("toolchain_identity", lambda: {"seed": "same-toolchain"}),
                        ("config_identity", lambda: {"bootstrap.toml": "same-config"}),
                        ("common_dir", lambda: Path(tmp)),
                        ("rustc_identity", lambda stage1=None, ident=identity: ident),
                        ("xpy_unready", lambda: None),
                        ("stage1_key", lambda *a, k=s1_key, **kw: k),
                        ("stage1_stamp_path", lambda: Path(tmp) / "stamp.json"),
                        ("stage1_reusable", lambda *a, **kw: False),
                        ("targo_unready", lambda leg: None),  # a faked leg runs no targo (round 5, D3)
                        ("run_leg", run_leg),
                        ("push_hook_state", lambda *a, **kw: HOOK_OFF),
                    ):
                        stack.enter_context(mock.patch.object(land_gate, name, value))
                    stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
                    with contextlib.redirect_stdout(io.StringIO()):
                        land_gate.cmd_run(args)
                records = sorted(Path(tmp).glob("trust-land/runs/*/record.json"))
                out.append((land_gate.json.loads(records[-1].read_text())["legs"]["crates-tests"], ran))
        return out

    MEMBER_INPUTS = {"crates/leaf": ["crates/leaf"], "crates/tester": ["crates/tester"]}

    def test_a_stage1_members_pass_is_reused_on_the_same_stage1(self):
        (first, _), (second, ran) = self.run_twice_on_one_cache(
            [("s1-T1", ["stage 1 of T1"], self.MEMBER_INPUTS)] * 2)
        self.assertEqual((first["outcome"], first["stage1"]), ("PASS", "built"))
        self.assertEqual(second["outcome"], "CACHED PASS", second)
        self.assertEqual(ran, [])

    def test_a_stage1_members_pass_from_an_earlier_trees_stage1_is_a_miss(self):
        # Only the stage-1 inputs moved (a merge brought compiler/ changes);
        # the member's own inputs and the stage 1 on disk are T1's.
        (_first, _), (second, ran) = self.run_twice_on_one_cache(
            [("s1-T1", ["stage 1 of T1"], self.MEMBER_INPUTS), ("s1-T2", ["stage 1 of T1"], self.MEMBER_INPUTS)])
        self.assertNotEqual(second["outcome"], "CACHED PASS",
                            "a PASS measured on T1's stage 1 answered for T2, whose stage-1 inputs differ")
        self.assertEqual((second["outcome"], second["stage1"]), ("PASS", "built"))
        self.assertEqual(second.get("cached_members"), ["crates/tester"])
        self.assertEqual(len(ran), 1)
        self.assertEqual(ran[0][:5], land_gate.stage1_prepare(1)[:5])

    def test_a_stage1_members_pass_on_a_replaced_stage1_is_a_miss(self):
        # Same stage-1 inputs, but the stage 1 on disk was rebuilt or replaced
        # since the PASS (by anything): the narrowed leg keeps its prepare.
        (_first, _), (second, ran) = self.run_twice_on_one_cache(
            [("s1-T1", ["stage 1 of T1"], self.MEMBER_INPUTS), ("s1-T1", ["another stage 1"], self.MEMBER_INPUTS)])
        self.assertEqual((second["outcome"], second["stage1"]), ("PASS", "built"), second)
        self.assertEqual(second.get("cached_members"), ["crates/tester"])
        self.assertEqual(len(ran), 1)
        self.assertEqual(ran[0][:5], land_gate.stage1_prepare(1)[:5],
                         "a narrowed leg dropped the prepare its remaining stage-1 member runs on")

    def test_a_narrowed_leg_drops_the_prepare_once_its_stage1_members_are_cached(self):
        moved = {**self.MEMBER_INPUTS, "crates/tester": ["crates/leaf"]}
        (_first, _), (second, ran) = self.run_twice_on_one_cache(
            [("s1-T1", ["stage 1 of T1"], self.MEMBER_INPUTS), ("s1-T1", ["stage 1 of T1"], moved)])
        self.assertEqual(second.get("cached_members"), ["crates/leaf"], second)
        self.assertEqual(ran, [[]], "only crates/tester runs, and it needs no stage 1")
        self.assertNotIn("stage1", second)

    def test_equivalent_stage1_child_environments_share_the_production_key(self):
        g = Fixture.graph()
        sel = ls.select(g, "base", ["compiler/rustc_a/src/lib.rs"])
        args = land_gate.argparse.Namespace(base="base", only=None, no_cache=True, dry_run=True)
        keys = []
        for caller in (None, "7", "2"):
            with self.subTest(caller=caller), \
                    tempfile.TemporaryDirectory(prefix="land-gate-stage1-env.") as tmp, \
                    mock.patch.dict(os.environ, {"BUILD_SLOT_HELD": "1", "CARGO_BUILD_JOBS": "7"}), \
                    contextlib.ExitStack() as stack:
                if caller is None:
                    os.environ.pop("RAYON_NUM_THREADS", None)
                else:
                    os.environ["RAYON_NUM_THREADS"] = caller
                l = leg(needs_stage1=True, default_env={"RAYON_NUM_THREADS": "7"})
                for name, value in (
                    ("git", lambda *a, **kw: ""), ("checkout_problem", lambda *a, **kw: None),
                    ("compute", lambda *a, **kw: (g, sel, "base")),
                    ("read_landing", lambda *a, **kw: stated(sel.changed)),
                    ("build_legs", lambda *a, **kw: [l]),
                    ("toolchain_identity", lambda: {"seed": "same-toolchain"}),
                    ("config_identity", lambda: {"bootstrap.toml": "same-config"}),
                    ("common_dir", lambda: Path(tmp)),
                    ("rustc_identity", lambda: None),
                ):
                    stack.enter_context(mock.patch.object(land_gate, name, value))
                stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
                reusable = stack.enter_context(mock.patch.object(land_gate, "stage1_reusable", return_value=True))
                with contextlib.redirect_stdout(io.StringIO()):
                    self.assertEqual(land_gate.cmd_run(args), 0)
                keys.append(reusable.call_args.args[0])
                record = next(Path(tmp).glob("trust-land/runs/*/record.json"))
                command = land_gate.json.loads(record.read_text())["legs"]["ui-trust"]["command"]
                self.assertEqual(command[-4:], ["--keep-stage", "0", "--keep-stage-std", "1"])
        self.assertEqual(keys[0], keys[1], "default and explicit seven have the same effective child environment")
        self.assertNotEqual(keys[0], keys[2], "a genuinely different Rayon setting changes the stage-1 key")

    def test_admitted_share_also_caps_the_crates_pool(self):
        with mock.patch.dict(os.environ, {"BUILD_SLOT_HELD": "1", "CARGO_BUILD_JOBS": "3"}), \
                contextlib.redirect_stdout(io.StringIO()):
            l = leg(env={"TRUST_CRATES_TESTS_JOBS": "5"})
            chose = land_gate.rescale(l, host(28, 128, 100))
        self.assertEqual(l.env["TRUST_CRATES_TESTS_JOBS"], "3")
        self.assertEqual(chose["jobs"], {"rustc-build": 3, "ui-test": 3, "crates-test": 3})

    def test_unadmitted_cargo_limit_does_not_change_host_scaling(self):
        with mock.patch.dict(os.environ, {"CARGO_BUILD_JOBS": "7"}):
            self.assertEqual(land_gate.budget_plans(host(28, 128, 100))["rustc-build"].jobs, 28)

    def test_malformed_admitted_share_refuses_before_planning(self):
        for raw in (None, "", "0", "-1", "not-a-number", "1.5"):
            with self.subTest(raw=raw), \
                    mock.patch.dict(os.environ, {"BUILD_SLOT_HELD": "1"}), \
                    mock.patch.object(host_budget, "plan") as plan:
                if raw is None:
                    os.environ.pop("CARGO_BUILD_JOBS", None)
                else:
                    os.environ["CARGO_BUILD_JOBS"] = raw
                with self.assertRaisesRegex(RuntimeError, "positive integer CARGO_BUILD_JOBS"):
                    land_gate.budget_plans(host(28, 128, 100))
                plan.assert_not_called()

    def test_overlap_admission(self):
        self.assertFalse(host_budget.admit_overlap(host(14, 24, 14))[0])
        self.assertTrue(host_budget.admit_overlap(host(20, 128, 100))[0])

    def test_governor_floors_scale(self):
        self.assertEqual(host_budget.governor_floors(host(14, 24, 10)), (2, 3))
        self.assertEqual(host_budget.governor_floors(host(20, 128, 10)), (8, 16))

    def test_governor_only_reads_memory_after_recreator_clears_cargo_environment(self):
        # Immutable recreation passes --jobs explicitly and forbids ambient
        # CARGO_*. Its pressure watcher asks only for governor floors, not a
        # new child plan; preserving this query does not grant CPU admission.
        with mock.patch.dict(os.environ, {"BUILD_SLOT_HELD": "1"}), \
                mock.patch.object(host_budget, "measure", return_value=host(32, 512, 500)), \
                contextlib.redirect_stdout(io.StringIO()) as output, \
                contextlib.redirect_stderr(io.StringIO()):
            os.environ.pop("CARGO_BUILD_JOBS", None)
            self.assertEqual(host_budget.main(["governor"]), 0)
            self.assertIn("TRUST_GOV_CRITICAL_GIB=32", output.getvalue())

    def test_vm_stat_and_meminfo(self):
        text = ("Mach Virtual Memory Statistics: (page size of 16384 bytes)\nPages free:  10.\n"
                "Pages active: 99.\nPages inactive: 20.\nPages speculative: 3.\nPages purgeable: 2.\n")
        self.assertEqual(host_budget.parse_vm_stat(text)[0], 35 * 16384)
        with self.assertRaises(host_budget.HostUnmeasurable):
            host_budget.parse_vm_stat("Pages free: 1.\n")
        total, avail = host_budget.parse_meminfo("MemTotal: 100 kB\nMemFree: 1 kB\nMemAvailable: 40 kB\n")
        self.assertEqual((total, avail), (100 * 1024, 40 * 1024))


