@contextlib.contextmanager
def gate_date_on(day):
    """Declare `day` as the run's date (land_gate.gate_date) for the block."""
    saved = list(land_gate._GATE_DATE)
    land_gate._GATE_DATE[:] = [day]
    try:
        yield
    finally:
        land_gate._GATE_DATE[:] = saved


@contextlib.contextmanager
def patched(obj, name, value):
    old = getattr(obj, name)
    setattr(obj, name, value)
    try:
        yield
    finally:
        setattr(obj, name, old)


def _m_closure_roots_only(self, roots):
    return {r for r in roots if r in self.packages or r in self.gitlinks}


def _m_reaches_closure_only(path, inputs):
    return ls._under_any(path, {i for i in inputs if not i.startswith("docs") and not i.startswith("tests")}) \
        or ls.EVERYTHING in inputs


def _m_everything_reason(path):
    return None if path.endswith("build.rs") or path.endswith("Cargo.toml") else ORIG["everything_reason"](path)


def _m_classify_unknown_prose(g, path):
    kind, why = ORIG["classify"](g, path)
    return ("prose", "") if kind == "unmapped" else (kind, why)


def _m_in_test_always(self, pos):
    return True


def _m_ui_partial_aux(g, paths):
    return sorted({p for p in paths})


def _m_no_include(g, pkg, path, text, *ctx):  # ctx: a file compiled from elsewhere (_scan_one)
    text = text.replace("include_str!", "include_strx!")
    getattr(g, "lex_cache", {}).pop(path, None)  # the scan reads the lexed text it is handed
    return ORIG["_scan_file"](g, pkg, path, text, *ctx)


def _m_harvest_none(g, pkg, top, *rows):
    return None


def _m_key_drops(field):
    def key(self):
        doc = {"schema": land_gate.SCHEMA, **{k: v for k, v in self.__dict__.items() if k != field}}
        return land_gate.hashlib.sha256(land_gate.json.dumps(doc, sort_keys=True, default=str).encode()).hexdigest()
    return key


def _m_env_empty(env=None):
    return {}


def _m_ignore_lock_prefix():
    original = land_gate.env_identity
    return patched(land_gate, "env_identity",
                   lambda env=None: {k: v for k, v in original(env).items()
                                     if not k.startswith("TRUST_BUILD_LOCK_")})


def _m_plan_cpu_only(h, kind, max_jobs=None):
    p = ORIG["plan"](h, kind, max_jobs)
    return p._replace(jobs=h.cpus, refused=None) if p.jobs else p._replace(jobs=h.cpus, cap=p.want, refused=None)


def _m_plan_cap_room(h, kind, max_jobs=None):
    p = ORIG["plan"](h, kind, max_jobs)
    return p._replace(cap=max(p.room, p.cap))


def _m_plan_refuse_below_want(h, kind, max_jobs=None):
    p = ORIG["plan"](h, kind, max_jobs)
    return p._replace(refused="x", jobs=0) if p.room < p.want else p


def _m_metadata_always_online(ws, offline=True):
    return ORIG["metadata_argv"](ws, False)



def _m_lock_redirect_ignores_include(cwd, env=None, home=None):
    why = ORIG["lock_redirect"](cwd, env, home)
    if why is None:
        return None
    path = Path(why.split(" ", 1)[0])
    try:
        import tomllib
        config = tomllib.loads(path.read_text())
    except (OSError, ValueError):
        return why
    return None if "include" in config and "lockfile-path" not in config.get("resolver", {}) else why


def _m_lock_redirect_one_home(cwd, env=None, home=None):
    env = dict(os.environ if env is None else env)
    if env.get("CARGO_HOME"):
        env.pop("TARGO_HOME", None)
        return ORIG["lock_redirect"](cwd, env, Path("/nonexistent-home"))
    return ORIG["lock_redirect"](cwd, env, home)


def _m_offline_metadata_ignores_redirect(ws):
    with patched(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None):
        return ORIG["offline_metadata"](ws)


def _m_fill_registry_ignores_redirect(ws):
    with patched(land_gate, "lock_redirect", lambda cwd, env=None, home=None: None):
        return ORIG["fill_registry"](ws)


_M_TOMLLIB_WITHOUT_UNSTABLE = types.SimpleNamespace(
    loads=lambda text: {key: value for key, value in tomllib.loads(text).items() if key != "unstable"},
    TOMLDecodeError=tomllib.TOMLDecodeError)


def _m_lock_redirect_without_shadow(cwd, env=None, home=None):
    for path, outside in land_gate.lock_config_files(cwd, env, home):
        why = land_gate.lock_config_reason(path, outside)
        if why:
            return why
    return None


def _m_lock_config_reason_cargo_file_unreadable(path, outside):
    if path.parent.is_file():
        return f"{path} cannot be read"
    return ORIG["lock_config_reason"](path, outside)


def _m_lock_redirect_home_raises(cwd, env=None, home=None):
    shadow = cwd / ".cargo" / "config"
    if shadow.exists():
        return f"{shadow} stands beside the committed config.toml"
    return _m_lock_redirect_without_shadow(cwd, env, home)


def _m_lock_config_files_home_verbatim(cwd, env=None, home=None):
    if home is None:
        home = Path((os.environ if env is None else env).get("HOME", ""))
    return ORIG["lock_config_files"](cwd, env, home)


def _m_lock_redirect_nearest_only(cwd, env=None, home=None):
    for path, outside in land_gate.lock_config_files(cwd, env, home):
        if path.exists():
            return land_gate.lock_config_reason(path, outside)
    return None


