def _m_accept_changed_audit_blob(graph):
    audits = ORIG["load_audits"](graph)
    for path, row in audits.items():
        if path in graph.index.entries:
            row["blob"] = graph.index.entries[path][1]
    return audits


def _m_drop_fixture_script_read(graph):
    audits = ORIG["load_audits"](graph)
    path = "targo-trust/tests/bridge_pin_gate.rs"
    if path in audits:
        audits[path] = dict(audits[path], reads=[])
    return audits


@contextlib.contextmanager
def patched_many(*triples):
    with contextlib.ExitStack() as stack:
        for obj, name, value in triples:
            stack.enter_context(patched(obj, name, value))
        yield


@contextlib.contextmanager
def patched_leg(leg_id, attr, value):
    """LEGS holds direct references (roots, extra, partial): patch the LegSpec."""
    spec = next(l for l in ls.LEGS if l.id == leg_id)
    with patched(spec, attr, value):
        yield


@contextlib.contextmanager
def patched_leg_scripts(leg_id, dropped):
    """build_legs with `dropped` left out of one leg's scripts (its key's code)."""
    def build(g, sel, base, plans, hook, landing=None):
        legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
        for l in legs:
            if l.id == leg_id:
                l.scripts = [x for x in l.scripts if x != dropped]
        return legs
    with patched(land_gate, "build_legs", build):
        yield


def _m_unit_lane_needs_a_crate(g, sel, base, plans, hook, landing=None):
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    for l in legs:
        if l.id == "compiler-unit-tests":
            l.selected = any(m != land_gate.RUN_MAKE_MEMBER for m in l.cache_members)
    return legs


def _m_crates_leg_sets_its_own_budget(g, sel, base, plans, hook, landing=None):
    # The rule before CRATES-TIME-1: the leg's own max(1200, 240 s x members).
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    for l in legs:
        if l.id == "crates-tests":
            l.env["TRUST_CRATES_TESTS_BUDGET_S"] = str(max(1200, 240 * len(l.cache_members)))
    return legs


def _m_run_make_member_on_crate_inputs(g, sel, base, plans, hook, landing=None):
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    for l in legs:
        if l.id == "compiler-unit-tests":
            l.member_inputs = {}
            l.stage1_members = []
            l.command = [c for c in l.command if c != "--run-make"] if not l.cache_members else l.command
    return legs


def _m_targo_unbounded_test_workers(g, sel, base, plans):
    legs = ORIG["build_legs"](g, sel, base, plans)
    for leg in legs:
        if leg.id == "targo-trust":
            leg.env.pop("RUST_TEST_THREADS", None)
    return legs


