def _m_judge_ignores_started_targets(log, rc, accepted, targets):
    log = "\n".join(line for line in log.splitlines() if not land_gate.SUITE_START.match(line))
    return ORIG["judge_suite"](log, rc, accepted, targets)

def _m_crates_leg_ignores_the_mode(g, sel, base, plans, hook, landing=None):
    # The leg as built beside a hook, whether or not one runs.
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    hooked = {l.id: l for l in ORIG["build_legs"](g, sel, base, plans, land_gate.PushHook(
        True, "mutant", "installed", frozenset(land_gate.HOOK_ROWS_COVERED)), landing)}
    return [hooked["crates-tests"] if l.id == "crates-tests" else l for l in legs]


def _m_hook_any_path(root=None):
    # Installed whenever core.hooksPath is set, wherever it points (patches hook_installed).
    proc = subprocess.run(["git", "-C", str(root or land_gate.REPO_ROOT), "config", "--get", "core.hooksPath"],
                          capture_output=True, text=True)
    return land_gate.PushHook(proc.returncode == 0, "mutant")


def _m_grade_quarantined_green_passes(row, status, log_text, quarantine, published=None, why="", env=None):
    grade, line = ORIG["grade_row"](row, status, log_text, quarantine, published, why, env=env)
    return ("PASS", f"PASS: {row.id}") if status == 0 and grade == "FAIL" else (grade, line)


def _m_git_out(root, *args):
    return subprocess.run(["git", "-C", str(root), *args], capture_output=True, text=True).stdout.strip()


def _m_landing_push_on_the_base(root=None, expect_tip=None, expect_head=None, expect_remote=None):
    # Round 1's destination: the gate's selection base (merge-base with the
    # local origin/main), not origin's main tip as the remote names it.
    root = Path(root or land_gate.REPO_ROOT)
    return land_gate.LandingPush(_m_git_out(root, "merge-base", "origin/main", "HEAD"),
                                 _m_git_out(root, "rev-parse", "HEAD"),
                                 _m_git_out(root, "remote", "get-url", "--push", "origin"))


def _m_landing_push_unchecked(root=None, expect_tip=None, expect_head=None, expect_remote=None):
    # origin's main tip, but no check that HEAD contains it.
    root = Path(root or land_gate.REPO_ROOT)
    url = _m_git_out(root, "remote", "get-url", "--push", "origin")
    tip = _m_git_out(root, "ls-remote", url, "refs/heads/main").split("\t")[0]
    if not tip:
        raise land_gate.LandingUnjudged("mutant: no tip")
    return land_gate.LandingPush(tip, _m_git_out(root, "rev-parse", "HEAD"), url)


def _m_hookless_instrument_host_as_member(g, sel, base, plans, hook, landing=None):
    # Round 1's hookless crates leg: no landing range; each moved instrument's
    # host tested as a member, judged by the zero-test rule only.
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    for l in legs:
        if l.id == "crates-tests" and not hook.active:
            at = l.command.index("--also-members") + 1
            members = sorted(set(filter(None, l.command[at].split(","))) | set(l.hookless_instruments))
            l.command[at] = ",".join(members)
            l.command[l.command.index("--range") + 1] = "HEAD...HEAD"
    return legs


def _m_touched_member_cached(g, sel, base, plans, hook, landing=None):
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    for l in legs:
        if l.id == "crates-tests":
            l.cache_members = sorted(set(l.cache_members) | set(l.hookless_members))
            l.force_run = False
    return legs


def _m_lane_drops_a_reached_hosts_instrument():
    lane = land_gate.crates_lane()
    orig = lane.plan_for

    def plan_for(*a, **kw):
        plan = orig(*a, **kw)
        plan.instrument_runs = [(h, t) for h, t in plan.instrument_runs if h not in plan.packages]
        return plan
    return patched(lane, "plan_for", plan_for)


def _m_push_hook_state_on_the_selection(changed, head="HEAD", root=None, landing=None):
    # Round 2's rule: the hook-path rule judged on the selection (base..head)
    # only, whatever the landing push carries.
    landing = landing or land_gate.read_landing(root, head)
    return ORIG["push_hook_state"](changed, head, root,
                                   dataclasses.replace(landing, changed=() if landing.changed is not None else None))


def _m_push_rows_last(g, sel, base, plans, hook, landing=None):
    legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
    return [l for l in legs if l.id != "push-rows"] + [l for l in legs if l.id == "push-rows"]


def _m_drop_leg(leg_id):
    def build(g, sel, base, plans, hook, landing=None):
        legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
        for l in legs:
            if l.id == leg_id:
                l.selected = False
        return legs
    return build


def _m_xpy_leg_without_stage(leg_id):
    # LAND-GATE-DARWIN-READINESS-1: the leg's request is full again (it readies the whole envelope).
    def build(g, sel, base, plans, hook, landing=None):
        legs = ORIG["build_legs"](g, sel, base, plans, hook, landing)
        for l in legs:
            if l.id == leg_id and "--stage" in l.command:
                at = l.command.index("--stage")
                del l.command[at:at + 2]
        return legs
    return build


def _m_run_row_text(row, root, env, log, stream):
    # Round 3's _run_row: a text-mode (universal-newline) read of the row's
    # output, so `\r\n` and a bare `\r` reach the log as `\n`.
    with open(log, "w", encoding="utf-8", errors="replace", buffering=1) as fh, \
            subprocess.Popen(["bash", "-o", "pipefail", "-c", row.command], cwd=root, env=env,
                             stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                             text=True, errors="replace") as proc:
        for line in proc.stdout:
            fh.write(line)
            if stream:
                sys.stdout.write(line)
        return proc.wait()


def _m_hook_lane_members_unstated(g, member_dirs, landing):
    # Members left to the hook from a push that cannot be stated.
    return ORIG["hook_lane_members"](g, member_dirs, dataclasses.replace(landing, contained=True,
                                                                           tip=landing.tip or "t" * 40))


def _m_hook_lane_members_lane_only(g, member_dirs, landing):
    # The lane's attribution alone (the selector's owner ignored). Round 5:
    # the attribution reads the graph's member sets, so the graph is kept and
    # only its owner replaced by the lane's.
    lane_view = copy.copy(g)
    lane_view.owner = land_gate.lane_attribution(g)
    return ORIG["hook_lane_members"](lane_view, member_dirs, landing)


_R5_CRATES_LANE_SETS = ls.crates_lane_sets


def _m_crates_lane_sets_any_depth(g):
    # Round 4's crates_members: every [workspace] root under crates/, at any depth.
    defaults, roots = _R5_CRATES_LANE_SETS(g)
    return defaults, roots | {d for d in g.workspace_members if d.startswith("crates/") and d in g.packages}


@contextlib.contextmanager
def _m_lane_keeps_unknown_also_members():
    # The lane before round 5: an --also-members dir it cannot attribute is
    # only listed, and the run goes on without it.
    lane = land_gate.crates_lane()
    real = lane.plan_for

    def plan_for(*a, **kw):
        plan = real(*a, **kw)
        plan.unknown_members = []
        return plan
    with patched(lane, "plan_for", plan_for):
        yield


def _m_hook_lane_members_gate_list(g, member_dirs, landing):
    # Round 4's code: "the lane's attribution" as a longest prefix over the
    # gate's member list, not the lane's own function over the lane's sets.
    if not landing.stated or landing.changed is None:
        return set()
    by_prefix = sorted(member_dirs, key=len, reverse=True)
    out = set()
    for p in landing.changed:
        lane_owner = next((d for d in by_prefix if p.startswith(d + "/")), None)
        if lane_owner is not None and g.owner(p) == lane_owner:
            out.add(lane_owner)
    return out


def _m_transaction_needs_targo_row(head):
    # Round 4's rule: exactly one required canonical scoped Targo push row.
    installed = land_gate.hook_installed()
    if not installed.active:
        return installed.why
    rows = [row for row in land_gate.push_profile_rows(land_gate.REPO_ROOT, rev=head)
            if row.id == "scoped.targo-trust-unit-tests"]
    if len(rows) != 1 or rows[0].required != "true" or rows[0].command != (
            "bash scripts/check_targo_trust_unit_tests.sh"):
        return "landing needs exactly one required canonical scoped Targo row"
    return land_gate.landing_targo.protocol_problem(land_gate.REPO_ROOT)


def _m_targo_trust_row_covered():
    cmd = "bash scripts/check_targo_trust_unit_tests.sh"
    return patched_many(
        (land_gate, "HOOK_ROWS_COVERED", {**land_gate.HOOK_ROWS_COVERED,
                                          "scoped.targo-trust-unit-tests": (cmd, "targo-trust")}),
        (land_gate, "COVERED_ROW_PINS", {**land_gate.COVERED_ROW_PINS, "scoped.targo-trust-unit-tests": (
            ("scripts/check_targo_trust_unit_tests.sh", "0756b23a750d05a9ca905983d1c3026e180bbfa2"),)}))


OLD_SCAN_RE = (r'include(_str|_bytes)?!|#\[path|rerun-if-changed|CARGO_MANIFEST_DIR'
               r'|"\.\./|"\.\."|"git"|REPO_ROOT|show-toplevel')

def _m_could_not_run_ignores_mode(leg, broken):
    for build in leg.shared_builds:
        if build in broken:
            return f"{broken[build][0]} failed"
    return None


def _m_listing_is_content():
    real = ls.leg_inputs
    def leg_inputs(g, roots, classes, include_test=True, test_roots=None, _expanding=(), cwd=True, listed=None):
        return real(g, roots, classes, include_test, test_roots, _expanding, cwd, None)
    return patched(ls, "leg_inputs", leg_inputs)


def _m_listing_reaches_nothing():
    # The recursive pseudo-input call hands `listed` positionally; a mutant that
    # took it as a keyword only crashed there, a false kill (review finding 20).
    real = ls.leg_inputs
    def leg_inputs(g, roots, classes, include_test=True, test_roots=None, _expanding=(), cwd=True, listed=None):
        return real(g, roots, classes, include_test, test_roots, _expanding, cwd,
                    set() if listed is not None else None)
    return patched(ls, "leg_inputs", leg_inputs)


def _m_landing_reuses_statuses(g, sel, landing):
    if landing is None or landing.changed is None:
        return None
    if sorted(landing.changed) == sorted(sel.changed):
        return sel
    return ls.select(g, landing.tip, list(landing.changed))


def _m_not_path_outlives_an_edit():
    real = ls._harvest_package_literals
    def harvest(g, pkg, top, audits, not_paths=None):
        fresh = {p: dict(r, blob=g.index.entries[p][1], premises=[]) if p in g.index.entries else r
                 for p, r in (not_paths or {}).items()}
        return real(g, pkg, top, audits, fresh)
    return patched(ls, "_harvest_package_literals", harvest)


def _m_lenient_not_paths(g):
    rows = ls._audit_doc(g).get("not_path", [])
    out = {}
    for row in rows if isinstance(rows, list) else []:
        if isinstance(row, dict) and isinstance(row.get("file"), str):
            literals = row.get("literals") if isinstance(row.get("literals"), list) else [row.get("literals")]
            premises = row.get("premises") if isinstance(row.get("premises"), list) else []
            out[row["file"]] = dict(row, literals=[str(v) for v in literals],
                                    via=row["via"] if isinstance(row.get("via"), list) else [],
                                    premises=[p for p in premises if isinstance(p, dict) and "blob" in p])
    return out


def _m_aliases_one_hop():
    def link_aliases(g, path):
        targets = ls.link_targets(g)
        return {link if path == t else link + path[len(t):] for link, t in targets
                if t is not None and t != "" and (path == t or path.startswith(t + "/"))}
    return patched(ls, "link_aliases", link_aliases)


def _legacy_stops_a_token_at_a_time(code, starts):
    """rust_lex._legacy_stops as the walk before round 4 of review 4 found
    each stop: a token at a time from each start (a mutant's)."""
    out = {}
    for j in starts:
        depth, out[j] = 0, None
        for t in re.finditer(r"[()\[\]{};]", code[j:]):
            ch = t.group(0)
            if ch in "([":
                depth += 1
            elif ch in ")]":
                depth -= 1
            elif depth <= 0 and ch != "}":
                out[j] = j + t.start()
                break
    return out


def _m_source(module, name, old, new, *more):
    """`module.name` recompiled from its source with `old` replaced by `new`
    (and each further (old, new) pair of `more`), its globals the module's own."""
    src = textwrap.dedent(inspect.getsource(getattr(module, name)))
    for o, n in ((old, new), *more):
        assert src.count(o) == 1, (name, o)
        src = src.replace(o, n)
    local: dict = {}
    exec(compile(src, module.__file__, "exec"), module.__dict__, local)
    return patched(module, name, local[name])


def _m_method_source(module, cls, name, old, new):
    """`cls.name` recompiled from its source with `old` replaced by `new`, its
    globals `module`'s own (a class namespace is no globals dict)."""
    src = textwrap.dedent(inspect.getsource(getattr(cls, name)))
    assert src.count(old) == 1, (name, old)
    local: dict = {}
    exec(compile(src.replace(old, new), module.__file__, "exec"), module.__dict__, local)
    return patched(cls, name, local[name])


def _m_checkout_head_only(root=None):
    """The reused-boundary guard as it was until review round 3: the
    superproject's HEAD only, blind to the index and to every submodule."""
    done = subprocess.run(["git", "-C", str(root or land_gate.REPO_ROOT), "rev-parse", "--verify", "HEAD^{commit}"],
                          capture_output=True, text=True)
    return done.stdout.strip() or None if done.returncode == 0 else None


@contextlib.contextmanager
def _m_together(*factories):
    """Every mutation `factories` make, at once (each a thunk returning one)."""
    with contextlib.ExitStack() as stack:
        for factory in factories:
            stack.enter_context(factory())
        yield


def _m_fence_at_any_indent():
    """A ``` line indented four columns or more opens a fence (as one indented
    less), as the doctest reader read it until review 4."""
    return _m_source(ls, "_md_start", "    if indent == 4:\n        st.llb = False\n",
                     "    if indent == 4 and _md_fence(line[ls.ix:]):\n        indent = 0\n"
                     "    if indent == 4:\n        st.llb = False\n")


def _m_method(cls, name, old, new):
    """`cls.name` recompiled from its source with `old` replaced by `new`, its
    globals its module's (_m_source for a method)."""
    src = textwrap.dedent(inspect.getsource(getattr(cls, name)))
    assert src.count(old) == 1, (name, old)
    local: dict = {}
    module = sys.modules[cls.__module__]
    exec(compile(src.replace(old, new), module.__file__, "exec"), module.__dict__, local)
    return patched(cls, name, local[name])


def _m_unresolvable_link_lexical():
    real = ls._index_realpath
    def index_realpath(texts, d, rel, spellings=None):
        r = real(texts, d, rel, spellings)
        return r if r is not None else ls._norm(d, rel)
    return patched(ls, "_index_realpath", index_realpath)


def _m_suite_links_lexical():
    def symlink_escapes(g, root, symlinks=None):
        if symlinks is None:
            links = [p for p, (mode, _) in g.index.entries.items()
                     if mode == "120000" and (p == root or p.startswith(root + "/"))]
            symlinks = g.index.read_blobs(links)
        out = set()
        for p, blob in symlinks.items():
            target = ls._norm(posixpath.dirname(p), blob.decode("utf-8", "surrogateescape"))
            if target is None:
                out.add(ls.EVERYTHING)
            elif not (target == root or target.startswith(root + "/")):
                out.add(target if target else ls.EVERYTHING)
        return out
    return patched(ls, "_symlink_escapes", symlink_escapes)


def _m_alias_limit_reads_nothing():
    real = ls._read_through_a_link
    def read_through_a_link(g, path, inputs, folded=None):
        return ls.link_aliases(g, path) is not None and real(g, path, inputs, folded)
    return patched(ls, "_read_through_a_link", read_through_a_link)


def _m_path_call_brackets_only():
    def in_path_call(code, s, e):
        inner, parent = ls._bracket_tree(code, [s])
        opened = inner[s]
        while opened >= 0:
            if code[opened] == "(" and ls.PATH_API.search(ls._callee_before(code, opened) or ""):
                return True
            opened = parent.get(opened, -1)
        return False
    return patched(ls, "_in_path_call", in_path_call)


def _m_chain_stops_at_escape():
    real = ls._string_chains
    def chains(lx, text):
        out = []
        for s, e, values in real(lx, text):
            if "\\" in text[s:e]:
                break
            out.append((s, e, values))
        return out
    return patched(ls, "_string_chains", chains)



def _m_relative_refs_quoted(g, root):
    """_relative_refs reading `git grep -n -o` lines, as before -z: a path git
    quotes resolves from its quote."""
    found = ls._git_grep(g, ["-n", "-o", "-E", "(\\.\\./)+[^] \"'),;>`]*"], [root])
    if found is None:
        return None
    out, prefix = set(), g.index.rev + ":"
    for raw in found.decode("utf-8", "replace").splitlines():
        rest = raw[len(prefix):] if raw.startswith(prefix) else raw
        path, _, rest = rest.partition(":")
        _lineno, _, ref = rest.partition(":")
        target = ls._norm(posixpath.dirname(path), ref)
        if target is None:
            out.add(ls.EVERYTHING)
            continue
        target, _ = ls._cut_glob(target)
        if target and not (target == root or target.startswith(root + "/")):
            out.add(target)
    return out


_M_GIT_GREP = ls._git_grep


def _m_git_grep_without_z(g, args, pathspecs):
    """_git_grep with no -z: git quotes a non-ASCII path (see _m_grep_listed_lines)."""
    return _M_GIT_GREP(g, [a for a in args if a != "-z"], pathspecs)


def _m_grep_listed_lines(g, out):
    prefix = g.index.rev + ":"
    return [raw[len(prefix):] if raw.startswith(prefix) else raw for raw in out.decode("utf-8", "replace").splitlines()]


def _m_bare_binding_aliases(code, api, local):
    """_binding_aliases as ALIAS_BINDING read it before LAND-GATE-EW1-FOLLOWUP-REVIEW-3's
    scan repairs: only `let`, `const` or `static` NAME = a bare path;."""
    bare = re.compile(r'\b(?:%s)\s+(?:mut\s+)?(?:r#)?([A-Za-z_]\w*)\s*(?::[^=;]*)?=' % (
        "let|const|static" if local else "const|static") + r'(\s*&?\s*(?:[A-Za-z_]\w*\s*::\s*)*[A-Za-z_]\w*\s*);')
    return {m.group(1) for m in bare.finditer(code) if api(m.group(2))}, False


# LAND-GATE-PUSHROWS-SPEED-1 (CheckoutWorkerTests, LandingPushCheckoutTests):
# each reopens what a checkout worker runs or reads, what it answers, when the
# pool starts, or the early remote read.
def _m_worker_from_disk(requests_fd, answers_fd, key):
    land_gate._checkout_worker_descriptors(requests_fd, answers_fd)
    sys.path.insert(0, str(REPO / "scripts" / "lib"))
    sys.modules.pop("checkout_inputs", None)
    import checkout_inputs
    with open(requests_fd, "rb") as requests, open(answers_fd, "wb") as answers:
        checkout_inputs.serve(requests, answers, key)


# The per-file check without the ascii codec's preload (it then loads on the
# first attribute query, after `ready`), and without the guard that stops a
# worker whose batch loaded a module.
_M_LAZY_CODEC_SOURCE = land_gate._CHECKOUT_INPUTS_SOURCE.replace(b"import encodings.ascii  # noqa: F401\n", b"")
# A worker that lets a module be imported after `ready` (the check after the
# batch then sees only a body that already ran), and one that also answers
# such a batch; and the per-file check without the locale codec's preload.
_M_IMPORTING_SOURCE = land_gate._CHECKOUT_INPUTS_SOURCE.replace(b"    sys.meta_path.insert(0, refused)\n", b"")
_M_UNGUARDED_SOURCE = _M_IMPORTING_SOURCE.replace(
    b"        if refused.attempted or not loaded.issuperset(sys.modules):\n            return\n", b"")
_M_LAZY_LOCALE_SOURCE = land_gate._CHECKOUT_INPUTS_SOURCE.replace(
    b"    codecs.getincrementaldecoder(encoding)(errors=\"surrogateescape\").decode(b\"x\", final=True)\n"
    b"    \"x\".encode(encoding, \"surrogateescape\").decode(encoding, \"surrogateescape\")\n", b"")
assert len({land_gate._CHECKOUT_INPUTS_SOURCE, _M_LAZY_CODEC_SOURCE, _M_IMPORTING_SOURCE, _M_UNGUARDED_SOURCE,
            _M_LAZY_LOCALE_SOURCE}) == 5


def _m_worker_descriptors_standard(requests_fd, answers_fd):
    # Before the third review: the request and answer pipes are the worker's
    # standard input and output, which the `git` it runs inherits.
    for sig in land_gate._CANCEL_SIGNALS:
        signal.signal(sig, signal.SIG_IGN)
    os.dup2(requests_fd, 0)
    os.dup2(answers_fd, 1)
    for name in os.listdir("/dev/fd"):
        if name.isdigit() and int(name) not in {0, 1, 2, requests_fd, answers_fd}:
            try:
                os.close(int(name))
            except OSError:
                pass


# Before the fourth review: a worker is a fresh interpreter, the program
# sys.executable names (on macOS, whatever PYTHONEXECUTABLE says), handed the
# source and the key on its input.
_M_EXEC_WORKER_BOOT = (
    "import os, sys, types\n"
    "requests, answers = open(os.dup(0), 'rb'), open(os.dup(1), 'wb')\n"
    "null = os.open(os.devnull, os.O_RDWR)\n"
    "os.dup2(null, 0)\n"
    "os.dup2(null, 1)\n"
    "key = requests.read(32)\n"
    "source = requests.read(int(requests.readline()))\n"
    "module = types.ModuleType('checkout_inputs')\n"
    "exec(compile(source, 'checkout_inputs.py', 'exec'), module.__dict__)\n"
    "module.serve(requests, answers, key)\n")


def _m_start_exec(self):
    if not self._key:
        self._key = os.urandom(32)
    while len(self._procs) < self.jobs:
        proc = subprocess.Popen([sys.executable, "-I", "-S", "-B", "-c", _M_EXEC_WORKER_BOOT],
                                stdin=subprocess.PIPE, stdout=subprocess.PIPE, cwd="/")
        self._procs.append(proc)
        source = land_gate._CHECKOUT_INPUTS_SOURCE
        proc.stdin.write(self._key + b"%d\n" % len(source) + source)
        proc.stdin.flush()
    for proc in self._procs[self._ready:]:
        if proc.stdout.readline() != b"ready\n":
            raise RuntimeError("a checkout worker did not start")
        self._ready += 1


_ORIG_CHECKOUT_RUN = land_gate._CheckoutWorkers.run


def _m_run_starting_workers(self, *args):
    # Before the third review: the first pass that needs workers starts them.
    if self.jobs > 1 and not self._procs:
        self._start()
    return _ORIG_CHECKOUT_RUN(self, *args)


def _m_start_despite_advertised(self):
    if self.jobs <= 1:
        return
    try:
        self._start()
    except (OSError, RuntimeError, ValueError) as exc:
        self.decline(str(exc))


def _m_checkout_answer_nonce_only(reply, nonce, request, key):
    if not isinstance(reply, tuple) or len(reply) != 4 or reply[0] != nonce:
        raise ValueError("an answer to another request")
    return land_gate.marshal.loads(reply[2])


def _m_checkout_answer_unauthenticated(reply, nonce, request, key):
    if (not isinstance(reply, tuple) or len(reply) != 4 or reply[0] != nonce
            or reply[1] != hashlib.sha256(request).digest()):
        raise ValueError("an answer to another request")
    return land_gate.marshal.loads(reply[2])


def _m_landing_push_tip_after_pass(root=None, expect_tip=None, expect_head=None, expect_remote=None):
    # The order before 2026-11-09: the complete checkout pass, then the remote.
    root = Path(root or land_gate.REPO_ROOT)
    head = _m_git_out(root, "rev-parse", "HEAD")
    if expect_head is not None and head != expect_head:
        raise land_gate.LandingUnjudged(f"HEAD changed from planned {expect_head[:12]} to {head[:12]}")
    tally = land_gate.CheckoutTally()
    problem = land_gate.checkout_problem(head, root, tally=tally)
    if problem:
        raise land_gate.LandingUnjudged(problem)
    remote, tip = land_gate._landing_destination(root, land_gate.git_query_env(), head, expect_tip, expect_remote)
    return land_gate.LandingPush(tip, head, remote, tally)


def _m_validation_programs_only(changed):
    # validation_test_modules before LAND-SELECT-VALIDATION-REACH-1: only the
    # declared validation programs (and the Cargo feature graph) select tests.
    modules = {module for path in changed for module in ls.VALIDATION_PROGRAM_TESTS.get(path, ())}
    if any(ls.fold(path).rsplit("/", 1)[-1] == "cargo.toml" for path in changed):
        modules.add("scripts.tests.mir_test_oracle_feature_test")
    return sorted(modules)


