def _patch_legs_partial(new):
    # LEGS holds a reference to _ui_partial; patch the LegSpec too.
    return contextlib.ExitStack()


# The seed of gate run 20261027T175434: it cannot build the stage-1 compiler
# (here the fixture's rustc_a, in compiler/rustc's closure).
SEED_E0658 = (
    "Building stage1 compiler artifacts (stage0 -> stage1, aarch64-apple-darwin)\n"
    "   Compiling rustc_a v0.0.0 (/repo/compiler/rustc_a)\n"
    "error[E0658]: use of unstable library feature `new_feature`\n"
    " --> compiler/rustc_a/src/lib.rs:3:5\n"
    "\n"
    "error: could not compile `rustc_a` (lib) due to 1 previous error\n")


class FailFastTests(unittest.TestCase):
    """EW-19: the cheap legs run first, and a deterministic compile error in a
    build other legs need too ends those legs as COULD NOT RUN, without
    running them and never as PASS."""

    def test_land_qualifies_captured_source_before_a_moved_publication_refuses(self):
        with tempfile.TemporaryDirectory(prefix="land-snapshot-check.") as tmp, \
                contextlib.ExitStack() as stack:
            root = Path(tmp)
            graph = Fixture.graph()
            selection = ls.select(graph, "base", ["weird/unknown.txt"])
            captured = stated(selection.changed, head=selection.head)
            captured = land_gate.LandingRange(
                captured.tip, captured.head, "fixture-remote", True, captured.changed)
            moved = land_gate.LandingRange(
                "new-main", captured.head, captured.remote, False, None, "main advanced")
            checks = [leg(id="push-rows"), leg(id="snapshot-check")]
            marker = root / "qualified-source"

            def run_leg(selected, *_args, **_kwargs):
                log = root / f"{selected.id}.log"
                if selected.id == "snapshot-check":
                    marker.write_text(selection.head)
                    log.write_text("source checked\n")
                    return 0, 0.01, str(log), False
                self.assertEqual(marker.read_text(), selection.head)
                log.write_text("publication destination advanced\n")
                return 2, 0.01, str(log), False

            for name, value in (
                    ("git", lambda *_a, **_k: ""),
                    ("checkout_problem", lambda *_a, **_k: None),
                    ("discover_landing", lambda *_a, **_k: (graph, selection, "base", captured)),
                    ("read_landing", lambda *_a, **_k: moved),
                    ("build_legs", lambda *_a, **_k: checks),
                    ("push_hook_state", lambda *_a, **_k: HOOK_ON),
                    ("toolchain_identity", lambda: {}), ("config_identity", lambda: {}),
                    ("rustc_identity", lambda *_a, **_k: None),
                    ("global_fingerprint", lambda *_a: "fixture"),
                    ("stage1_key", lambda *_a, **_k: "fixture-stage1"),
                    ("xpy_unready", lambda: None), ("targo_unready", lambda _leg: None),
                    ("common_dir", lambda: root), ("run_leg", run_leg)):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(land_gate, "REPO_ROOT", Path(graph.index.repo)))
            stack.enter_context(mock.patch.object(
                land_gate.remote_tips, "github_repository", return_value="fixture/repo"))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            publish = stack.enter_context(mock.patch.object(land_gate, "publish_native_source"))
            preflight = stack.enter_context(mock.patch.object(
                land_gate, "landing_preflight", side_effect=AssertionError("publication before qualification")))
            args = SimpleNamespace(base="base", land=True, only=None, no_cache=True, dry_run=False)
            with contextlib.redirect_stdout(io.StringIO()), \
                    self.assertRaises(land_gate.LandingRefreshRequired) as refreshed:
                land_gate.cmd_run(args)
            record = json.loads(next(root.glob("trust-land/runs/*/record.json")).read_text())
            self.assertEqual(marker.read_text(), selection.head)
            self.assertEqual(record["legs"]["snapshot-check"]["outcome"], "PASS")
            self.assertEqual(record["legs"]["push-rows"]["outcome"], "NOT JUDGED")
            self.assertEqual(refreshed.exception.landing.tip, moved.tip)
            publish.assert_not_called()
            preflight.assert_not_called()

    def test_unavailable_ir_stops_publication_work_but_preserves_diagnostic_runs(self):
        for publishing, ir_exit, follow_on_runs in (
                (True, 2, False), (False, 2, True), (True, 1, True), (False, 0, True)):
            with self.subTest(publishing=publishing, ir_exit=ir_exit), \
                    tempfile.TemporaryDirectory(prefix="land-unavailable-ir.") as tmp, \
                    contextlib.ExitStack() as stack:
                root = Path(tmp)
                graph = Fixture.graph()
                selection = ls.select(graph, "base", ["weird/unknown.txt"])
                landing = stated(selection.changed, head=selection.head)
                legs = [leg(id="ir-cohort"), leg(id="compiler-check")]
                marker = root / "compiler-started"

                def run_leg(selected, *_args, **_kwargs):
                    log = root / f"{selected.id}.log"
                    if selected.id == "ir-cohort":
                        log.write_text("remote containment unavailable\n" if ir_exit == 2 else "IR verdict\n")
                        return ir_exit, 0.01, str(log), False
                    marker.write_text("compiler work started\n")
                    log.write_text("compiler passed\n")
                    return 0, 0.01, str(log), False

                for name, value in (
                        ("git", lambda *_a, **_k: ""),
                        ("checkout_problem", lambda *_a, **_k: None),
                        ("discover_landing", lambda *_a, **_k: (graph, selection, "base", landing)),
                        ("read_landing", lambda *_a, **_k: landing),
                        ("landing_preflight", lambda *_a, **_k: land_gate.LandingPush("base", selection.head)),
                        ("build_legs", lambda *_a, **_k: legs),
                        ("push_hook_state", lambda *_a, **_k: HOOK_ON),
                        ("toolchain_identity", lambda: {}), ("config_identity", lambda: {}),
                        ("rustc_identity", lambda *_a, **_k: None),
                        ("global_fingerprint", lambda *_a: "fixture"),
                        ("stage1_key", lambda *_a, **_k: "fixture-stage1"),
                        ("xpy_unready", lambda: None), ("targo_unready", lambda _leg: None),
                        ("common_dir", lambda: root), ("run_leg", run_leg)):
                    stack.enter_context(mock.patch.object(land_gate, name, value))
                stack.enter_context(mock.patch.object(land_gate, "REPO_ROOT", Path(graph.index.repo)))
                stack.enter_context(mock.patch.object(land_gate.remote_tips, "github_repository", return_value="fixture/repo"))
                stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
                publish = stack.enter_context(mock.patch.object(land_gate, "publish_native_source"))
                args = SimpleNamespace(base="base", land=publishing, only=None, no_cache=True, dry_run=False)
                with contextlib.redirect_stdout(io.StringIO()):
                    result = land_gate.cmd_run(args)
                record = json.loads(next(root.glob("trust-land/runs/*/record.json")).read_text())
                self.assertEqual(marker.exists(), follow_on_runs)
                self.assertEqual(result, 2 if ir_exit == 2 else ir_exit)
                self.assertEqual(record["legs"]["ir-cohort"]["rc"], ir_exit)
                follow_on = record["legs"]["compiler-check"]
                if follow_on_runs:
                    self.assertEqual(follow_on["outcome"], "PASS")
                else:
                    self.assertIn("NOT RUN", follow_on["outcome"])
                    self.assertNotIn("rc", follow_on)
                    self.assertNotIn("ordinary_push", record)
                publish.assert_not_called()

    def legs(self, path="weird/unknown.txt"):
        g = Fixture.graph()
        sel = ls.select(g, "base", [path])
        with contextlib.redirect_stdout(io.StringIO()):
            return g, sel, land_gate.build_legs(g, sel, "base", land_gate.budget_plans(host(20, 128, 100)), HOOK_ON,
                                                stated(sel.changed))

    def test_the_cheap_legs_run_right_after_push_rows(self):
        _g, _sel, legs = self.legs()
        ids = [l.id for l in legs]
        self.assertEqual(ids[:5], ["push-rows", "tidy", "tcb-panic-ratchet", "ir-cohort", "validation-tests"])
        self.assertEqual(sorted(ids), sorted(set(ids)), "no leg lost or doubled")
        for heavy in ("compiler-check", "ui-trust", "run-make-trust", "compiler-unit-tests", "crates-tests",
                      "targo-trust", "native-targo-tests", "bootstrap-tests", "olean-audit"):
            self.assertGreater(ids.index(heavy), ids.index("validation-tests"), heavy)

    def test_shared_builds_are_named_per_leg(self):
        _g, _sel, legs = self.legs()
        by = {l.id: l.shared_builds for l in legs}
        self.assertEqual(by["compiler-check"], {"seed-compiler": "check"})
        for leg_id in ("ui-trust", "run-make-trust", "native-targo-tests"):
            self.assertEqual(by[leg_id], {"seed-compiler": "build", "stage1-library": "build",
                                          "stage1-sysroot": "build"}, leg_id)
        self.assertEqual(by["compiler-unit-tests"], {"seed-compiler": "uses", "stage1-library": "uses"})
        for leg_id in ("push-rows", "tidy", "tcb-panic-ratchet", "ir-cohort", "validation-tests", "crates-tests",
                       "targo-trust", "olean-audit", "bootstrap-tests"):
            self.assertEqual(by[leg_id], {}, leg_id)

    def test_only_a_deterministic_compile_error_in_a_shared_build_breaks_it(self):
        _g, _sel, legs = self.legs()
        by = {l.id: l for l in legs}
        check = by["compiler-check"]
        [(build, mode, why)] = land_gate.shared_build_failures(SEED_E0658, check)
        self.assertEqual((build, mode), ("seed-compiler", "check"))
        self.assertIn("error[E0658]: use of unstable library feature", why)
        self.assertIn("`rustc_a` (lib)", why)
        self.assertEqual(land_gate.shared_build_failures(SEED_E0658.replace("could not compile", "could not check"),
                                                         check)[0][0], "seed-compiler")
        for name, text in (
                ("a test target is the leg's own", SEED_E0658.replace("(lib)", "(lib test)")),
                ("a killed compiler is no deterministic failure",
                 SEED_E0658.replace(" due to 1 previous error", "\n\nCaused by:\n  process didn't exit "
                                    "successfully: rustc (signal: 9, SIGKILL: kill)")),
                ("no section header: no build named", SEED_E0658.split("\n", 1)[1]),
                ("a passing log", "   Compiling rustc_a v0.0.0\n    Finished\n")):
            with self.subTest(name):
                self.assertEqual(land_gate.shared_build_failures(text, check), [])
        # A leg that builds the compiler among other things it cannot tell
        # apart (a stage-2 run) names no broken build.
        self.assertEqual(land_gate.shared_build_failures(SEED_E0658, by["compiler-unit-tests"]), [])
        # The prepare step's sysroot breaks on any compile error, only when the
        # prepare step is what failed.
        tool = SEED_E0658.replace("compiler artifacts", "tool targo-trust").replace("`rustc_a`", "`some-battery`")
        ui = by["ui-trust"]
        self.assertEqual(land_gate.shared_build_failures(tool, ui), [])
        self.assertEqual([b for b, _m, _w in land_gate.shared_build_failures(tool, ui, prepare_failed=True)],
                         ["stage1-sysroot"])
        self.assertEqual(sorted(b for b, _m, _w in land_gate.shared_build_failures(SEED_E0658, ui, True)),
                         ["seed-compiler", "stage1-sysroot"])

    def test_a_failure_is_attributed_by_the_bootstrap_section_that_compiled_it(self):
        # Review of EW-19: by crate name the seed's set was only rustc-main on
        # the real tree (rustc_ast is also a path dependency of Trust tools),
        # so the brief's own case, a seed that cannot build rustc_ast, was
        # missed. Bootstrap's section header names the build.
        _g, _sel, legs = self.legs()
        by = {l.id: l for l in legs}
        ast = SEED_E0658.replace("`rustc_a`", "`rustc_ast`").replace("compiler artifacts",
                                                                     "compiler artifacts {rustc_ast}")
        for leg_id, mode in (("compiler-check", "check"), ("ui-trust", "build")):
            with self.subTest(leg=leg_id):
                self.assertIn(("seed-compiler", mode),
                              [(b, m) for b, m, _w in land_gate.shared_build_failures(ast, by[leg_id])])
        checking = ast.replace("Building stage1", "Checking stage1")
        self.assertEqual(land_gate.shared_build_failures(checking, by["compiler-check"])[0][0], "seed-compiler")
        ui = by["ui-trust"]
        for name, header in (
                ("the same crate compiled for a tool", "Building stage1 tool targo-trust (stage0 -> stage1, "
                                                       "aarch64-apple-darwin)"),
                ("the stage-1 compiler compiling stage 2", "Building stage2 compiler artifacts (stage1 -> stage2, "
                                                            "aarch64-apple-darwin)")):
            with self.subTest(name):
                text = header + "\n" + ast.split("\n", 1)[1]
                self.assertEqual(land_gate.shared_build_failures(text, ui), [])
        std = ("Building stage1 library artifacts (stage1 -> stage1, aarch64-apple-darwin)\n"
               "error[E0425]: cannot find value `x` in this scope\n"
               "error: could not compile `std` (lib) due to 1 previous error\n")
        self.assertEqual([b for b, _m, _w in land_gate.shared_build_failures(std, ui)], ["stage1-library"])
        self.assertEqual(land_gate.shared_build_failures(std, by["compiler-check"]), [])
        # A later section ends the seed's: an error after it is not the seed's.
        later = SEED_E0658.split("error[")[0] + "Building stage1 tool targo-trust (stage0 -> stage1, x)\n" + \
            "error[" + SEED_E0658.split("error[", 1)[1]
        self.assertEqual(land_gate.shared_build_failures(later, ui), [])

    def test_a_link_or_io_failure_is_no_deterministic_evidence(self):
        # Review of EW-19: rustc reports a failed link as an error, so Cargo
        # prints `due to 1 previous error` for a killed linker or a full disk.
        _g, _sel, legs = self.legs()
        ui = {l.id: l for l in legs}["ui-trust"]
        head = "Building stage1 compiler artifacts (stage0 -> stage1, aarch64-apple-darwin)\n"
        tail = "error: could not compile `rustc-main` (bin \"rustc-main\") due to 1 previous error\n"
        for name, error in (("linker", "error: linking with `cc` failed: exit status: 1"),
                            ("disk", "error: failed to write rlib: No space left on device (os error 28)"),
                            ("killed linker", "error: linker `cc` was killed (signal 9)")):
            with self.subTest(name):
                self.assertEqual(land_gate.shared_build_failures(head + error + "\n" + tail, ui), [])
        both = head + "error: linking with `cc` failed\nerror[E0425]: cannot find value `x`\n" + tail
        [(build, _m, why)] = land_gate.shared_build_failures(both, ui)
        self.assertEqual(build, "seed-compiler")
        self.assertIn("E0425", why)

    def test_who_a_broken_build_stops(self):
        _g, _sel, legs = self.legs()
        by = {l.id: l for l in legs}
        checked = {"seed-compiler": ("compiler-check", "check", "why")}
        built = {"seed-compiler": ("ui-trust", "build", "why")}
        for leg_id in ("ui-trust", "run-make-trust", "native-targo-tests", "compiler-unit-tests"):
            self.assertIn("compiler-check failed building the stage-1 compiler",
                          land_gate.could_not_run(by[leg_id], checked) or "", leg_id)
        self.assertIsNotNone(land_gate.could_not_run(by["compiler-unit-tests"], built))
        # A build error (codegen, post-monomorphisation) need not be a check error.
        self.assertIsNone(land_gate.could_not_run(by["compiler-check"], built))
        for leg_id in ("tidy", "crates-tests", "targo-trust", "bootstrap-tests", "olean-audit"):
            self.assertIsNone(land_gate.could_not_run(by[leg_id], checked), leg_id)

    # TRUST_RUSTC-1 x EW-19: a crates leg that prepares this tree's stage 1
    # for its Trust-rustc members builds the three shared builds in that
    # prepare step, and only there.
    def stage1_crates_legs(self):
        with mock.patch.object(land_gate, "TRUST_RUSTC_RESOLVER", "crates/leaf"):
            g, _sel, legs = self.legs("crates/leaf/src/lib.rs")
        by = {l.id: l for l in legs}
        self.assertEqual(by["crates-tests"].prepare[:5], land_gate.stage1_prepare(1)[:5])
        return g, by

    def test_a_crates_leg_that_prepares_stage1_takes_part_through_its_prepare(self):
        _g, by = self.stage1_crates_legs()
        crates_leg = by["crates-tests"]
        self.assertEqual(crates_leg.shared_builds, {b: "prepare" for b in land_gate.SHARED_BUILDS})
        # Its Cargo run's compile error is the workspace's, never the compiler's build.
        self.assertEqual(land_gate.shared_build_failures(SEED_E0658, crates_leg), [])
        self.assertEqual(sorted(b for b, _m, _w in land_gate.shared_build_failures(SEED_E0658, crates_leg,
                                                                                    prepare_failed=True)),
                         ["seed-compiler", "stage1-sysroot"])
        built = {"seed-compiler": ("ui-trust", "build", "why")}
        checked = {"seed-compiler": ("compiler-check", "check", "why")}
        for broken in (built, checked):
            self.assertIn("failed building the stage-1 compiler",
                          land_gate.could_not_run(crates_leg, broken) or "", broken)
        # A prepare step that is not the stage-1 sysroot's shares nothing.
        crates_leg.prepare = ["true"]
        self.assertEqual(land_gate.shared_builds_of(crates_leg), {})

    def test_a_crates_leg_without_stage1_members_takes_no_part(self):
        _g, by = self.stage1_crates_legs()
        self.assertNotEqual(by["crates-tests"].shared_builds, {}, "the control: the resolver reached")
        _g, _sel, legs = self.legs("crates/leaf/src/lib.rs")
        plain = {l.id: l for l in legs}["crates-tests"]
        self.assertEqual((plain.prepare, plain.stage1_members, plain.shared_builds), (None, [], {}))

    def run_gate(self, logs, only=None, prepare_fails=(), cached=False):
        """cmd_run over the fixture with every leg selected; `logs` is
        {leg id: (exit, log text)} (default: exit 0, a passing log); the legs
        in `prepare_fails` fail in their prepare step; `cached`: every key
        has a stored PASS."""
        g, sel, _legs = self.legs()
        args = land_gate.argparse.Namespace(base="base", only=only, no_cache=not cached, dry_run=False)
        ran = []
        with tempfile.TemporaryDirectory(prefix="land-gate-fail-fast.") as tmp, contextlib.ExitStack() as stack:
            def run_leg(leg, *a, **kw):
                ran.append(leg.id)
                rc, text = logs.get(leg.id, (0, f"{leg.id}: passed\n"))
                log = Path(tmp) / f"{leg.id}.log"
                log.write_text(text, encoding="utf-8")
                return rc, 1.0, str(log), leg.id in prepare_fails
            if cached:
                # Every leg but compiler-check (which must run to fail) has a
                # stored PASS: keys are tagged with their leg.
                real_key_parts = land_gate.key_parts
                stack.enter_context(mock.patch.object(
                    land_gate, "key_parts", lambda leg, *a, **kw: types.SimpleNamespace(
                        key=lambda: f"{leg.id}|{real_key_parts(leg, *a, **kw).key()}")))
                stack.enter_context(mock.patch.object(
                    land_gate, "cache_lookup", lambda key, sysroot=None:
                    None if key.startswith("compiler-check|") else {"run": "earlier"}))
            for name, value in (("git", lambda *a, **kw: ""), ("checkout_problem", lambda *a, **kw: None),
                                ("compute", lambda *a, **kw: (g, sel, "base")),
                                ("toolchain_identity", lambda: {}), ("common_dir", lambda: Path(tmp)),
                                ("rustc_identity", lambda stage1=None: None), ("config_identity", lambda: {}),
                                ("push_hook_state", lambda *a, **kw: HOOK_ON), ("stage1_key", lambda *a, **kw: "s1"),
                                ("targo_unready", lambda leg: None),  # a faked leg runs no targo (round 5, D3)
                                ("xpy_unready", lambda: None), ("run_leg", run_leg),
                                ("read_landing", lambda *a, **kw: stated(sel.changed))):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(land_gate, "REPO_ROOT", Path(g.index.repo)))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            stack.enter_context(mock.patch.object(land_gate, "cache_store"))
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                rc = land_gate.cmd_run(args)
            [record] = list((Path(tmp) / "trust-land" / "runs").glob("*/record.json"))
            return rc, ran, json.loads(record.read_text(encoding="utf-8")), out.getvalue()

    def test_a_forced_seed_failure_ends_the_legs_that_need_it_as_could_not_run(self):
        rc, ran, record, out = self.run_gate({"compiler-check": (1, SEED_E0658)})
        legs = record["legs"]
        self.assertEqual(rc, 1, out)
        self.assertIn("LAND-GATE: RED", out)
        # push-rows and validation-tests are not selected by this change (a
        # hook answers; no validation program changed): the cheap legs lead.
        self.assertEqual([k for k in legs if legs[k]["selected"]][:3], ["tidy", "tcb-panic-ratchet", "ir-cohort"])
        self.assertEqual(ran[:4], ["tidy", "tcb-panic-ratchet", "ir-cohort", "compiler-check"],
                         "the cheap legs run first, before the build that fails")
        self.assertEqual(legs["compiler-check"]["outcome"], "FAIL")
        self.assertEqual(legs["compiler-check"]["shared_build_failed"][0]["build"], "seed-compiler")
        stopped = ("ui-trust", "run-make-trust", "compiler-unit-tests", "native-targo-tests")
        for leg_id in stopped:
            with self.subTest(leg=leg_id):
                self.assertTrue(legs[leg_id]["selected"], "the change selects every leg")
                self.assertNotIn(leg_id, ran, "a leg that needs the broken build never runs")
                outcome = legs[leg_id]["outcome"]
                self.assertTrue(outcome.startswith("COULD NOT RUN ("), outcome)
                self.assertIn("compiler-check failed building the stage-1 compiler", outcome)
                self.assertIn("error[E0658]", outcome)
                self.assertIn(f"COULD NOT RUN {leg_id}: compiler-check failed", out)
        for leg_id in ("crates-tests", "targo-trust", "bootstrap-tests", "olean-audit"):
            self.assertIn(leg_id, ran, "a leg that does not need the build still runs")
        self.assertFalse(any("PASS" in v.get("outcome", "") for k, v in legs.items() if k in stopped))

    def test_a_cached_pass_never_answers_for_a_leg_whose_build_is_broken(self):
        # Every other leg has a stored PASS; the legs that need compiler-check's
        # broken build are COULD NOT RUN, never CACHED PASS.
        rc, ran, record, out = self.run_gate({"compiler-check": (1, SEED_E0658)}, cached=True)
        legs = record["legs"]
        self.assertIn("compiler-check", ran)
        for leg_id in ("ui-trust", "run-make-trust", "compiler-unit-tests", "native-targo-tests"):
            self.assertTrue(legs[leg_id]["outcome"].startswith("COULD NOT RUN ("), legs[leg_id]["outcome"])
        self.assertIn("CACHED PASS", {v.get("outcome") for v in legs.values()}, "the cache lookup was live")
        self.assertEqual(rc, 1, out)

    def test_a_failed_prepare_step_stops_the_legs_with_the_same_prepare_step(self):
        battery = SEED_E0658.replace("compiler artifacts", "tool targo-trust").replace("`rustc_a`", "`some-battery`")
        rc, ran, record, out = self.run_gate({"ui-trust": (1, battery)}, prepare_fails=("ui-trust",))
        legs = record["legs"]
        self.assertEqual(rc, 1, out)
        self.assertTrue(legs["ui-trust"]["outcome"].startswith("FAIL (its prepare step"))
        self.assertEqual([b["build"] for b in legs["ui-trust"]["shared_build_failed"]], ["stage1-sysroot"])
        for leg_id in ("run-make-trust", "native-targo-tests"):
            self.assertNotIn(leg_id, ran)
            self.assertIn("ui-trust failed building the batteries-on stage-1 sysroot", legs[leg_id]["outcome"])
        self.assertIn("compiler-unit-tests", ran, "its own sysroot build is not the prepare step")
        # The same error outside the prepare step stops nothing.
        rc, ran, record, out = self.run_gate({"ui-trust": (1, battery)})
        self.assertNotIn("COULD NOT RUN", out)
        self.assertIn("run-make-trust", ran)

    def test_the_cited_error_is_the_failing_targets_own(self):
        _g, _sel, legs = self.legs()
        check = {l.id: l for l in legs}["compiler-check"]
        text = ("error[E0308]: mismatched types\n"
                "error: could not compile `rustc_a` (lib test) due to 1 previous error\n" + SEED_E0658)
        [(_b, _m, why)] = land_gate.shared_build_failures(text, check)
        self.assertIn("E0658", why)
        self.assertNotIn("E0308", why)

    def test_a_failure_without_shared_evidence_stops_nothing(self):
        # Control: the same exit with a test target's error (or any other
        # failure) is the leg's own; every other leg still runs.
        rc, ran, record, out = self.run_gate({"compiler-check": (1, SEED_E0658.replace("(lib)", "(lib test)"))})
        self.assertEqual(rc, 1, out)
        self.assertNotIn("COULD NOT RUN", out)
        for leg_id in ("ui-trust", "run-make-trust", "compiler-unit-tests", "native-targo-tests"):
            self.assertIn(leg_id, ran)

    def test_a_shared_failure_with_only_names_the_selected_legs_not_run(self):
        # --only keeps its meaning: an excluded leg is NOT RUN (--only), never
        # COULD NOT RUN; a requested one that needs the broken build is.
        rc, ran, record, out = self.run_gate({"compiler-check": (1, SEED_E0658)},
                                             only=["compiler-check", "ui-trust"])
        self.assertEqual(ran, ["compiler-check"])
        self.assertTrue(record["legs"]["ui-trust"]["outcome"].startswith("COULD NOT RUN"))
        self.assertEqual(record["legs"]["run-make-trust"]["outcome"], "NOT RUN (--only)")
        self.assertEqual(rc, 1, out)


class CacheOutcomeTests(unittest.TestCase):
    """EW-21: the cache holds every outcome under its complete key. Only a PASS
    serves, and never from a key a FAIL contradicts (a split key)."""

    def test_the_mutant_suite_runs_every_test_class(self):
        import re
        text = Path(__file__).read_text()
        defined = re.findall(r"^class (\w+)\(unittest\.TestCase\)", text, re.M)
        names = [c.__name__ for c in mutant_suite_cases()]
        self.assertEqual(sorted(names), sorted(defined))
        self.assertIn("CacheOutcomeTests", names)

    def setUp(self):
        tmp = tempfile.TemporaryDirectory(prefix="land-gate-outcomes.")
        self.addCleanup(tmp.cleanup)
        self.tmp = Path(tmp.name)
        patcher = mock.patch.object(land_gate, "common_dir", lambda: self.tmp)
        patcher.start()
        self.addCleanup(patcher.stop)

    def path(self, key):
        return land_gate.cache_dir() / f"{key}.json"

    def record_fail(self, key, **row):
        land_gate.cache_record(key, "FAIL", {"run": "failed-run", **row})

    def run_gate(self, logs=None, only=("tidy",), no_cache=False, prepare_fails=(), cancel_after_exit=False,
                 leg_runner=None, problems=None):
        """cmd_run over FailFastTests' fixture, with the real cache under this
        test's directory, so one run's records are the next run's cache.
        `cancel_after_exit`: a signal arrives once a leg's exit is observed
        (at the next source check), and cmd_run raises GateCancelled."""
        logs = logs or {}
        exited = []
        signalled = []

        def checkout_problem(*a, **kw):
            # One signal, delivered at the first source check after an exit;
            # the source check itself never raises (it runs git only).
            if cancel_after_exit and exited and not signalled:
                signalled.append(True)
                raise land_gate.GateCancelled(15)
            return problems(*a, **kw) if problems else None
        g = Fixture.graph()
        sel = ls.select(g, "base", ["weird/unknown.txt"])
        args = land_gate.argparse.Namespace(base="base", only=list(only), no_cache=no_cache, dry_run=False)
        ran = []

        def run_leg(leg, *a, **kw):
            ran.append(leg.id)
            rc, text = logs.get(leg.id, (0, f"{leg.id}: passed\n"))
            log = self.tmp / f"{leg.id}.log"
            log.write_text(text, encoding="utf-8")
            exited.append(leg.id)
            return rc, 1.0, str(log), leg.id in prepare_fails

        with contextlib.ExitStack() as stack:
            for name, value in (("git", lambda *a, **kw: ""), ("checkout_problem", checkout_problem),
                                ("compute", lambda *a, **kw: (g, sel, "base")),
                                ("toolchain_identity", lambda: {}), ("rustc_identity", lambda stage1=None: None),
                                ("config_identity", lambda: {}), ("push_hook_state", lambda *a, **kw: HOOK_ON),
                                ("stage1_key", lambda *a, **kw: "s1"), ("xpy_unready", lambda: None),
                                ("targo_unready", lambda leg: None),  # a faked leg runs no targo (round 5, D3)
                                ("run_leg", leg_runner or run_leg),
                                ("read_landing", lambda *a, **kw: stated(sel.changed))):
                stack.enter_context(mock.patch.object(land_gate, name, value))
            stack.enter_context(mock.patch.object(land_gate, "REPO_ROOT", Path(g.index.repo)))
            stack.enter_context(mock.patch.object(host_budget, "measure", return_value=host(28, 128, 100)))
            out = io.StringIO()
            with contextlib.redirect_stdout(out):
                rc = land_gate.cmd_run(args)
        records = sorted((self.tmp / "trust-land" / "runs").glob("*/record.json"), key=lambda p: p.stat().st_mtime_ns)
        return rc, ran, json.loads(records[-1].read_text(encoding="utf-8")), out.getvalue()

    # -- the accept rows --------------------------------------------------
    def test_a_fail_then_a_pass_under_one_key_serves_no_pass_and_names_the_split(self):
        rc, ran, record, out = self.run_gate({"tidy": (1, "tidy: red\n")})
        self.assertEqual(ran, ["tidy"])
        self.assertEqual(rc, 1, out)
        self.assertEqual(record["split_keys"], {}, "a FAIL alone contradicts nothing")
        [key_file] = land_gate.cache_dir().glob("*.json")
        key = key_file.stem
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key)], ["FAIL"])
        self.assertIsNone(land_gate.cache_lookup(key), "a FAIL never serves")

        # The same inputs pass: this run's PASS is fresh, and it splits the key.
        rc, ran, record, out = self.run_gate()
        self.assertEqual(ran, ["tidy"], "a FAIL alone serves nothing, so the leg runs")
        self.assertEqual(rc, 2, out)  # --only: PARTIAL
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key)], ["FAIL", "PASS"])
        self.assertEqual(list(record["split_keys"]), [key], out)
        self.assertIn(f"LAND-GATE: SPLIT KEY {key}: tidy: ", out)

        # Every later run with these inputs runs the leg and names the split.
        rc, ran, record, out = self.run_gate()
        self.assertEqual(ran, ["tidy"], "a key holding a PASS and a FAIL serves no PASS")
        self.assertNotIn("CACHED PASS", out)
        self.assertEqual(record["legs"]["tidy"]["outcome"], "PASS")
        self.assertEqual([row["key"] for row in record["legs"]["tidy"]["split_keys"]], [key])
        self.assertIn(f"SPLIT KEY {key} (tidy): 1 PASS", out)

    def test_control_a_pass_serves_a_later_run(self):
        self.run_gate()
        rc, ran, record, out = self.run_gate()
        self.assertEqual(ran, [], out)
        self.assertEqual(record["legs"]["tidy"]["outcome"], "CACHED PASS")
        self.assertEqual(record["split_keys"], {})
        self.assertNotIn("SPLIT KEY", out)

    def test_a_pass_then_a_fail_splits_too(self):
        land_gate.cache_store("K", {"run": "passed-run"})
        self.assertIsNotNone(land_gate.cache_lookup("K"))
        self.record_fail("K")
        self.assertIsNone(land_gate.cache_lookup("K"))
        why = land_gate.cache_split("K")
        self.assertIn("1 PASS (last passed-run) and 1 FAIL (last failed-run)", why)

    def test_no_cache_still_records_and_names_the_split(self):
        self.run_gate({"tidy": (1, "red\n")}, no_cache=True)
        rc, ran, record, out = self.run_gate(no_cache=True)
        self.assertEqual(ran, ["tidy"])
        self.assertEqual(len(record["split_keys"]), 1, out)

    def test_could_not_run_and_not_judged_never_serve(self):
        for verdict in ("COULD NOT RUN", "NOT JUDGED"):
            with self.subTest(verdict=verdict):
                key = verdict.replace(" ", "-")
                land_gate.cache_record(key, verdict, {"run": "r", "sysroot": ["s"]})
                self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key)], [verdict])
                self.assertIsNone(land_gate.cache_lookup(key))
                self.assertIsNone(land_gate.cache_lookup(key, ["s"]))
                self.assertIsNone(land_gate.cache_split(key), "no PASS here for it to contradict")
                # Nothing that did not judge contradicts a PASS beside it.
                land_gate.cache_store(key, {"run": "passed"})
                self.assertEqual(land_gate.cache_lookup(key)["run"], "passed")
                land_gate.cache_record(key, verdict, {"run": "later"})
                self.assertEqual(land_gate.cache_lookup(key)["verdict"], "PASS")

    def test_a_run_records_could_not_run_under_the_key_a_run_looks_up(self):
        seed_red = (1, SEED_E0658)
        rc, ran, record, out = self.run_gate({"compiler-check": seed_red}, only=("compiler-check", "native-targo-tests"))
        self.assertEqual(ran, ["compiler-check"], out)
        self.assertTrue(record["legs"]["native-targo-tests"]["outcome"].startswith("COULD NOT RUN"))
        rows = [r for f in land_gate.cache_dir().glob("*.json") for r in land_gate.cache_outcomes(f.stem)]
        self.assertEqual(sorted((r["leg"], r["verdict"]) for r in rows),
                         [("compiler-check", "FAIL"), ("native-targo-tests", "COULD NOT RUN")])
        # The next run looks that very key up, finds nothing to serve, and runs the leg.
        rc, ran, record, out = self.run_gate(only=("native-targo-tests",))
        self.assertEqual(ran, ["native-targo-tests"], "a COULD NOT RUN record is never served")
        self.assertEqual(sorted(r["verdict"] for f in land_gate.cache_dir().glob("*.json")
                                for r in land_gate.cache_outcomes(f.stem) if r["leg"] == "native-targo-tests"),
                         ["COULD NOT RUN", "PASS"], "the same key: the PASS lands beside it")

    def test_a_lane_that_judged_nothing_records_not_judged(self):
        rc, ran, record, out = self.run_gate({"tidy": (0, "SKIPPED: nothing here\n")})
        self.assertEqual(ran, ["tidy"])
        [key_file] = land_gate.cache_dir().glob("*.json")
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key_file.stem)], ["NOT JUDGED"])

    def test_an_unreadable_record_serves_nothing_even_after_a_pass(self):
        d = land_gate.cache_dir()
        d.mkdir(parents=True)
        for name, text in (("truncated", '{"key": "truncated", "out'),
                           ("other-key", json.dumps({"key": "elsewhere", "verdict": "PASS"})),
                           ("not-object", "[1]"),
                           # Review of EW-21: no key reaches a file from before
                           # it, and its one PASS is not a list of outcomes.
                           ("pass-only", json.dumps({"key": "pass-only", "verdict": "PASS", "run": "old"})),
                           ("no-rows", json.dumps({"key": "no-rows", "outcomes": []})),
                           ("bad-rows", json.dumps({"key": "bad-rows", "outcomes": [{"verdict": "GREEN"}]}))):
            with self.subTest(name=name):
                self.path(name).write_text(text, encoding="utf-8")
                self.assertIsNone(land_gate.cache_lookup(name))
                self.assertIn("unreadable", land_gate.cache_split(name))
                # It may have held a FAIL: a later PASS does not launder it.
                land_gate.cache_store(name, {"run": "fresh"})
                self.assertIsNone(land_gate.cache_lookup(name))
                self.assertIn("unreadable", land_gate.cache_split(name))
                self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(name)], ["UNREADABLE", "PASS"])

    def test_the_newest_pass_on_this_stage1_serves(self):
        land_gate.cache_store("K", {"run": "one", "sysroot": ["s1"]})
        land_gate.cache_store("K", {"run": "two", "sysroot": ["s2"]})
        self.assertEqual(land_gate.cache_lookup("K", ["s1"])["run"], "one")
        self.assertEqual(land_gate.cache_lookup("K", ["s2"])["run"], "two")
        self.assertEqual(land_gate.cache_lookup("K")["run"], "two")
        self.assertIsNone(land_gate.cache_lookup("K", ["s3"]))

    def test_a_fail_on_another_stage1_still_splits(self):
        land_gate.cache_store("K", {"run": "passed", "sysroot": ["s1"]})
        self.record_fail("K", sysroot=["s2"])
        self.assertIsNone(land_gate.cache_lookup("K", ["s1"]))

    # -- a run of several members -----------------------------------------
    def test_a_run_fail_contradicts_only_once_every_key_of_the_run_passes(self):
        for key in ("A", "B"):
            self.record_fail(key, run_keys=["A", "B"])
        land_gate.cache_store("A", {"run": "a-passed"})
        # B has not passed: it may be the member that failed, and A is not split.
        self.assertIsNone(land_gate.cache_split("A"))
        self.assertEqual(land_gate.cache_lookup("A")["run"], "a-passed")
        # Every member of the failed run now passes on the same inputs.
        land_gate.cache_store("B", {"run": "b-passed"})
        for key in ("A", "B"):
            with self.subTest(key=key):
                self.assertIsNone(land_gate.cache_lookup(key))
                self.assertIn("two answers", land_gate.cache_split(key))

    def test_a_member_fixed_since_its_run_failed_splits_nothing(self):
        # N's fix moves N's inputs: its PASS lands under a new key, so the old
        # key never passes and M, which did not change, is no split.
        for key in ("M", "N-old"):
            self.record_fail(key, run_keys=["M", "N-old"])
        land_gate.cache_store("M", {"run": "after-the-fix"})
        land_gate.cache_store("N-new", {"run": "after-the-fix"})
        self.assertEqual(land_gate.cache_lookup("M")["run"], "after-the-fix")
        self.assertIsNotNone(land_gate.cache_lookup("N-new"))
        self.assertIsNone(land_gate.cache_lookup("N-old"))

    def test_an_unreadable_key_of_the_run_counts_as_its_pass(self):
        # Review of EW-21: the record that may complete the contradiction is
        # read the worst way, as everywhere else.
        for key in ("A", "B"):
            self.record_fail(key, run_keys=["A", "B"])
            land_gate.cache_store(key, {"run": "passed"})
        self.assertIsNone(land_gate.cache_lookup("A"))
        for text in ("{truncated", ""):
            with self.subTest(text=text):
                self.path("B").write_text(text, encoding="utf-8")
                self.assertIsNone(land_gate.cache_lookup("A"), "a split key serves no PASS")
                self.assertIn("two answers", land_gate.cache_split("A"))
        # Before the other key ever passed, though, an unreadable one is the
        # only reason to call it split: still the worst reading.
        self.record_fail("C", run_keys=["C", "D"])
        land_gate.cache_store("C", {"run": "passed"})
        self.assertIsNotNone(land_gate.cache_lookup("C"), "D never passed: C is no split")

    def test_a_narrowed_compiler_unit_run_files_its_fail_under_every_key(self):
        # Review of EW-21: check_compiler_unit_tests.sh only ADDS --also to the
        # suites its diff selects, so a member a PASS answered for may run, and
        # fail, inside the narrowed run. A log that does not say what ran
        # files the FAIL under every key.
        self.run_gate(only=("compiler-unit-tests",))
        keys = sorted(f.stem for f in land_gate.cache_dir().glob("*.json"))
        self.assertGreater(len(keys), 1, "the fixture has several compiler members")
        missed, *kept = keys
        self.path(missed).unlink()
        rc, ran, record, out = self.run_gate({"compiler-unit-tests": (1, "red\n")}, only=("compiler-unit-tests",))
        self.assertEqual(ran, ["compiler-unit-tests"], out)
        for key in keys:
            rows = land_gate.cache_outcomes(key)
            self.assertEqual(rows[-1]["verdict"], "FAIL", key)
            self.assertEqual(sorted(rows[-1]["run_keys"]), keys)
        for key in kept:
            self.assertIsNotNone(land_gate.cache_lookup(key), "its PASS stands until every key of that run passes")
        # The next run would complete that FAIL with its own PASS of `missed`:
        # it serves none of them (review of EW-21) and runs every member again,
        # and the split it completes is named.
        rc, ran, record, out = self.run_gate(only=("compiler-unit-tests",))
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(missed)], ["FAIL", "PASS"])
        self.assertNotIn("cached_members", record["legs"]["compiler-unit-tests"], out)
        for key in kept:
            self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key)], ["PASS", "FAIL", "PASS"])
            self.assertIn(key, record["split_keys"], out)

    def test_a_compiler_unit_fail_names_only_the_members_the_script_ran(self):
        # Review of EW-21: the script prints its scope before it runs; a
        # reached member it neither touched nor was asked to run never ran.
        self.run_gate(only=("compiler-unit-tests",))
        members = {land_gate.cache_outcomes(f.stem)[0]["member"]: f.stem for f in land_gate.cache_dir().glob("*.json")}
        crates = sorted(m for m in members if m != land_gate.RUN_MAKE_MEMBER)
        self.assertGreater(len(crates), 1, "the fixture has several compiler members")
        missed, touched, *untouched = crates
        self.path(members[missed]).unlink()
        log = f"in scope against base:\n  {missed}\n  {touched}\nerror: a test failed\n"
        self.run_gate({"compiler-unit-tests": (1, log)}, only=("compiler-unit-tests",))
        fail = land_gate.cache_outcomes(members[missed])[-1]
        self.assertEqual(fail["verdict"], "FAIL")
        # What ran: the missed member, the one its diff touched, and the
        # run-make member, which always runs here (its PASS names a stage 1).
        named = {members[missed], members[touched]} | (
            {members[land_gate.RUN_MAKE_MEMBER]} if land_gate.RUN_MAKE_MEMBER in members else set())
        self.assertEqual(set(fail["run_keys"]), named)
        self.assertEqual(land_gate.cache_outcomes(members[touched])[-1]["verdict"], "FAIL")
        self.assertTrue(untouched, "the fixture has a member the script did not run")
        for m in untouched:
            self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(members[m])], ["PASS"],
                             f"{m} never ran in the failed run")
        self.assertEqual(land_gate.unit_scope("in scope against b:\n  compiler/x\n  run-make at stage 1: t\nend\n"),
                         {"compiler/x", land_gate.RUN_MAKE_MEMBER})
        self.assertIsNone(land_gate.unit_scope("REFUSE: cannot resolve base\n"))

    def test_a_run_never_serves_a_key_its_own_pass_will_split(self):
        # Review of EW-21: A and B failed in one run; A has passed since, B not.
        # A run that serves A and passes B completes that contradiction: A
        # must run too, and the split it completes must be named.
        self.run_gate(only=("crates-tests",))
        members = {land_gate.cache_outcomes(f.stem)[0]["member"]: f.stem for f in land_gate.cache_dir().glob("*.json")}
        self.assertGreater(len(members), 2, "the fixture has several members")
        (a_member, a), (b_member, b) = sorted(members.items())[:2]
        self.path(b).unlink()
        self.record_fail(a, run_keys=[a, b])
        self.record_fail(b, run_keys=[a, b])
        self.assertIsNotNone(land_gate.cache_lookup(a), "alone, A's PASS serves: B holds no PASS yet")
        self.assertIsNone(land_gate.cache_lookup(a, assumed=frozenset({b})))
        rc, ran, record, out = self.run_gate(only=("crates-tests",))
        self.assertEqual(ran, ["crates-tests"], out)
        entry = record["legs"]["crates-tests"]
        self.assertNotIn(a_member, entry.get("cached_members", []), out)
        self.assertNotIn(b_member, entry.get("cached_members", []), out)
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(a)], ["PASS", "FAIL", "PASS"])
        self.assertIn(a, record["split_keys"], out)

    def test_a_failed_stage1_prepare_fails_only_the_keys_that_name_it(self):
        # Review of EW-21: the crates leg's stage-1 prepare failed, so no
        # member's tests ran; a member whose key names no stage-1 input could
        # not run, and its later PASS must not read as a split.
        with mock.patch.object(land_gate, "TRUST_RUSTC_RESOLVER", "crates/leaf"):
            rc, ran, record, out = self.run_gate({"crates-tests": (1, "error: could not compile\n")},
                                                 only=("crates-tests",), prepare_fails=("crates-tests",))
            self.assertEqual(rc, 1, out)
            self.assertTrue(record["legs"]["crates-tests"]["outcome"].startswith("FAIL"), out)
            rows = {land_gate.cache_outcomes(f.stem)[0]["member"]: land_gate.cache_outcomes(f.stem)[0]
                    for f in land_gate.cache_dir().glob("*.json")}
            stage1 = {m for m in rows if m in ("crates/leaf", "crates/tester")}
            self.assertTrue(stage1 and set(rows) - stage1, rows)
            for m, row in rows.items():
                self.assertEqual(row["verdict"], "FAIL" if m in stage1 else "COULD NOT RUN", m)
            fail_keys = {f.stem for f in land_gate.cache_dir().glob("*.json") if land_gate.cache_outcomes(f.stem)[0]["member"] in stage1}
            for key in fail_keys:
                self.assertEqual(set(land_gate.cache_outcomes(key)[0]["run_keys"]), fail_keys)
            # The retry passes: only the keys that named the stage 1 are split.
            rc, ran, record, out = self.run_gate(only=("crates-tests",))
        self.assertEqual({k for k in record["split_keys"]}, fail_keys, out)

    def test_a_signal_after_a_red_exit_still_records_its_fail(self):
        # Review of EW-21: GateCancelled is a BaseException, and cache_record
        # refused every row once a cancellation was pending, so a red exit the
        # gate had observed left no FAIL, and a later PASS served unsplit.
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate({"tidy": (1, "tidy: red\n")}, cancel_after_exit=True)
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual(row["verdict"], "FAIL")
        self.assertEqual(row["why"], "exit 1, recorded unjudged: the gate was cancelled")
        rc, ran, record, out = self.run_gate()
        self.assertEqual(list(record["split_keys"]), [key_file.stem], out)
        # A green exit under the same signal publishes nothing.
        land_gate.cache_dir().joinpath(f"{key_file.stem}.json").unlink()
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate(cancel_after_exit=True)
        self.assertEqual(list(land_gate.cache_dir().glob("*.json")), [])

    def real_leg(self, script, grace=None, retire=None, exited=None):
        """A leg_runner for run_gate that runs the REAL run_leg on `script`."""
        real_run_leg = land_gate.run_leg

        def leg_runner(leg, log_dir, extra_env, governor):
            leg.command, leg.prepare = ["/bin/sh", "-c", script], None
            with contextlib.ExitStack() as stack:
                if grace is not None:
                    stack.enter_context(mock.patch.object(land_gate, "EXIT_DRAIN_GRACE_S", grace))
                if retire is not None:
                    stack.enter_context(mock.patch.object(land_gate._OwnedGroup, "retire", retire))
                if exited is not None:
                    stack.enter_context(mock.patch.object(land_gate._OwnedGroup, "exited", exited))
                return real_run_leg(leg, log_dir, extra_env, governor)
        return leg_runner

    def test_a_signal_while_a_red_exit_is_retired_still_records_its_fail(self):
        # Review of EW-1: a signal during the drain and group retire after the
        # leader's own red exit raised GateCancelled out of run_leg, and no FAIL
        # was recorded.
        retire = land_gate._OwnedGroup.retire

        def signalled_retire(group, cancellation, stop_signal=None, before_reap=None):
            if group.exited():
                os.kill(os.getpid(), signal.SIGTERM)
            return retire(group, cancellation, stop_signal, before_reap)
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate(leg_runner=self.real_leg("echo 'tidy: red'; exit 1", retire=signalled_retire))
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual((row["verdict"], row["why"]), ("FAIL", "exit 1, recorded unjudged: the gate was cancelled"))
        rc, ran, record, out = self.run_gate()
        self.assertEqual(list(record["split_keys"]), [key_file.stem], out)

    def test_a_signal_before_the_leg_exits_records_nothing(self):
        # Control: an exit the gate's own signal caused is no verdict.
        exited = land_gate._OwnedGroup.exited
        sent = []

        def signal_first(group):
            if not sent:
                sent.append(True)
                os.kill(os.getpid(), signal.SIGTERM)
            return exited(group)
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate(leg_runner=self.real_leg("sleep 5; exit 1", exited=signal_first))
        self.assertEqual(list(land_gate.cache_dir().glob("*.json")) if land_gate.cache_dir().is_dir() else [], [])

    def test_a_signal_as_the_legs_scope_closes_still_records_its_fail(self):
        # Review of EW-1 (second pass): a signal after _run_one's in-scope
        # check raised a GateCancelled with no exit from its final check.
        real = land_gate._cancellation_scope

        @contextlib.contextmanager
        def late():
            nested = land_gate._ACTIVE_CANCELLATION is not None
            with real() as state:
                yield state
                if nested:
                    os.kill(os.getpid(), signal.SIGTERM)
        with mock.patch.object(land_gate, "_cancellation_scope", late), self.assertRaises(land_gate.GateCancelled):
            self.run_gate(leg_runner=self.real_leg("echo 'tidy: red'; exit 1"))
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual((row["verdict"], row["why"]), ("FAIL", "exit 1, recorded unjudged: the gate was cancelled"))

    def test_an_exit_seen_after_the_cancellation_is_the_cancellations(self):
        # Review of EW-1 (second pass): a leader the same tree signal killed
        # was recorded as a FAIL of its own.
        exited = land_gate._OwnedGroup.exited
        sent = []

        def signal_with_the_exit(group):
            done = exited(group)
            if done and not sent:
                sent.append(True)
                os.kill(os.getpid(), signal.SIGTERM)
            return done
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate(leg_runner=self.real_leg("exit 1", exited=signal_with_the_exit))
        self.assertTrue(sent)
        self.assertEqual(list(land_gate.cache_dir().glob("*.json")) if land_gate.cache_dir().is_dir() else [], [])

    def test_an_echo_that_breaks_after_a_red_exit_still_records_its_fail(self):
        # Review of EW-1 (second pass): any failure after the observed exit
        # other than a retained pipe (here the gate's stdout reader is gone)
        # dropped the FAIL.
        write = land_gate._CancellableEcho.write

        def broken(echo, text):
            if "late" in text:
                raise BrokenPipeError(32, "Broken pipe")
            return write(echo, text)
        with mock.patch.object(land_gate._CancellableEcho, "write", broken), \
                self.assertRaisesRegex(land_gate.LegCleanupFailed, "Broken pipe"):
            self.run_gate(leg_runner=self.real_leg("(sleep .3; echo late) & echo 'tidy: red'; exit 1", grace=5))
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual((row["verdict"], row["why"]),
                         ("FAIL", "exit 1, recorded unjudged: BrokenPipeError after the exit"))

    def test_an_observed_exit_of_a_source_that_moved_is_not_judged(self):
        # Review of EW-1 (second pass): record_observed_exit skipped the
        # source check the run makes after every leg, so a red exit of an
        # edited tree was a FAIL under the commit's key.
        retire = land_gate._OwnedGroup.retire
        moved = []

        def signalled_retire(group, cancellation, stop_signal=None, before_reap=None):
            if group.exited() and not moved:
                moved.append(True)
                os.kill(os.getpid(), signal.SIGTERM)
            return retire(group, cancellation, stop_signal, before_reap)
        with self.assertRaises(land_gate.GateCancelled):
            self.run_gate(leg_runner=self.real_leg("echo 'tidy: red'; exit 1", retire=signalled_retire),
                          problems=lambda *a, **kw: "a tracked file changed" if moved else None)
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual((row["verdict"], row["why"]), ("NOT JUDGED", "the source changed"))

    def test_a_red_exit_whose_pipe_a_descendant_retains_still_records_its_fail(self):
        # Review of EW-1: the retained-pipe refusal was a plain RuntimeError,
        # so the leader's reaped red exit left no FAIL.
        with self.assertRaisesRegex(land_gate.LegCleanupFailed, "retained its output pipe"):
            self.run_gate(leg_runner=self.real_leg("sleep 5 & echo 'tidy: red'; exit 1", grace=.3))
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual((row["verdict"], row["why"]),
                         ("FAIL", "exit 1, recorded unjudged: a descendant retained its output pipe after the exit"))
        key_file.unlink()
        # A green exit under the same refusal publishes nothing.
        with self.assertRaises(land_gate.LegCleanupFailed):
            self.run_gate(leg_runner=self.real_leg("sleep 5 & echo 'tidy: ok'; exit 0", grace=.3))
        self.assertEqual(list(land_gate.cache_dir().glob("*.json")), [])

    def test_a_cleanup_that_fails_after_a_red_exit_still_records_its_fail(self):
        # Review of EW-21: the census timed out after the child exited red;
        # the gate refused and the observed FAIL was never recorded.
        def run_leg(leg, *a, **kw):
            exc = land_gate.LegCleanupFailed("landing child cleanup failed: [TimeoutExpired]", 1)
            exc.seconds, exc.log = 1.0, str(self.tmp / "red.log")
            raise exc
        with self.assertRaisesRegex(land_gate.LegCleanupFailed, "cleanup failed"):
            self.run_gate(leg_runner=run_leg)
        [key_file] = land_gate.cache_dir().glob("*.json")
        [row] = land_gate.cache_outcomes(key_file.stem)
        self.assertEqual(row["verdict"], "FAIL")
        self.assertEqual(row["why"], "exit 1, recorded unjudged: its cleanup failed after the exit")

    def test_an_exit_whose_output_is_still_in_flight_is_drained(self):
        # Review of EW-21: kqueue reported the exit before the child's pipe
        # closed, and the gate called a finished leg a retained pipe.
        # The exit is reported while the last line and EOF are still 300 ms away.
        proc = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(.3); print('last line', flush=True)"],
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        early = types.SimpleNamespace(process=proc, exited=lambda: True)
        fh, echo = io.StringIO(), io.StringIO()
        land_gate._stream_leg(early, types.SimpleNamespace(id="tidy"), fh, land_gate._Cancellation(), echo)
        self.assertIn("last line", fh.getvalue())
        proc.wait()
        holder = subprocess.Popen([sys.executable, "-c", "import time; print('x', flush=True); time.sleep(30)"],
                                  stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        try:
            with mock.patch.object(land_gate, "EXIT_DRAIN_GRACE_S", .3):
                with self.assertRaisesRegex(RuntimeError, "retained its output pipe"):
                    land_gate._stream_leg(types.SimpleNamespace(process=holder, exited=lambda: True),
                                          types.SimpleNamespace(id="tidy"), io.StringIO(),
                                          land_gate._Cancellation(), io.StringIO())
        finally:
            holder.kill()
            holder.wait()
            holder.stdout.close()
        proc.stdout.close()

    def test_a_slow_census_is_asked_again(self):
        calls = []

        def ps(argv, capture_output=True, text=True, timeout=None):
            calls.append(timeout)
            if len(calls) == 1:
                raise subprocess.TimeoutExpired(argv, timeout)
            return subprocess.CompletedProcess(argv, 0, "  42 42 S\n  43 7 S\n", "")
        with mock.patch.object(land_gate.subprocess, "run", ps):
            members = land_gate._OwnedGroup(types.SimpleNamespace(pid=42)).members()
        self.assertEqual(members, [(42, "S")])
        self.assertEqual(calls, list(land_gate.CENSUS_TIMEOUTS_S[:2]))

    def test_only_a_pass_waits_on_a_pending_cancellation(self):
        class Pending:
            def check(self):
                raise land_gate.GateCancelled(2)
        with mock.patch.object(land_gate, "_ACTIVE_CANCELLATION", Pending()):
            for verdict in ("FAIL", "NOT JUDGED", "COULD NOT RUN"):
                land_gate.cache_record("K", verdict, {"run": "r"})
            with self.assertRaises(land_gate.GateCancelled):
                land_gate.cache_store("K", {"run": "r"})
        self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes("K")], ["FAIL", "NOT JUDGED", "COULD NOT RUN"])

    def test_the_land_hooks_suite_records_its_fail_and_no_pass(self):
        # Review of EW-21: under `land` the full Targo suite runs in the hook;
        # its FAIL now splits a PASS a `run` stored under the same key.
        key = "cd" * 32
        land_gate.cache_store(key, {"run": "earlier-run"})

        def suite(root, check, record):
            record(land_gate.landing_targo.gate_keys(), "FAIL", "exit 101")
            return 1
        env = {land_gate.landing_targo.HEAD_ENV: "e" * 40, land_gate.landing_targo.KEYS_ENV: json.dumps([key])}
        with mock.patch.dict(os.environ, env), mock.patch.object(land_gate.landing_targo, "run_targo", suite):
            self.assertEqual(land_gate.cmd_landing_targo(None), 1)
        rows = land_gate.cache_outcomes(key)
        self.assertEqual([r["verdict"] for r in rows], ["PASS", "FAIL"])
        self.assertEqual(rows[-1]["run_keys"], [key])
        self.assertIsNone(land_gate.cache_lookup(key))
        self.assertIn("ordinary push of " + "e" * 40, land_gate.cache_split(key))

        def forged(root, check, record):
            record([key], "PASS", "forged")
        with mock.patch.dict(os.environ, env), mock.patch.object(land_gate.landing_targo, "run_targo", forged):
            with self.assertRaisesRegex(ValueError, "records no PASS"):
                land_gate.cmd_landing_targo(None)

    def test_the_land_hooks_fail_is_dated_by_the_date_its_suite_was_handed(self):
        # Review of EW-1: the hook dated its FAIL by its own clock, so a push
        # after UTC midnight filed [D+1, D+1] for a suite that ran under D, and
        # a gate dated D still served the PASS of D.
        key, day = "cd" * 32, datetime.date(2026, 11, 5)
        with gate_date_on(day):
            land_gate.cache_store(key, {"run": "plain-run-on-D"})

        def suite(root, check, record):
            record(land_gate.landing_targo.gate_keys(), "FAIL", "exit 101")
            return 1

        class AfterMidnight(datetime.datetime):
            @classmethod
            def now(cls, tz=None):
                return datetime.datetime(2026, 11, 6, 0, 30, tzinfo=datetime.timezone.utc)
        handed = {name: day.isoformat() for name in land_gate.DATE_ENV}
        env = {land_gate.landing_targo.HEAD_ENV: "e" * 40, land_gate.landing_targo.KEYS_ENV: json.dumps([key]),
               land_gate.landing_targo.INPUT_ENV: json.dumps(handed)}
        saved = list(land_gate._GATE_DATE)
        land_gate._GATE_DATE[:] = []  # the hook is a process of its own
        try:
            with mock.patch.dict(os.environ, env), mock.patch.object(land_gate.landing_targo, "run_targo", suite), \
                    mock.patch.object(land_gate.datetime, "datetime", AfterMidnight):
                self.assertEqual(land_gate.cmd_landing_targo(None), 1)
        finally:
            land_gate._GATE_DATE[:] = saved
        fail = land_gate.cache_outcomes(key)[-1]
        self.assertEqual(land_gate.outcome_window(fail), (day, datetime.date(2026, 11, 6)))
        with gate_date_on(day):
            self.assertIsNone(land_gate.cache_lookup(key))
            self.assertIsNotNone(land_gate.cache_split(key))
        # Without a well-formed declared date the row has no window: it meets every PASS.
        del env[land_gate.landing_targo.INPUT_ENV]
        with mock.patch.dict(os.environ, env), mock.patch.object(land_gate.landing_targo, "run_targo", suite):
            land_gate.cmd_landing_targo(None)
        self.assertIsNone(land_gate.outcome_window(land_gate.cache_outcomes(key)[-1]))

    def test_a_hook_suite_that_runs_past_midnight_is_dated_through_both_days(self):
        # Review of EW-1 (second pass): the window was read before the suite
        # ran, so a hook started at 23:59 on D whose suite failed at 00:20 on
        # D+1 (its ledgers reading D+1) filed [D, D], and a PASS of D+1 served.
        key, day, next_day = "ce" * 32, datetime.date(2026, 11, 5), datetime.date(2026, 11, 6)
        clock = [datetime.datetime(2026, 11, 5, 23, 59, tzinfo=datetime.timezone.utc)]

        class Clock(datetime.datetime):
            @classmethod
            def now(cls, tz=None):
                return clock[0]

        def suite(root, check, record):
            clock[0] = datetime.datetime(2026, 11, 6, 0, 20, tzinfo=datetime.timezone.utc)
            record(land_gate.landing_targo.gate_keys(), "FAIL", "exit 101")
            return 1
        handed = {name: day.isoformat() for name in land_gate.DATE_ENV}
        env = {land_gate.landing_targo.HEAD_ENV: "e" * 40, land_gate.landing_targo.KEYS_ENV: json.dumps([key]),
               land_gate.landing_targo.INPUT_ENV: json.dumps(handed)}
        saved = list(land_gate._GATE_DATE)
        land_gate._GATE_DATE[:] = []
        try:
            with mock.patch.dict(os.environ, env), mock.patch.object(land_gate.landing_targo, "run_targo", suite), \
                    mock.patch.object(land_gate.datetime, "datetime", Clock):
                self.assertEqual(land_gate.cmd_landing_targo(None), 1)
        finally:
            land_gate._GATE_DATE[:] = saved
        self.assertEqual(land_gate.outcome_window(land_gate.cache_outcomes(key)[-1]), (day, next_day))
        for when in (day, next_day):
            with gate_date_on(when):
                land_gate.cache_store(key, {"run": f"plain-run-on-{when}"})
                self.assertIsNone(land_gate.cache_lookup(key), when)
                self.assertIsNotNone(land_gate.cache_split(key), when)

    def test_two_gates_started_in_one_second_never_share_a_run(self):
        # Review of EW-21: worktrees share runs/, keyed by the second; one
        # gate's leg log was the other's, and so was every row's `run`.
        with mock.patch.object(land_gate.time, "strftime", return_value="20261106T000000"):
            self.run_gate()
            land_gate.cache_dir().joinpath(next(land_gate.cache_dir().glob("*.json")).name).unlink()
            self.run_gate()
        runs = sorted((self.tmp / "trust-land" / "runs").iterdir())
        self.assertEqual([r.name for r in runs], ["20261106T000000", "20261106T000000.002"])
        self.assertTrue(all((r / "record.json").is_file() for r in runs))
        rows = land_gate.cache_outcomes(next(land_gate.cache_dir().glob("*.json")).stem)
        self.assertEqual([r["run"] for r in rows], [str(runs[1])])

