    def test_every_unjudged_exit_is_recorded_under_the_key_a_later_run_uses(self):
        # Review of EW-21: no test reached the NOT JUDGED rows of cmd_run.
        for leg, rc in (("tidy", 2), ("crates-tests", 3)):
            with self.subTest(leg=leg, rc=rc):
                for f in land_gate.cache_dir().glob("*.json") if land_gate.cache_dir().is_dir() else []:
                    f.unlink()
                rc_gate, ran, record, out = self.run_gate({leg: (rc, "not judged\n")}, only=(leg,))
                self.assertEqual(record["legs"][leg]["outcome"], "NOT JUDGED", out)
                rows = {f.stem: land_gate.cache_outcomes(f.stem) for f in land_gate.cache_dir().glob("*.json")}
                self.assertTrue(rows)
                for key, outcomes in rows.items():
                    self.assertEqual([(r["verdict"], r["why"]) for r in outcomes], [("NOT JUDGED", f"exit {rc}")])
                self.run_gate(only=(leg,))
                for key in rows:
                    self.assertEqual([r["verdict"] for r in land_gate.cache_outcomes(key)], ["NOT JUDGED", "PASS"])
        for f in land_gate.cache_dir().glob("*.json"):
            f.unlink()
        # The source changed while tidy ran: its exit is not this tree's.
        calls = []

        def changed_after_the_run(*a, **kw):
            calls.append(a)
            return "the checkout moved" if len(calls) == 3 else None
        rc_gate, ran, record, out = self.run_gate({"tidy": (1, "red\n")}, problems=changed_after_the_run)
        self.assertEqual(record["legs"]["tidy"]["outcome"], "NOT JUDGED (source changed)", out)
        [f] = land_gate.cache_dir().glob("*.json")
        self.assertEqual([(r["verdict"], r["why"]) for r in land_gate.cache_outcomes(f.stem)],
                         [("NOT JUDGED", "the source changed")])

