        missed, *kept = keys
        self.path(missed).unlink()
        rc, ran, record, out = self.run_gate(only=("crates-tests",))
        self.assertEqual(ran, ["crates-tests"], out)
        self.assertEqual(len(land_gate.cache_outcomes(missed)), 1)
        for key in kept:
            self.assertEqual(len(land_gate.cache_outcomes(key)), 1, "no PASS without a run behind it")

