    def test_concurrent_writers_lose_no_outcome(self):
        def write(index):
            for n in range(10):
                land_gate.cache_record("K", "FAIL", {"run": f"{index}-{n}"})
        threads = [threading.Thread(target=write, args=(i,)) for i in range(6)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        self.assertEqual(sorted(r["run"] for r in land_gate.cache_outcomes("K")),
                         sorted(f"{i}-{n}" for i in range(6) for n in range(10)))

