    def test_unpopulated_gitlink_cannot_hide_consumer_manifests(self):
        root, _head = self.repository()
        source = root / "source"
        source.mkdir()
        make_repo(source, {"Cargo.toml": '[package]\nname="dep"\nversion="0.1.0"\n'}, symlinks={})
        git_in(root, "-c", "protocol.file.allow=always", "submodule", "add", "-q", str(source), "first-party/dep")
        git_in(root, "commit", "-qam", "dependency")
